-- Generated by scripts/import_enfermeria_gpc_questions.py
-- Sources: three ECOTEC teaching banks based on MSP Ecuador obstetric GPCs.
-- Questions: 220

insert into public.questions (
  id,
  question_text,
  option_a,
  option_b,
  option_c,
  option_d,
  correct_option,
  explanation,
  category,
  difficulty
) values
  ('2c8a2af7-d7eb-5561-aa1f-65b619df4b13', 'Según la GPC del MSP de Ecuador sobre ruptura prematura de membranas pretérmino, ¿cómo se define la ruptura prematura de membranas pretérmino (RPMP)?', 'La solución de continuidad o pérdida de la integridad de las membranas corioamnióticas que se produce desde las 20 semanas de gestación hasta antes del inicio del trabajo de parto.', 'La ruptura de membranas que ocurre exclusivamente durante el trabajo de parto activo.', 'La ruptura de membranas que se presenta únicamente después de las 37 semanas de gestación.', 'La pérdida de líquido amniótico que ocurre solamente en el puerperio inmediato.', 'A', 'La guía define la RPMP como la solución de continuidad o pérdida de la integridad de las membranas corioamnióticas que se produce desde las 20 semanas de gestación hasta antes del inicio del trabajo de parto.', 'Enfermería - Cuidados de la Mujer, Recién Nacido, Niño y Adolescente', 'GPC MSP Ecuador – RPMP 2015'),
  ('7995deaa-4fe3-571c-a537-6524b437670d', '¿Cómo se denomina la ruptura prematura de membranas cuando el tiempo de latencia es mayor de 24 horas?', 'RPMP lejos de término.', 'Ruptura prolongada.', 'RPMP previable.', 'RPMP cerca de término.', 'B', 'La guía define la ruptura prolongada como el tiempo de latencia mayor de 24 horas, entendiendo por período de latencia el tiempo transcurrido entre la ruptura de membranas y el inicio del trabajo de parto.', 'Enfermería - Cuidados de la Mujer, Recién Nacido, Niño y Adolescente', 'GPC MSP Ecuador – RPMP 2015'),
  ('c812f837-c907-52dc-800b-d76468203a7b', 'Gestante de 29 semanas y 4 días presenta salida de líquido por vía vaginal, confirmada mediante examen especular. De acuerdo con la clasificación de la GPC del MSP de Ecuador sobre ruptura prematura de membranas pretérmino, ¿en qué categoría se ubica esta paciente?', 'RPMP previable.', 'RPMP cerca de término.', 'RPMP lejos de término.', 'Ruptura prolongada.', 'C', 'Según la Tabla 1 de clasificación de la guía, la RPMP "lejos de término" corresponde al rango entre 24 y 34 semanas 6 días de gestación. Una paciente de 29 semanas y 4 días se ubica dentro de este rango.', 'Enfermería - Cuidados de la Mujer, Recién Nacido, Niño y Adolescente', 'GPC MSP Ecuador – RPMP 2015'),
  ('d5133f6b-6c3e-561a-b5db-242e111e22e5', 'Gestante con sospecha clínica de RPMP acude a valoración inicial. Según las recomendaciones de la GPC del MSP de Ecuador sobre ruptura prematura de membranas pretérmino sobre el diagnóstico en mujeres con sospecha de RPMP, ¿cuál es la conducta inicial recomendada?', 'Realizar tacto vaginal de forma inmediata para determinar dilatación cervical.', 'Indicar amniocentesis de rutina como primer paso diagnóstico.', 'Solicitar de inmediato una resonancia magnética fetal para confirmar el diagnóstico.', 'Efectuar el diagnóstico mediante la historia clínica y observación de la salida de líquido amniótico por el canal cervical con especuloscopia, evitando el tacto vaginal.', 'D', 'La guía recomienda que el diagnóstico se efectúe mediante la historia clínica y la observación de la salida de líquido amniótico por el canal cervical con especuloscopia, y recomienda evitar los tactos vaginales cuando se sospecha RPMP.', 'Enfermería - Cuidados de la Mujer, Recién Nacido, Niño y Adolescente', 'GPC MSP Ecuador – RPMP 2015'),
  ('d30f55c5-efd6-50b0-bf10-9518a3beabc9', 'Gestante con salida evidente y visible de líquido amniótico a través del canal cervical durante la especuloscopia. Según la GPC del MSP de Ecuador sobre ruptura prematura de membranas pretérmino, ¿se recomienda realizar la prueba de nitrazina en este escenario?', 'No se recomienda la evaluación con prueba de nitrazina ante la presencia de salida de líquido amniótico visible a través del canal cervical.', 'Sí, pero únicamente si la paciente cursa con oligohidramnios.', 'La guía no menciona la prueba de nitrazina como parte del diagnóstico de RPMP.', 'Sí, siempre debe realizarse nitrazina para confirmar cualquier caso de RPMP.', 'A', 'La guía establece explícitamente que no se recomienda la evaluación con prueba de nitrazina ante la presencia de salida de líquido amniótico a través del canal cervical, ya que en ese escenario el diagnóstico clínico visual ya es suficiente.', 'Enfermería - Cuidados de la Mujer, Recién Nacido, Niño y Adolescente', 'GPC MSP Ecuador – RPMP 2015'),
  ('37931b71-6372-5596-b1d0-5eb9a7b06f89', 'Según la GPC del MSP de Ecuador sobre ruptura prematura de membranas pretérmino, ¿cuál es la sensibilidad y especificidad reportadas para la proteína alfa microglobulina-1 placentaria (PAMG-1) en fluido vaginal como prueba diagnóstica de RPMP?', 'Sensibilidad del 70% y especificidad del 75%.', 'Sensibilidad cercana al 99% y especificidad que varía del 87,5% al 100%.', 'Sensibilidad y especificidad no determinadas por la guía.', 'Sensibilidad del 50% y especificidad del 60%.', 'B', 'La guía indica que la proteína alfa microglobulina-1 placentaria (PAMG-1) en fluido vaginal presenta una sensibilidad cercana al 99% y una especificidad que varía del 87,5% al 100%, como evidencia de nivel E-2a.', 'Enfermería - Cuidados de la Mujer, Recién Nacido, Niño y Adolescente', 'GPC MSP Ecuador – RPMP 2015'),
  ('1c20cf9f-9a33-5981-ad02-84cc63874167', 'Gestante presenta flujo genital blanco amarillento asociado a prurito, sin evidencia de salida de líquido amniótico. Según el diagnóstico diferencial descrito en la GPC del MSP de Ecuador sobre ruptura prematura de membranas pretérmino, ¿con cuál entidad se corresponde este cuadro?', 'Incontinencia urinaria.', 'Ruptura prematura de membranas.', 'Leucorrea.', 'Eliminación de tapón mucoso.', 'C', 'La guía describe la leucorrea, dentro del diagnóstico diferencial de la RPM, como flujo genital blanco amarillento infeccioso asociado con prurito, lo cual coincide exactamente con el cuadro descrito.', 'Enfermería - Cuidados de la Mujer, Recién Nacido, Niño y Adolescente', 'GPC MSP Ecuador – RPMP 2015'),
  ('16f3b3bf-211a-592d-be59-94d86c55bfb4', 'Gestante de 21 semanas presenta ruptura prematura de membranas confirmada, con todos los estudios diagnósticos realizados. Según la GPC del MSP de Ecuador sobre ruptura prematura de membranas pretérmino, ¿cuál es la conducta recomendada en este caso?', 'Manejo expectante hospitalario con maduración pulmonar y antibioticoterapia, igual que en RPMP lejos de término.', 'Manejo expectante prolongado en el domicilio hasta alcanzar la viabilidad fetal.', 'Amnioinfusión transabdominal inmediata para prevenir hipoplasia pulmonar.', 'El manejo expectante no se justifica dado el pronóstico neonatal desfavorable y el riesgo materno elevado; se recomienda la interrupción del embarazo.', 'D', 'La guía establece que en embarazos menores a 24 semanas o previables, el manejo expectante no se justifica una vez confirmado el diagnóstico mediante todos los estudios disponibles, por lo que la interrupción del embarazo es recomendada en virtud del pronóstico neonatal desfavorable y el riesgo materno elevado.', 'Enfermería - Cuidados de la Mujer, Recién Nacido, Niño y Adolescente', 'GPC MSP Ecuador – RPMP 2015'),
  ('fea74ae0-cbfc-5e8e-8472-c2410ffafb3c', 'Gestante de 30 semanas con RPMP confirmada, sin contraindicaciones maternas ni fetales para continuar el embarazo. Según la GPC del MSP de Ecuador sobre ruptura prematura de membranas pretérmino, ¿cuál es el manejo recomendado en este caso?', 'Manejo expectante hospitalario con maduración pulmonar fetal y antibioticoterapia profiláctica.', 'Manejo expectante ambulatorio en el domicilio de la paciente.', 'Terminación inmediata del embarazo por cesárea.', 'Amniocentesis de rutina como primera medida antes de cualquier otra intervención.', 'A', 'La guía recomienda que en embarazos entre 24 a 34 semanas 6 días, la conducta sea el manejo expectante con maduración pulmonar fetal y antibioticoterapia profiláctica para mejorar el pronóstico neonatal y disminuir la morbimortalidad materna; además, señala que las pacientes con RPMP lejos de término deben manejarse en forma expectante si no existen contraindicaciones maternas o fetales.', 'Enfermería - Cuidados de la Mujer, Recién Nacido, Niño y Adolescente', 'GPC MSP Ecuador – RPMP 2015'),
  ('a3cf0c51-44e8-5fbb-af04-037a5456a45b', 'Gestante con RPMP que alcanza las 35 semanas de gestación, sin signos de infección ni compromiso fetal. Según la GPC del MSP de Ecuador sobre ruptura prematura de membranas pretérmino, ¿cuál es la conducta recomendada a partir de esta edad gestacional?', 'Continuar el manejo expectante indefinidamente, ya que el beneficio del manejo expectante no tiene límite de edad gestacional.', 'Se recomienda la terminación del embarazo a toda RPMP que se presenta a partir de la semana 35.', 'Realizar amnioinfusión transvaginal para prevenir complicaciones fetales antes de decidir la vía del parto.', 'Iniciar tocolisis profiláctica para prolongar el embarazo el mayor tiempo posible.', 'B', 'La guía recomienda la terminación del embarazo a toda RPMP que se presenta a partir de la semana 35, señalando que el beneficio del manejo expectante en la RPMP tiene su límite al cumplir la semana 35, sin diferencia significativa en la morbilidad respecto a los nacimientos en la semana 36 o más.', 'Enfermería - Cuidados de la Mujer, Recién Nacido, Niño y Adolescente', 'GPC MSP Ecuador – RPMP 2015'),
  ('9ca4f57f-324b-53dc-a844-734d41498471', 'Gestante de 28 semanas con RPMP y riesgo de parto pretérmino dentro de los siguientes siete días. Según la GPC del MSP de Ecuador sobre ruptura prematura de membranas pretérmino, ¿cuál es el esquema de corticoides recomendado como tratamiento de primera elección?', 'Dexametasona 12 mg intravenosa en dosis única.', 'Hidrocortisona 100 mg intramuscular cada 24 horas por cuatro dosis.', 'Betametasona 12 mg intramuscular glútea cada 24 horas, por un total de dos dosis.', 'Betametasona 6 mg intramuscular cada 12 horas por dos dosis.', 'C', 'La guía recomienda como tratamiento de primera elección la Betametasona 12 mg intramuscular glútea cada 24 horas, por un total de dos dosis, con Dexametasona 6 mg intramuscular cada 12 horas por cuatro dosis como alternativa.', 'Enfermería - Cuidados de la Mujer, Recién Nacido, Niño y Adolescente', 'GPC MSP Ecuador – RPMP 2015'),
  ('708b0152-86d9-5264-99f7-5206956dee36', 'Un médico plantea administrar dos cursos completos de corticoides antenatales, repetidos cada semana, a una gestante con RPMP de 27 semanas que se mantiene sin parto. Según la evidencia presentada en la GPC del MSP de Ecuador sobre ruptura prematura de membranas pretérmino, ¿es correcta esta conducta?', 'Sí, siempre que se utilicen dosis menores en cada curso adicional.', 'Sí, los esquemas múltiples de corticoides mejoran el pronóstico neonatal en todos los casos.', 'La guía no aborda el tema de los esquemas múltiples de corticoides antenatales.', 'No. Los cursos múltiples no han demostrado beneficio neonatal frente a un curso único y se asocian con restricción del crecimiento y muerte neonatal en fetos menores de 28 semanas.', 'D', 'La guía señala explícitamente que no se recomiendan esquemas múltiples de esteroides antenatales, ya que existe evidencia de que, en humanos, se reporta mayor incidencia de restricción de crecimiento intrauterino (RCIU) y muerte neonatal en fetos menores de 28 semanas de edad gestacional, sin demostrarse ningún beneficio neonatal en comparación con un curso único.', 'Enfermería - Cuidados de la Mujer, Recién Nacido, Niño y Adolescente', 'GPC MSP Ecuador – RPMP 2015'),
  ('b678886b-4c61-5e7e-aede-259f4d3a7ce2', 'Gestante de 27 semanas con RPMP en manejo expectante hospitalario, sin alergias medicamentosas conocidas. Según el esquema recomendado por la GPC del MSP de Ecuador sobre ruptura prematura de membranas pretérmino, ¿cuál es la antibioticoterapia correcta para prolongar la latencia y reducir la infección materna y perinatal?', 'Ampicilina intravenosa y eritromicina vía oral durante 48 horas, seguido de cinco días con amoxicilina y eritromicina vía oral.', 'Amoxicilina + ácido clavulánico vía oral durante siete días.', 'Penicilina cristalina intravenosa en dosis única, sin continuar tratamiento posterior.', 'Ciprofloxacino intravenoso durante 10 días.', 'A', 'La guía recomienda durante el manejo expectante de la RPMP un curso de 48 horas de antibióticos: ampicilina intravenosa y eritromicina vía oral, seguido de cinco días con amoxicilina y eritromicina vía oral, esquema que prolonga la latencia del embarazo y reduce la infección materna y perinatal, así como la morbilidad neonatal asociada a prematuridad.', 'Enfermería - Cuidados de la Mujer, Recién Nacido, Niño y Adolescente', 'GPC MSP Ecuador – RPMP 2015'),
  ('1940a5fc-401a-56e4-ad2f-7bc5ede2590d', 'Gestante con RPMP y alergia documentada a la penicilina. Según la GPC del MSP de Ecuador sobre ruptura prematura de membranas pretérmino, ¿cuál es una alternativa antibiótica adecuada para la profilaxis en este caso?', 'No existe alternativa antibiótica segura para pacientes alérgicas a la penicilina según la guía.', 'Eritromicina 250 mg vía oral cada 6 horas durante 10 días posteriores al diagnóstico de RPMP, o clindamicina 900 mg intravenosa cada ocho horas por siete días.', 'Ampicilina intravenosa en las mismas dosis que en pacientes no alérgicas.', 'Amoxicilina + ácido clavulánico vía oral por siete días.', 'B', 'La guía indica que, como alternativa o en caso de pacientes alérgicas a la penicilina, para profilaxis se recomienda eritromicina 250 mg vía oral cada 6 horas durante 10 días posteriores al diagnóstico de RPMP, o clindamicina 900 mg intravenosa cada ocho horas por siete días.', 'Enfermería - Cuidados de la Mujer, Recién Nacido, Niño y Adolescente', 'GPC MSP Ecuador – RPMP 2015'),
  ('08b9562d-bd5c-585a-842a-5635c28613ba', 'Según la GPC del MSP de Ecuador sobre ruptura prematura de membranas pretérmino, ¿por qué no se recomienda la combinación de amoxicilina + ácido clavulánico en el tratamiento profiláctico de la RPMP?', 'Porque no tiene ningún efecto sobre la flora bacteriana materna.', 'Porque incrementa el riesgo de hipoplasia pulmonar fetal.', 'Porque está asociada a un incremento en el número de recién nacidos con enterocolitis necrotizante.', 'Porque disminuye la efectividad de la maduración pulmonar fetal.', 'C', 'La guía indica que el uso de amoxicilina + ácido clavulánico en el tratamiento profiláctico de la RPMP está asociado a un incremento en el número de recién nacidos con enterocolitis necrotizante, razón por la cual no se recomienda esta combinación.', 'Enfermería - Cuidados de la Mujer, Recién Nacido, Niño y Adolescente', 'GPC MSP Ecuador – RPMP 2015'),
  ('aa010ba6-da8b-5285-aeaa-a9843882f225', 'Gestante con RPMP sin actividad uterina, en manejo expectante lejos de término. Según la GPC del MSP de Ecuador sobre ruptura prematura de membranas pretérmino, ¿se recomienda el uso de tocolisis profiláctica en este caso?', 'La guía recomienda tocolisis solo en la RPMP previable.', 'Sí, únicamente si se combina con amnioinfusión transvaginal.', 'Sí, la tocolisis profiláctica está indicada en toda paciente con RPMP para prolongar el embarazo.', 'No se recomienda la tocolisis profiláctica en mujeres con RPMP sin actividad uterina, ya que este tratamiento no mejora significativamente el resultado perinatal.', 'D', 'La guía establece que no se recomienda la tocolisis profiláctica en mujeres con RPMP, porque este tratamiento no mejora significativamente el resultado perinatal, y específicamente que no se recomienda la tocolisis profiláctica en mujeres con RPMP sin actividad uterina.', 'Enfermería - Cuidados de la Mujer, Recién Nacido, Niño y Adolescente', 'GPC MSP Ecuador – RPMP 2015'),
  ('f5f3389d-2468-5a94-abd2-d86740a85582', 'Gestante con RPMP y oligohidramnios en el segundo trimestre; se plantea el uso de sellantes de fibrina. Según la GPC del MSP de Ecuador sobre ruptura prematura de membranas pretérmino, ¿cuál es la recomendación respecto al uso de fibrinas en este escenario?', 'No se recomienda el uso de sellantes de fibrina como tratamiento de rutina del oligohidramnios en el segundo trimestre causado por RPMP.', 'La guía no menciona el uso de fibrinas en el manejo de la RPMP.', 'Se recomienda su uso rutinario para sellar el sitio de ruptura y restaurar el volumen de líquido amniótico.', 'Se recomienda únicamente en combinación con amnioinfusión transabdominal.', 'A', 'La guía indica explícitamente que no se recomienda el uso de sellantes de fibrina como un tratamiento de rutina de oligohidramnios en el segundo trimestre causado por RPMP.', 'Enfermería - Cuidados de la Mujer, Recién Nacido, Niño y Adolescente', 'GPC MSP Ecuador – RPMP 2015'),
  ('237a97c9-1efe-5be4-8df1-d66c19203b42', 'Durante la labor de parto de una paciente con RPMP, se plantea realizar amnioinfusión transvaginal para mejorar el bienestar fetal. Según la GPC del MSP de Ecuador sobre ruptura prematura de membranas pretérmino, ¿es correcta esta intervención?', 'Sí, la amnioinfusión transvaginal está recomendada de rutina durante la labor de parto en mujeres con RPMP.', 'No se recomienda la amnioinfusión transvaginal en el parto, en mujeres con RPMP.', 'Solo se recomienda si la paciente presenta corioamnionitis clínica.', 'Sí, especialmente si existe oligohidramnios severo confirmado por ecografía.', 'B', 'La guía establece explícitamente que no se recomienda la amnioinfusión transvaginal en el parto en mujeres con RPMP, ni tampoco su uso durante la labor de parto en general.', 'Enfermería - Cuidados de la Mujer, Recién Nacido, Niño y Adolescente', 'GPC MSP Ecuador – RPMP 2015'),
  ('ccd02f76-caa2-5a51-b64b-601f28ac4df0', 'Gestante de 36 semanas con RPMP que presenta en trabajo de parto evidencia de corioamnionitis y compromiso fetal. Según la GPC del MSP de Ecuador sobre ruptura prematura de membranas pretérmino, ¿cuál es la conducta correcta en este caso?', 'Continuar el manejo expectante con vigilancia estrecha, dado que aún no alcanza las 37 semanas.', 'Diferir la interrupción del embarazo hasta completar un ciclo adicional de corticoides.', 'Las pacientes con RPMP y evidencia de trabajo de parto, corioamnionitis, compromiso fetal, muerte fetal, desprendimiento normoplacentario, o de 35 semanas o más de edad gestacional requieren interrupción del embarazo.', 'Indicar tocolisis para detener el trabajo de parto y prolongar la gestación.', 'C', 'La guía establece que las pacientes con RPMP y evidencia de trabajo de parto, corioamnionitis, compromiso fetal, muerte fetal, desprendimiento normoplacentario, o de 35 semanas o más de edad gestacional, requieren interrupción del embarazo; el caso descrito, con 36 semanas, corioamnionitis y compromiso fetal, cumple estos criterios.', 'Enfermería - Cuidados de la Mujer, Recién Nacido, Niño y Adolescente', 'GPC MSP Ecuador – RPMP 2015'),
  ('9f8fd5b0-4003-5cf5-8620-71c3d14e4a9e', 'Una paciente con RPMP es diagnosticada en un establecimiento de primer nivel de atención. Según los criterios de referencia y contrarreferencia de la GPC del MSP de Ecuador sobre ruptura prematura de membranas pretérmino, ¿cuál es la conducta correcta?', 'Diferir la transferencia hasta que la paciente presente signos de corioamnionitis.', 'Referir únicamente si la paciente lo solicita expresamente.', 'Manejar a la paciente íntegramente en el primer nivel de atención, sin necesidad de referencia.', 'Se recomienda la transferencia inmediata al segundo o tercer nivel de las pacientes con RPMP que sean diagnosticadas en el primer nivel de atención.', 'D', 'La guía recomienda la transferencia inmediata al segundo o tercer nivel de las pacientes con RPMP que sean diagnosticadas en el primer nivel de atención, dado que el manejo expectante y el tratamiento de esta condición requieren capacidad resolutiva de mayor complejidad.', 'Enfermería - Cuidados de la Mujer, Recién Nacido, Niño y Adolescente', 'GPC MSP Ecuador – RPMP 2015'),
  ('9cdaad24-2df5-5c20-801d-e23b4fd479c4', 'Según la descripción general de la GPC del MSP de Ecuador sobre infección de vías urinarias en el embarazo, ¿cuál es la población blanco de la GPC del MSP de Ecuador sobre infección de vías urinarias en el embarazo?', 'Embarazadas', 'Mujeres en edad fértil, estén o no embarazadas', 'Mujeres en período de climaterio', 'Recién nacidos con sospecha de infección urinaria', 'A', 'La tabla de Descripción general de esta GPC establece explícitamente que la población blanco de la guía son las embarazadas.', 'Enfermería - Cuidados de la Mujer, Recién Nacido, Niño y Adolescente', 'GPC MSP Ecuador – IVU en el embarazo 2013'),
  ('62752fdd-5eee-5d53-ba0a-ca7d4aede4c1', 'Según la clasificación CIE-10 recogida en la GPC del MSP de Ecuador sobre infección de vías urinarias en el embarazo, ¿qué código corresponde a la infección del riñón en el embarazo?', 'O23.2', 'O23.0', 'O23.1', 'O23.5', 'B', 'La guía enumera la clasificación CIE-10: O23 Infección de las vías genitourinarias en el embarazo, O23.0 Infección del riñón en el embarazo, O23.1 Infección de la vejiga urinaria en el embarazo, O23.2 Infección de la uretra en el embarazo, entre otros.', 'Enfermería - Cuidados de la Mujer, Recién Nacido, Niño y Adolescente', 'GPC MSP Ecuador – IVU en el embarazo 2013'),
  ('eedef3e3-fdc6-510f-8607-f9eac8b9f4ab', 'Según la GPC del MSP de Ecuador sobre infección de vías urinarias en el embarazo, ¿a qué categoría de atención corresponde la GPC del MSP de Ecuador sobre infección de vías urinarias en el embarazo?', 'Exclusivamente atención domiciliaria sin intervención institucional', 'Exclusivamente tercer nivel de atención hospitalaria', 'Primer nivel de atención: diagnóstico y tratamiento, con acciones específicas en segundo y tercer nivel', 'Únicamente segundo nivel de atención ambulatoria especializada', 'C', 'La tabla de Descripción general de esta GPC señala que la categoría de la guía corresponde al primer nivel de atención para diagnóstico y tratamiento, con acciones específicas en segundo y tercer nivel.', 'Enfermería - Cuidados de la Mujer, Recién Nacido, Niño y Adolescente', 'GPC MSP Ecuador – IVU en el embarazo 2013'),
  ('b5775220-82ec-59a2-9dab-1847d72249bc', '¿Cuáles son las intervenciones y acciones consideradas por la GPC del MSP de Ecuador sobre infección de vías urinarias en el embarazo, según su descripción general?', 'Exclusivamente el manejo quirúrgico de las complicaciones renales', 'Solamente la vacunación materna contra infecciones urinarias', 'Únicamente el diagnóstico prenatal de malformaciones congénitas', 'Diagnóstico y tratamiento de las IVU, además de prevención, detección y tratamiento de sus complicaciones materno-neonatales.', 'D', 'La guía establece que las intervenciones y acciones consideradas son el diagnóstico y tratamiento de infección de vías urinarias en el embarazo, así como la prevención, detección y tratamiento de complicaciones materno-neonatales: pielonefritis, parto pretérmino y recién nacidos de peso bajo.', 'Enfermería - Cuidados de la Mujer, Recién Nacido, Niño y Adolescente', 'GPC MSP Ecuador – IVU en el embarazo 2013'),
  ('9439a334-ce6b-5992-a06a-1c1b9e7066f3', 'Según la sección ''Preguntas que responde la GPC del MSP de Ecuador sobre infección de vías urinarias en el embarazo'', ¿cuál de las siguientes es una de las preguntas clínicas que la GPC del MSP de Ecuador sobre infección de vías urinarias en el embarazo busca responder?', '¿Hay suficiente evidencia para indicar el tamizaje de detección de bacteriuria asintomática en la atención prenatal?', '¿Cuál es el manejo adecuado de la hipertensión gestacional severa?', '¿Cuáles son los criterios diagnósticos de diabetes gestacional?', '¿Cuál es el esquema de vacunación antitetánica en el embarazo?', 'A', 'Entre las preguntas que responde esta GPC se incluye explícitamente: ''¿Hay suficiente evidencia para indicar el tamizaje de detección de bacteriuria asintomática en la atención prenatal?''.', 'Enfermería - Cuidados de la Mujer, Recién Nacido, Niño y Adolescente', 'GPC MSP Ecuador – IVU en el embarazo 2013'),
  ('0924a8ad-52e3-54b9-abe0-48612744d57c', 'Según los objetivos específicos de la GPC del MSP de Ecuador sobre infección de vías urinarias en el embarazo, ¿cuál de los siguientes corresponde textualmente a uno de ellos?', 'Determinar el esquema de anticoncepción posparto más adecuado', 'Identificar los signos y síntomas de gravedad para referir de manera oportuna y segura a las pacientes a los centros de mayor capacidad resolutiva', 'Establecer un protocolo único de manejo hospitalario obligatorio para toda IVU, sin distinción de gravedad', 'Erradicar por completo la incidencia de infección urinaria en el embarazo a nivel nacional', 'B', 'Los objetivos específicos de la guía incluyen: señalar las medidas de prevención efectivas y factibles, fomentar el uso de pruebas diagnósticas eficaces disponibles en Ecuador, e identificar los signos y síntomas de gravedad para referir de manera oportuna y segura a las pacientes a los centros de mayor capacidad resolutiva.', 'Enfermería - Cuidados de la Mujer, Recién Nacido, Niño y Adolescente', 'GPC MSP Ecuador – IVU en el embarazo 2013'),
  ('b1a54699-3a0c-52e8-a48c-74774cc2bf33', 'Según la introducción de la GPC del MSP de Ecuador sobre infección de vías urinarias en el embarazo, ¿cuál es el patógeno más frecuentemente aislado en las IVU durante el embarazo?', 'Staphylococcus saprophyticus', 'Proteus mirabilis', 'Escherichia coli', 'Klebsiella pneumoniae', 'C', 'La guía establece en su introducción que Escherichia coli es el patógeno más frecuentemente aislado en IVU durante el embarazo, dato que se reitera en la sección de definiciones y en las recomendaciones de tratamiento, donde se señala que se encuentra en 80% a 90% de las infecciones iniciales.', 'Enfermería - Cuidados de la Mujer, Recién Nacido, Niño y Adolescente', 'GPC MSP Ecuador – IVU en el embarazo 2013'),
  ('03a7ddd6-a415-5f5d-9eef-42daf1b8f6b4', 'Según la GPC del MSP de Ecuador sobre infección de vías urinarias en el embarazo, ¿qué porcentaje de partos pretérmino tiene una asociación clínica con IVU?', 'Menos de 5%', 'Más de 80%', 'Más de 50%', 'Más de 27%', 'D', 'La introducción de la guía establece que más de 27% de partos pretérmino tienen una asociación clínica con IVU, aunque la patogénesis de la contracción uterina aún no está clara.', 'Enfermería - Cuidados de la Mujer, Recién Nacido, Niño y Adolescente', 'GPC MSP Ecuador – IVU en el embarazo 2013'),
  ('9ec1fa13-d1e3-57ac-b2c8-c09dcecf7e06', 'Según la introducción de la GPC del MSP de Ecuador sobre infección de vías urinarias en el embarazo, ¿cuál es la principal causa de falla terapéutica en el tratamiento de las infecciones de vías urinarias bajas?', 'El inadecuado análisis de las resistencias bacterianas locales a los antibióticos', 'La ausencia de vacunación materna previa al embarazo', 'El uso exclusivo de manejo expectante sin antibióticos', 'La falta de acceso a estudios de imagen renal', 'A', 'La introducción de la guía señala que el tratamiento adecuado de las infecciones de vías urinarias bajas requiere un adecuado análisis de las resistencias bacterianas locales a los antibióticos, ya que esta es la principal causa de falla terapéutica.', 'Enfermería - Cuidados de la Mujer, Recién Nacido, Niño y Adolescente', 'GPC MSP Ecuador – IVU en el embarazo 2013'),
  ('0ccb84b6-4e56-5279-ac9d-383a5dad03af', 'Según la GPC del MSP de Ecuador sobre infección de vías urinarias en el embarazo, ¿por qué las mujeres embarazadas desarrollan de manera fácil infecciones de vías urinarias?', 'Debido exclusivamente a la disminución de la inmunidad celular en el tercer trimestre', 'Debido a cambios funcionales, hormonales y anatómicos, además de la localización del meato uretral expuesta a bacterias uropatógenas y de vagina que acceden al tracto urinario bajo', 'Debido únicamente al aumento de la frecuencia de relaciones sexuales durante el embarazo', 'Debido exclusivamente al uso de anticonceptivos previos al embarazo', 'B', 'La introducción de la guía explica que las mujeres embarazadas desarrollan de manera fácil IVU debido a cambios funcionales, hormonales y anatómicos, además de la localización del meato uretral expuesta a bacterias uropatógenas y de vagina que acceden al tracto urinario bajo.', 'Enfermería - Cuidados de la Mujer, Recién Nacido, Niño y Adolescente', 'GPC MSP Ecuador – IVU en el embarazo 2013'),
  ('b8a65eb7-9ca5-5092-a05f-1ebfa96122a0', 'Según la historia natural y el pronóstico descritos en la GPC del MSP de Ecuador sobre infección de vías urinarias en el embarazo, ¿qué organismos recomiendan realizar tamizaje apropiado para detectar la bacteriuria asintomática?', 'La Organización Mundial de la Salud (OMS) exclusivamente', 'El Colegio Americano de Cardiología exclusivamente', 'El American College of Obstetrics and Gynecology (ACOG) y el U.S. Preventive Services Task Force', 'Ningún organismo internacional recomienda este tamizaje según la guía', 'C', 'La guía establece que la bacteriuria asintomática no presenta sintomatología y puede determinar problemas obstétricos y perinatales de alto impacto, por lo que se debe realizar tamizaje apropiado para detectarla, como lo recomienda el American College of Obstetrics and Gynecology (ACOG) y el U.S. Preventive Services Task Force.', 'Enfermería - Cuidados de la Mujer, Recién Nacido, Niño y Adolescente', 'GPC MSP Ecuador – IVU en el embarazo 2013'),
  ('cad4e658-f493-51e6-abc0-65a0a979c569', 'Según la GPC del MSP de Ecuador sobre infección de vías urinarias en el embarazo, ¿cuáles son los cambios fisiológicos del embarazo que propician la bacteriuria asintomática y su progresión a pielonefritis?', 'Únicamente el aumento del volumen plasmático materno', 'Solamente el incremento de la tasa de filtración glomerular sin otros cambios asociados', 'Exclusivamente la disminución de la frecuencia miccional en el tercer trimestre', 'Compresión mecánica por el crecimiento del útero, relajación del músculo liso inducida por la progesterona, cambios en el pH urinario, glucosuria y aminoaciduria', 'D', 'La guía señala que los cambios fisiológicos en el embarazo que propician la bacteriuria asintomática (BA) y su progresión a pielonefritis incluyen la compresión mecánica por el crecimiento del útero, la relajación del músculo liso inducida por la progesterona, los cambios en el pH urinario, así como la glucosuria y la aminoaciduria.', 'Enfermería - Cuidados de la Mujer, Recién Nacido, Niño y Adolescente', 'GPC MSP Ecuador – IVU en el embarazo 2013'),
  ('b0d3587a-ba55-507c-9c51-470481ca83cf', 'Según la GPC del MSP de Ecuador sobre infección de vías urinarias en el embarazo, ¿cómo se define la infección de vías urinarias (IVU)?', 'La existencia de gérmenes patógenos en la orina por infección de la vejiga o el riñón', 'La presencia de proteinuria mayor a 300 mg en 24 horas', 'La sensación inminente de orinar sin otro hallazgo asociado', 'La presencia exclusiva de leucocitos en orina, independientemente del urocultivo', 'A', 'La guía define la infección de vías urinarias (IVU) como la existencia de gérmenes patógenos en la orina por infección de la vejiga o el riñón, señalando que los síntomas varían según el sitio de la infección, pudiendo incluso ser asintomática.', 'Enfermería - Cuidados de la Mujer, Recién Nacido, Niño y Adolescente', 'GPC MSP Ecuador – IVU en el embarazo 2013'),
  ('a07f3768-31c5-5dc5-a292-d90baf1870f4', 'Según la GPC del MSP de Ecuador sobre infección de vías urinarias en el embarazo, ¿en qué tres presentaciones se clasifica la IVU de acuerdo al sitio de proliferación de las bacterias?', 'Infección leve, moderada y grave, según la intensidad del dolor', 'Bacteriuria asintomática (orina), cistitis (vejiga) y pielonefritis (riñón)', 'Nefritis intersticial, glomerulonefritis y nefrolitiasis', 'Uretritis, vaginitis y cervicitis', 'B', 'La guía establece que la IVU se clasifica de acuerdo al sitio de proliferación de las bacterias en: bacteriuria asintomática (orina), cistitis (vejiga) y pielonefritis (riñón).', 'Enfermería - Cuidados de la Mujer, Recién Nacido, Niño y Adolescente', 'GPC MSP Ecuador – IVU en el embarazo 2013'),
  ('47a7cbba-0839-5707-bb17-1f3ec9749199', 'Una paciente embarazada asintomática presenta en su urocultivo de tamizaje un resultado de 150.000 unidades formadoras de colonias/mL de un único germen. Según la definición de la GPC del MSP de Ecuador sobre infección de vías urinarias en el embarazo, ¿qué diagnóstico corresponde a este resultado?', 'Contaminación de la muestra, sin relevancia clínica', 'Pielonefritis aguda', 'Bacteriuria asintomática (BA)', 'Cistitis aguda', 'C', 'La guía define la bacteriuria asintomática (BA) como la presencia de bacterias en orina detectadas por urocultivo (más de 100.000 unidades formadoras de colonias/mL) sin síntomas típicos de infección aguda del tracto urinario, criterio que se cumple en este caso al tratarse de una paciente asintomática con un resultado superior a ese umbral.', 'Enfermería - Cuidados de la Mujer, Recién Nacido, Niño y Adolescente', 'GPC MSP Ecuador – IVU en el embarazo 2013'),
  ('c390a287-ea56-57b5-8717-a0f4e460f7c8', 'Una paciente embarazada refiere urgencia miccional, aumento de la frecuencia urinaria, disuria y presencia de hematuria. No presenta fiebre ni afección sistémica. Según la definición de la GPC del MSP de Ecuador sobre infección de vías urinarias en el embarazo, ¿qué diagnóstico corresponde a este cuadro?', 'Vaginitis', 'Pielonefritis aguda', 'Bacteriuria asintomática', 'Cistitis aguda', 'D', 'La guía define la cistitis aguda como la infección bacteriana del tracto urinario bajo que se acompaña de urgencia, frecuencia, disuria, piuria y hematuria, sin evidencia de afección sistémica, cuadro que coincide exactamente con el caso descrito.', 'Enfermería - Cuidados de la Mujer, Recién Nacido, Niño y Adolescente', 'GPC MSP Ecuador – IVU en el embarazo 2013'),
  ('e0cb312c-370e-5b37-b8e3-2f65800658ee', 'Una paciente embarazada de 28 semanas acude por fiebre de 38.7°C, escalofrío, malestar general intenso y dolor costovertebral derecho, acompañado de náusea y vómito. Según la definición de la GPC del MSP de Ecuador sobre infección de vías urinarias en el embarazo, ¿qué diagnóstico corresponde a este cuadro?', 'Pielonefritis aguda', 'Bacteriuria asintomática', 'Cistitis aguda no complicada', 'Amenaza de parto pretérmino sin relación con IVU', 'A', 'La guía define la pielonefritis aguda como la infección de la vía excretora urinaria alta y del parénquima renal de uno o ambos riñones que se acompaña de fiebre, escalofrío, malestar general, dolor costovertebral y, en ocasiones, náusea, vómito y deshidratación, cuadro que corresponde exactamente al caso descrito.', 'Enfermería - Cuidados de la Mujer, Recién Nacido, Niño y Adolescente', 'GPC MSP Ecuador – IVU en el embarazo 2013'),
  ('f74d907c-66fa-5981-ac30-27947657e793', 'Según la GPC del MSP de Ecuador sobre infección de vías urinarias en el embarazo, ¿cuál es la droga de elección para el tratamiento de IVU en Ecuador y por qué motivo?', 'La ampicilina, por su bajo costo', 'La nitrofurantoína, por sus bajos niveles de resistencia', 'La amoxicilina/clavulánico, por su disponibilidad en el primer nivel', 'El trimetoprim con sulfametoxasol, por su amplio espectro', 'B', 'La guía establece que la droga de elección para el país es la nitrofurantoína por sus bajos niveles de resistencia, señalando que la fosfomicina y las cefalosporinas son alternativas a la nitrofurantoína.', 'Enfermería - Cuidados de la Mujer, Recién Nacido, Niño y Adolescente', 'GPC MSP Ecuador – IVU en el embarazo 2013'),
  ('b1f7401e-fa08-5e82-b03d-77c9efa05959', 'Según la GPC del MSP de Ecuador sobre infección de vías urinarias en el embarazo, ¿qué se debe realizar luego de completar el tratamiento antibiótico tanto de BA como de cistitis?', 'Ninguna prueba adicional, ya que el tratamiento se considera exitoso de forma automática', 'Una ecografía renal de control en todos los casos', 'Urocultivo de control para documentar el éxito de la erradicación', 'Un examen general de orina únicamente, sin urocultivo', 'C', 'La guía establece que, luego de completar el tratamiento antibiótico tanto de BA como de cistitis, se debe realizar urocultivo de control para documentar el éxito de la erradicación.', 'Enfermería - Cuidados de la Mujer, Recién Nacido, Niño y Adolescente', 'GPC MSP Ecuador – IVU en el embarazo 2013'),
  ('1493d0c3-0913-594c-af79-5c0180a14b31', 'Según la GPC del MSP de Ecuador sobre infección de vías urinarias en el embarazo, ¿qué fármacos son desaconsejados para el tratamiento empírico de IVU por sus altas tasas de resistencia local?', 'Nitrofurantoína y fosfomicina', 'Fosfomicina en dosis única', 'Cefalexina y cefalosporinas de segunda generación', 'Ampicilina y combinaciones con inhibidores de betalactamasas.', 'D', 'La guía establece que la ampicilina e inhibidores de betalactamasas son desaconsejados por sus altas tasas de resistencia local presentadas en la reunión de consenso para la toma de decisiones respecto a la terapéutica.', 'Enfermería - Cuidados de la Mujer, Recién Nacido, Niño y Adolescente', 'GPC MSP Ecuador – IVU en el embarazo 2013'),
  ('48505b2a-3988-5901-8965-2eb621d0db09', 'Según la GPC del MSP de Ecuador sobre infección de vías urinarias en el embarazo, la elección del antimicrobiano para el tratamiento de la IVU en el embarazo debe estar dirigida a:', 'Los agentes etiológicos más frecuentes, siendo además el fármaco seguro para la madre y el feto', 'La preferencia personal de la paciente, sin considerar el perfil de resistencia', 'El menor costo del fármaco, independientemente del perfil de resistencia local', 'La disponibilidad exclusiva en farmacias privadas', 'A', 'La guía establece que la elección del antimicrobiano debe estar dirigida a los agentes etiológicos más frecuentes y debe ser seguro para la madre y el feto, criterios que fundamentan la selección de nitrofurantoína, fosfomicina y cefalosporinas como opciones de tratamiento.', 'Enfermería - Cuidados de la Mujer, Recién Nacido, Niño y Adolescente', 'GPC MSP Ecuador – IVU en el embarazo 2013'),
  ('79ebc35e-bffb-5196-b125-1fd3e4b3a309', 'Según la GPC del MSP de Ecuador sobre infección de vías urinarias en el embarazo, en el Ecuador, la etiología bacteriana de la BA y la cistitis en mujeres embarazadas y no embarazadas es similar, encontrando Escherichia coli en:', 'Solo en infecciones recurrentes, nunca en las iniciales', '80% a 90% de las infecciones iniciales y en 70% a 80% de las recurrentes', 'Menos del 20% de las infecciones iniciales', '100% de todas las infecciones sin excepción', 'B', 'La guía establece que la etiología bacteriana de la BA y cistitis en mujeres embarazadas y no embarazadas es similar, encontrando Escherichia coli en 80% a 90% de las infecciones iniciales y en 70% a 80% de las recurrentes.', 'Enfermería - Cuidados de la Mujer, Recién Nacido, Niño y Adolescente', 'GPC MSP Ecuador – IVU en el embarazo 2013'),
  ('9d64ad73-549f-5105-90a2-9741c90b9a56', 'Según la GPC del MSP de Ecuador sobre infección de vías urinarias en el embarazo, ¿de qué sistemas de clasificación se adaptaron los niveles de evidencia y grados de recomendación utilizados para criterios de tratamiento y diagnóstico?', 'Únicamente el sistema GRADE', 'Exclusivamente la escala de Shekelle modificada', 'Scottish Intercollegiate Guidelines Network (SIGN) y National Institute for Health and Clinical Excellence (NICE)', 'El sistema propio desarrollado por el Ministerio de Salud Pública del Ecuador sin referencia internacional', 'C', 'La guía indica que la evidencia científica se presenta con niveles de evidencia y grados de recomendación adaptados de la clasificación de la Scottish Intercollegiate Guidelines Network (SIGN) y del National Institute for Health and Clinical Excellence (NICE), que son similares entre sí para niveles de recomendación y grados de evidencia en criterios de tratamiento y diagnóstico.', 'Enfermería - Cuidados de la Mujer, Recién Nacido, Niño y Adolescente', 'GPC MSP Ecuador – IVU en el embarazo 2013'),
  ('17b16fc9-1402-5122-8581-879c48bba942', 'Según la GPC del MSP de Ecuador sobre infección de vías urinarias en el embarazo, ¿qué sistema de clasificación se utiliza para variables como prevención, etiología, daño, pronóstico, prevalencia o economía?', 'Scottish Intercollegiate Guidelines Network (SIGN) exclusivamente', 'National Institute for Health and Clinical Excellence (NICE) exclusivamente', 'Instrumento AGREE II', 'Centre for Evidence-Based Medicine, Oxford (OCEBM)', 'D', 'La guía establece que se usarán los niveles del Centre for Evidence-Based Medicine, Oxford (OCEBM) para variables como prevención, etiología, daño, pronóstico, prevalencia o economía, mientras que para criterios de tratamiento y diagnóstico se usan los de SIGN y NICE.', 'Enfermería - Cuidados de la Mujer, Recién Nacido, Niño y Adolescente', 'GPC MSP Ecuador – IVU en el embarazo 2013'),
  ('856e1c24-aa90-59ed-9395-7ee3ecd049b9', 'Según la escala SIGN/NICE recogida en la GPC del MSP de Ecuador sobre infección de vías urinarias en el embarazo, ¿qué nivel de evidencia corresponde a un metaanálisis de alta calidad, revisión sistemática de ensayos clínicos o ensayo clínico de alta calidad con muy poco riesgo de sesgo?', '1++', '1-', '2++', '4', 'A', 'La tabla SIGN/NICE de la guía asigna el nivel 1++ a metaanálisis de alta calidad, revisiones sistemáticas de ensayos clínicos (RS de EC) o ensayos clínicos (EC) de alta calidad con muy poco riesgo de sesgo.', 'Enfermería - Cuidados de la Mujer, Recién Nacido, Niño y Adolescente', 'GPC MSP Ecuador – IVU en el embarazo 2013'),
  ('7675e514-3ac4-5d48-8d63-8d7b1a5eff7d', 'Según la escala SIGN/NICE de la GPC del MSP de Ecuador sobre infección de vías urinarias en el embarazo, ¿qué grado de recomendación corresponde a un volumen de evidencia compuesta por estudios clasificados como 2++, directamente aplicable a la población diana de la GPC del MSP de Ecuador sobre infección de vías urinarias en el embarazo?', 'Grado A', 'Grado B', 'Grado D', 'Grado C', 'B', 'La tabla SIGN/NICE de grados de recomendación establece que el grado B corresponde a un volumen de evidencia científica compuesta por estudios clasificados como 2++, directamente aplicable a la población diana de la guía y que demuestran gran consistencia entre ellos, o evidencia científica extrapolada desde estudios clasificados como 1++ o 1+.', 'Enfermería - Cuidados de la Mujer, Recién Nacido, Niño y Adolescente', 'GPC MSP Ecuador – IVU en el embarazo 2013'),
  ('b8311dc7-fcbc-5e89-9401-821eff5eff30', 'Según la escala del Centre for Evidence-Based Medicine, Oxford (OCEBM) recogida en la GPC del MSP de Ecuador sobre infección de vías urinarias en el embarazo, ¿qué nivel de evidencia corresponde a un ensayo clínico aleatorizado con intervalo de confianza estrecho?', '2 a', '1 a', '1 b', '3 b', 'C', 'La tabla OCEBM de la guía establece que el nivel 1b corresponde a un ensayo clínico aleatorizado con intervalo de confianza estrecho, distinto del nivel 1a, que corresponde a una revisión sistemática de ensayos clínicos aleatorizados con homogeneidad.', 'Enfermería - Cuidados de la Mujer, Recién Nacido, Niño y Adolescente', 'GPC MSP Ecuador – IVU en el embarazo 2013'),
  ('b119f925-9aae-5574-8f52-cab53b6dadda', 'Según la GPC del MSP de Ecuador sobre infección de vías urinarias en el embarazo, ¿qué representa el símbolo de verificación (ü) en el margen de las páginas de la GPC del MSP de Ecuador sobre infección de vías urinarias en el embarazo?', 'Un error tipográfico sin significado clínico', 'Una recomendación obsoleta que debe ser descartada por el lector', 'El nivel más alto de evidencia científica disponible, equivalente al grado A', 'Un consejo de buena práctica clínica sobre el cual el grupo de expertos acuerda, generalmente aspectos prácticos sin suficiente evidencia científica que los sustente', 'D', 'La guía establece que el símbolo ü representa un consejo de buena práctica clínica sobre el cual el grupo de expertos acuerda, siendo por lo general aspectos prácticos sobre los que se quiere hacer énfasis y para los cuales probablemente no existe suficiente evidencia científica que los sustente, aclarando que estos aspectos no son una alternativa a las recomendaciones basadas en evidencia, sino que deben considerarse únicamente cuando no existe otra manera de destacar dicho aspecto.', 'Enfermería - Cuidados de la Mujer, Recién Nacido, Niño y Adolescente', 'GPC MSP Ecuador – IVU en el embarazo 2013'),
  ('a6ebd888-e821-530f-b83f-d514abb597f6', 'Según la GPC del MSP de Ecuador sobre infección de vías urinarias en el embarazo, ¿se dispone actualmente de una prevención primaria efectiva específica para la infección de vías urinarias en el embarazo?', 'No, en cuanto a infección de vías urinarias en el embarazo no se dispone aún de una prevención efectiva; mientras se desarrollan estrategias, se deben tomar en cuenta ciertas evidencias generales', 'No se menciona ningún tipo de medida preventiva en la guía', 'Sí, existe una vacuna específica altamente efectiva avalada por esta guía', 'Sí, el uso de antibióticos profilácticos continuos durante todo el embarazo previene completamente la IVU', 'A', 'La guía establece que la prevención primaria de toda enfermedad es la meta de la medicina preventiva, pero que en cuanto a infección de vías urinarias en el embarazo no se dispone aún de una prevención efectiva, señalando que mientras se desarrollan estrategias efectivas se deben tomar en cuenta ciertas evidencias disponibles.', 'Enfermería - Cuidados de la Mujer, Recién Nacido, Niño y Adolescente', 'GPC MSP Ecuador – IVU en el embarazo 2013'),
  ('d6b859be-a0db-513c-9d2f-2e37f8ff2722', 'Según la GPC del MSP de Ecuador sobre infección de vías urinarias en el embarazo, ¿qué medidas generales se recomiendan como punto de buena práctica para la prevención de IVU en el embarazo?', 'Restricción severa de líquidos para disminuir la producción de orina', 'Consumo de abundantes líquidos (>2 litros/día), vaciamiento completo de la vejiga en forma frecuente y después de tener relaciones sexuales, aseo genital adecuado y uso de ropa interior de preferencia de algodón', 'Retención voluntaria de la orina para ''entrenar'' la vejiga', 'Uso obligatorio de ropa interior sintética ajustada', 'B', 'La guía recomienda, como punto de buena práctica, el consumo de abundantes líquidos (mayor a 2 litros/día), el vaciamiento completo de la vejiga en forma frecuente y después de tener relaciones sexuales, un aseo genital adecuado y el uso de ropa interior de preferencia de algodón.', 'Enfermería - Cuidados de la Mujer, Recién Nacido, Niño y Adolescente', 'GPC MSP Ecuador – IVU en el embarazo 2013'),
  ('e5396e65-8b02-5542-97e2-2fe413e9830e', 'Según la GPC del MSP de Ecuador sobre infección de vías urinarias en el embarazo, ¿el consumo de jugo de arándano (mortiño) y lactobacilos probióticos es suficiente para prevenir las IVU recurrentes?', 'Sí, están avalados con evidencia de grado A como único método preventivo', 'No se menciona ninguna evidencia sobre el arándano en esta guía', 'No, estos métodos alternativos pueden contribuir, pero no son suficientes para prevenir IVU recurrentes', 'Sí, son completamente suficientes y reemplazan al tratamiento antibiótico', 'C', 'La guía establece (Ib C) que métodos alternativos como el consumo de jugo de arándano y lactobacilos probióticos pueden contribuir, pero no son suficientes para prevenir IVU recurrentes, señalando además que la dosis y el método de administración del arándano aún no están claros.', 'Enfermería - Cuidados de la Mujer, Recién Nacido, Niño y Adolescente', 'GPC MSP Ecuador – IVU en el embarazo 2013'),
  ('7eede9cd-8b75-53f6-929c-be5b85ea7058', 'Según la GPC del MSP de Ecuador sobre infección de vías urinarias en el embarazo, ¿qué se ha documentado respecto al jugo de arándano y la disminución del número de IVU sintomáticas?', 'Se ha establecido una dosis y método de administración estandarizados y avalados por la guía', 'No existe ninguna evidencia relacionada con el arándano en la literatura citada por la guía', 'Se ha demostrado que aumenta significativamente el riesgo de IVU sintomáticas', 'Hay evidencia de que puede disminuir el número de IVU sintomáticas en un período de 12 meses, sobre todo en IVU recurrentes, aunque aún no está claro ni la dosis ni el método de administración', 'D', 'La guía indica (E ü) que hay evidencia de que el jugo de arándano (mortiño en Ecuador) puede disminuir el número de IVU sintomáticas en un período de 12 meses, sobre todo en IVU recurrentes; sin embargo, aún no está claro ni la dosis ni el método de administración.', 'Enfermería - Cuidados de la Mujer, Recién Nacido, Niño y Adolescente', 'GPC MSP Ecuador – IVU en el embarazo 2013'),
  ('b2fb4ece-c760-5489-9ecc-dc01e93b3fe0', 'Una paciente embarazada refiere haber tenido infecciones del tracto urinario confirmadas antes del embarazo actual. Según la GPC del MSP de Ecuador sobre infección de vías urinarias en el embarazo, ¿qué relevancia tiene este antecedente en la evaluación prenatal actual?', 'El antecedente de IVU confirmadas es un predictor de bacteriuria asintomática durante el embarazo, por lo que se debe investigar dicho antecedente en las embarazadas', 'Solo debe investigarse si la paciente presenta síntomas urinarios activos en el momento de la consulta', 'Solo es relevante si las infecciones previas fueron causadas por Klebsiella', 'No tiene ninguna relevancia clínica para el embarazo actual', 'A', 'La guía establece (nivel 3) que el antecedente de infecciones del tracto urinario (IVU) confirmadas es un predictor de BA durante el embarazo, y recomienda (D) investigar el antecedente de IVU previas confirmadas en las embarazadas.', 'Enfermería - Cuidados de la Mujer, Recién Nacido, Niño y Adolescente', 'GPC MSP Ecuador – IVU en el embarazo 2013'),
  ('6fefbc46-caee-5b88-b053-20023271cb4a', 'Según la GPC del MSP de Ecuador sobre infección de vías urinarias en el embarazo, ¿qué grado de evidencia y recomendación respalda la afirmación de que el antecedente de IVU confirmadas es predictor de BA durante el embarazo?', 'No se asigna ningún grado de evidencia a esta afirmación', 'Nivel de evidencia 3, con grado de recomendación D', 'Nivel de evidencia 1++, con grado de recomendación A', 'Nivel de evidencia 2++, con grado de recomendación B', 'B', 'La guía asigna nivel de evidencia 3 a la afirmación sobre el antecedente de IVU como predictor de BA, y grado de recomendación D a la recomendación de investigar dicho antecedente en las embarazadas.', 'Enfermería - Cuidados de la Mujer, Recién Nacido, Niño y Adolescente', 'GPC MSP Ecuador – IVU en el embarazo 2013'),
  ('13df14fe-e6a0-58a3-a277-079da59d68e6', 'Un profesional de salud plantea utilizar la tira reactiva (dipstick) de orina como método de tamizaje para detectar bacteriuria asintomática en todas sus pacientes embarazadas. Según la GPC del MSP de Ecuador sobre infección de vías urinarias en el embarazo, ¿es adecuada esta conducta?', 'Sí, la tira reactiva es el método de tamizaje recomendado de primera línea para BA', 'Sí, siempre que se repita la prueba tres veces consecutivas para mejorar su sensibilidad', 'No, el examen general de orina o la prueba con tira reactiva no deben utilizarse para el tamizaje de BA, ya que tienen sensibilidad baja', 'Es indiferente utilizar tira reactiva o urocultivo, ya que tienen sensibilidad equivalente', 'C', 'La guía establece (A 1+) que el examen general de orina o la prueba con tira reactiva no deben utilizarse para el tamizaje de BA, señalando que la detección de BA a través del EMO o tirillas reactivas (Dipsticks) que detectan leucocituria, nitritos y bacterias tiene una sensibilidad baja, la cual disminuye ante la presencia de leucorrea.', 'Enfermería - Cuidados de la Mujer, Recién Nacido, Niño y Adolescente', 'GPC MSP Ecuador – IVU en el embarazo 2013'),
  ('397dbadc-550b-5b6e-98f6-b03aaf30408f', 'Según la GPC del MSP de Ecuador sobre infección de vías urinarias en el embarazo, ¿cuál es la sensibilidad y el valor predictivo negativo de la detección de bacteriuria asintomática a través del examen elemental y microscópico de orina (EMO)?', 'Sensibilidad de 99% y valor predictivo negativo de 100%', 'Sensibilidad de 10% y valor predictivo negativo de 20%', 'No se reporta ningún dato de sensibilidad para el EMO en esta guía', 'Sensibilidad de 50% a 92% y valor predictivo negativo de 92%', 'D', 'La guía establece que la detección de bacteriuria asintomática a través del EMO (leucocituria, nitritos y bacterias) tiene una sensibilidad de 50% a 92% y un valor predictivo negativo de 92%, señalando que la sensibilidad disminuye ante la presencia de leucorrea.', 'Enfermería - Cuidados de la Mujer, Recién Nacido, Niño y Adolescente', 'GPC MSP Ecuador – IVU en el embarazo 2013'),
  ('6ab21a12-eb83-58ed-a56a-0e79782a7bcd', 'Según la GPC del MSP de Ecuador sobre infección de vías urinarias en el embarazo, ¿cuál es la prueba de elección adecuada y más práctica para el diagnóstico de BA?', 'El urocultivo, que se establece con el aislamiento de más de 100.000 unidades formadoras de colonias/mL de un solo germen', 'La ecografía renal y de vías urinarias', 'La tira reactiva de orina', 'El examen general de orina exclusivamente', 'A', 'La guía establece (A) que el urocultivo es la prueba de elección adecuada y más práctica para el diagnóstico de BA, el cual se establece con el aislamiento de más de 100.000 unidades formadoras de colonias/mL de un solo germen, aceptándose la detección en una sola muestra obtenida del chorro medio de orina.', 'Enfermería - Cuidados de la Mujer, Recién Nacido, Niño y Adolescente', 'GPC MSP Ecuador – IVU en el embarazo 2013'),
  ('3f2a67ab-7cca-517c-841c-881f8a58e2f2', 'Según la GPC del MSP de Ecuador sobre infección de vías urinarias en el embarazo, ¿cuántas muestras de orina se requieren para establecer el diagnóstico de BA mediante urocultivo?', 'Se requieren obligatoriamente tres muestras consecutivas en días distintos', 'Se acepta la detección en una sola muestra obtenida del chorro medio de orina', 'Se requieren dos muestras tomadas con 24 horas de diferencia como mínimo', 'Se requiere una muestra obtenida exclusivamente por sondaje vesical en todos los casos', 'B', 'La guía establece explícitamente que se acepta la detección en una sola muestra obtenida del chorro medio de orina para el diagnóstico de BA, a diferencia de otros protocolos internacionales que exigen dos muestras.', 'Enfermería - Cuidados de la Mujer, Recién Nacido, Niño y Adolescente', 'GPC MSP Ecuador – IVU en el embarazo 2013'),
  ('1a8f9e69-50a4-535a-909d-8669f6e4cdb6', 'Una paciente embarazada con BA no recibió tratamiento antibiótico oportuno. Según la GPC del MSP de Ecuador sobre infección de vías urinarias en el embarazo, ¿en qué porcentaje de los casos progresa la BA no tratada a pielonefritis?', '60% a 80% de los casos', '90% a 100% de los casos', '20% a 40% de los casos', '1% a 2% de los casos', 'C', 'La guía establece (A 1++/2+) que la BA sin tratamiento progresa a pielonefritis en 20% a 40% de los casos, y que además se asocia con ruptura prematura de membranas, parto pretérmino y productos con bajo peso al nacer.', 'Enfermería - Cuidados de la Mujer, Recién Nacido, Niño y Adolescente', 'GPC MSP Ecuador – IVU en el embarazo 2013'),
  ('2b5db758-9e65-5f15-b19e-5eff7eaa4d32', 'Según la GPC del MSP de Ecuador sobre infección de vías urinarias en el embarazo, ¿en qué semanas de gestación se recomienda solicitar el urocultivo para el tamizaje de BA?', 'Solo en el tercer trimestre, después de la semana 28', 'Exclusivamente en el momento del parto', 'Únicamente en la semana 30 a 34 de gestación', 'En la semana 12-16 de embarazo, según el U.S. Preventive Task Force, o en la primera consulta prenatal, según el ACOG', 'D', 'La guía recomienda (C 3) solicitar el urocultivo para el tamizaje de BA en la semana 12-16 de embarazo, según el U.S. Preventive Task Force, o en la primera consulta prenatal, según el ACOG, en caso de que la paciente acuda por primera vez a control prenatal después de la fecha recomendada.', 'Enfermería - Cuidados de la Mujer, Recién Nacido, Niño y Adolescente', 'GPC MSP Ecuador – IVU en el embarazo 2013'),
  ('ce73d221-46de-5aa3-9b7e-51ce71009285', 'Según la GPC del MSP de Ecuador sobre infección de vías urinarias en el embarazo, ¿qué porcentaje aproximado de pacientes con BA se detecta al realizar el urocultivo en las semanas 12-16 de gestación?', 'Aproximadamente 80%', 'Aproximadamente 50%', '100% de los casos sin excepción', 'Aproximadamente 20%', 'A', 'La guía indica (C 3) que, aunque aún no se conoce el momento óptimo ni la frecuencia para realizar el urocultivo, este obtenido en las semanas 12-16 de gestación detectará aproximadamente 80% de las pacientes con BA.', 'Enfermería - Cuidados de la Mujer, Recién Nacido, Niño y Adolescente', 'GPC MSP Ecuador – IVU en el embarazo 2013'),
  ('f3fbb4d0-e240-5136-9690-e31f74555364', 'Una paciente presenta un urocultivo de tamizaje negativo en el primer trimestre del embarazo. Según la GPC del MSP de Ecuador sobre infección de vías urinarias en el embarazo, ¿se debe repetir el urocultivo de tamizaje en esta paciente durante el resto del embarazo?', 'Sí, se debe repetir mensualmente durante todo el embarazo sin excepción', 'No, a las pacientes con urocultivo de tamizaje negativo en el primer trimestre no se les debe repetir el urocultivo para tamizaje', 'Solo se repite si la paciente desarrolla preeclampsia', 'Sí, se debe repetir obligatoriamente en cada trimestre restante', 'B', 'La guía establece (C 3) que a las pacientes con urocultivo de tamizaje negativo en el primer trimestre del embarazo no se les debe repetir el urocultivo para tamizaje, señalando que solo el 1% a 2% de las mujeres con cultivo negativo inicial desarrollarán pielonefritis durante el embarazo.', 'Enfermería - Cuidados de la Mujer, Recién Nacido, Niño y Adolescente', 'GPC MSP Ecuador – IVU en el embarazo 2013'),
  ('76554161-ccab-5b14-b1ec-40b14528f48b', 'Según la GPC del MSP de Ecuador sobre infección de vías urinarias en el embarazo, ¿qué grado de recomendación y niveles de evidencia respaldan la recomendación de realizar tamizaje con urocultivo para diagnóstico y tratamiento oportuno de BA en las embarazadas?', 'C 3', 'No se asigna ningún grado de evidencia a esta recomendación', 'Grado A, con niveles de evidencia 1++/2+.', 'D 4', 'C', 'La guía asigna grado de recomendación A, con niveles de evidencia 1++/2+ a la recomendación de realizar tamizaje con urocultivo para diagnóstico y tratamiento oportuno de BA en las embarazadas, respaldada por los datos de progresión a pielonefritis (20-40%) y asociación con ruptura prematura de membranas, parto pretérmino y bajo peso al nacer.', 'Enfermería - Cuidados de la Mujer, Recién Nacido, Niño y Adolescente', 'GPC MSP Ecuador – IVU en el embarazo 2013'),
  ('03dcd299-07d9-5c77-83d7-ee08486a5119', 'Según la GPC del MSP de Ecuador sobre infección de vías urinarias en el embarazo, ¿cuál es el principal objetivo de realizar el tamizaje de BA durante las visitas prenatales?', 'Evaluar exclusivamente la función renal materna basal', 'Determinar el sexo del producto de la concepción', 'Sustituir el control de la tensión arterial en cada visita prenatal', 'Detectar oportunamente la infección, dado que la mayoría de las mujeres con BA estarán asintomáticas inicialmente', 'D', 'La guía señala que durante las visitas prenatales es necesario el tamizaje de IVU, ya que la mayoría de las mujeres estarán asintomáticas inicialmente, siendo el diagnóstico preciso de infección de vías urinarias la base del tratamiento.', 'Enfermería - Cuidados de la Mujer, Recién Nacido, Niño y Adolescente', 'GPC MSP Ecuador – IVU en el embarazo 2013'),
  ('9c3d5bab-66e5-5ad9-81d5-1a237f371fd8', 'Una paciente acude a su primer control prenatal en la semana 20 de gestación, ya que no tuvo acceso a controles previos. Según la GPC del MSP de Ecuador sobre infección de vías urinarias en el embarazo, ¿en qué momento debe solicitarse el urocultivo de tamizaje para BA en este caso?', 'En la primera consulta prenatal, dado que la paciente acude por primera vez luego de la fecha recomendada (semana 12-16)', 'No corresponde realizar tamizaje si la paciente ya superó la semana 16 de gestación', 'Debe esperarse hasta la semana 30 para solicitar el urocultivo', 'Debe solicitarse únicamente si la paciente presenta síntomas urinarios', 'A', 'La guía establece que se debe solicitar el urocultivo para el tamizaje de BA en la semana 12-16 de embarazo, o en la primera consulta prenatal (según el ACOG), en caso de que la paciente acuda por primera vez a control prenatal luego de la fecha recomendada, situación que corresponde exactamente a este caso.', 'Enfermería - Cuidados de la Mujer, Recién Nacido, Niño y Adolescente', 'GPC MSP Ecuador – IVU en el embarazo 2013'),
  ('5b0d7958-c045-5b97-8ae4-870ddb62984b', 'Según la GPC del MSP de Ecuador sobre infección de vías urinarias en el embarazo, ¿la sensibilidad de la detección de BA mediante EMO se ve afectada por la presencia de leucorrea?', 'No, la leucorrea no tiene ningún efecto sobre la sensibilidad del EMO para BA', 'Sí, la sensibilidad de la detección mediante EMO disminuye ante la presencia de leucorrea', 'La leucorrea aumenta la sensibilidad del EMO para el diagnóstico de BA', 'La guía no menciona ninguna relación entre leucorrea y la sensibilidad del EMO', 'B', 'La guía establece explícitamente que la sensibilidad de la detección de BA a través del examen general de orina o con tirillas reactivas disminuye ante la presencia de leucorrea, lo que constituye una de las razones por las que estos métodos no deben usarse para el tamizaje de BA.', 'Enfermería - Cuidados de la Mujer, Recién Nacido, Niño y Adolescente', 'GPC MSP Ecuador – IVU en el embarazo 2013'),
  ('6510a739-2ac2-5d67-9743-f955d1d517ed', 'Una paciente embarazada sin otra patología conocida presenta disuria, polaquiuria y urgencia urinaria, sin síntomas vaginales asociados. Según la GPC del MSP de Ecuador sobre infección de vías urinarias en el embarazo, ¿es necesario solicitar urocultivo antes de iniciar el tratamiento en este caso?', 'No se debe iniciar ningún tratamiento sin antes descartar pielonefritis mediante ecografía renal', 'Sí, el urocultivo es obligatorio antes de iniciar cualquier tratamiento de cistitis', 'No, en mujeres sin otra patología el diagnóstico puede realizarse sobre la base de los datos clínicos, sin requerir urocultivo para iniciar el tratamiento', 'Sí, se debe esperar el resultado del urocultivo durante al menos 5 días antes de tratar', 'C', 'La guía establece (C 3) que en mujeres sin otra patología, el diagnóstico de cistitis puede realizarse sobre la base de los datos clínicos, sin requerir solicitar urocultivo para iniciar el tratamiento, señalando que los datos clínicos junto con el examen general de orina tienen una sensibilidad alta (70% a 80%) para el diagnóstico de cistitis.', 'Enfermería - Cuidados de la Mujer, Recién Nacido, Niño y Adolescente', 'GPC MSP Ecuador – IVU en el embarazo 2013'),
  ('3018975b-548a-5646-b38c-290b8edd15b0', 'Según la GPC del MSP de Ecuador sobre infección de vías urinarias en el embarazo, ¿cuál es la sensibilidad de los datos clínicos y del examen general de orina para el diagnóstico de cistitis, en ausencia de síntomas vaginales?', '10% a 20%', '30% a 40%', '95% a 100%', '70% a 80%', 'D', 'La guía establece (C 3) que los datos clínicos de cistitis y del examen general de orina (disuria, polaquiuria, urgencia urinaria, así como piuria y hematuria en ausencia de síntomas vaginales), sin evidencia de enfermedad sistémica, tienen una sensibilidad alta de 70% a 80% para el diagnóstico de cistitis.', 'Enfermería - Cuidados de la Mujer, Recién Nacido, Niño y Adolescente', 'GPC MSP Ecuador – IVU en el embarazo 2013'),
  ('dc2576f2-ab6c-59fc-b7f7-df1145e53204', 'Una paciente embarazada presenta datos clínicos compatibles con cistitis, pero además refiere ardor y secreción vaginal anormal. Según la GPC del MSP de Ecuador sobre infección de vías urinarias en el embarazo, ¿qué conducta se recomienda en este caso?', 'Explorar alternativas de diagnóstico de la cistitis y considerar el examen pélvico para tratamiento inicial de la vaginitis', 'Iniciar tratamiento antibiótico para cistitis sin ninguna evaluación adicional', 'Referir de manera inmediata a un centro de tercer nivel sin evaluación previa', 'Descartar por completo el diagnóstico de cistitis y tratar únicamente la vaginitis', 'A', 'La guía recomienda (C 2++) que en mujeres que presentan datos clínicos de cistitis y además ardor y/o secreción vaginal anormal, se deben explorar alternativas de diagnóstico de la cistitis y considerar el examen pélvico para tratamiento inicial de la vaginitis, dado que la presencia de secreción vaginal anormal disminuye la sensibilidad de los datos clínicos y del examen general de orina para el diagnóstico de cistitis.', 'Enfermería - Cuidados de la Mujer, Recién Nacido, Niño y Adolescente', 'GPC MSP Ecuador – IVU en el embarazo 2013'),
  ('db4434ec-2494-5eb5-b177-7ddeee460aaa', 'Según la GPC del MSP de Ecuador sobre infección de vías urinarias en el embarazo, ¿qué efecto tiene la presencia de secreción vaginal anormal sobre la sensibilidad de los datos clínicos y del examen general de orina para el diagnóstico de cistitis?', 'No tiene ningún efecto', 'La disminuye', 'La guía no menciona ninguna relación entre secreción vaginal y sensibilidad diagnóstica de cistitis', 'La aumenta significativamente', 'B', 'La guía establece que la presencia de secreción vaginal anormal disminuye la sensibilidad de los datos clínicos y del examen general de orina para el diagnóstico de cistitis, lo que justifica explorar alternativas diagnósticas y considerar el examen pélvico en estos casos.', 'Enfermería - Cuidados de la Mujer, Recién Nacido, Niño y Adolescente', 'GPC MSP Ecuador – IVU en el embarazo 2013'),
  ('74f4d482-eae8-57bd-8dd8-abc706b80bc4', 'Según la GPC del MSP de Ecuador sobre infección de vías urinarias en el embarazo, ¿los uropatógenos encontrados en la cistitis en la embarazada son los mismos que en la bacteriuria asintomática?', 'Sí, pero únicamente en pacientes con diabetes gestacional', 'No, la cistitis se asocia exclusivamente a hongos, mientras que la BA se asocia solo a bacterias', 'Sí, los uropatógenos encontrados en una cistitis en la embarazada son los mismos que en la BA', 'No existe ninguna relación entre los uropatógenos de ambas condiciones', 'C', 'La guía establece (C 3) que las recomendaciones de tratamiento para la cistitis durante el embarazo son las mismas que para BA, señalando que los uropatógenos encontrados en una cistitis en la embarazada son los mismos que en la BA.', 'Enfermería - Cuidados de la Mujer, Recién Nacido, Niño y Adolescente', 'GPC MSP Ecuador – IVU en el embarazo 2013'),
  ('78cee290-8bf5-5e33-a5d8-9aa60855bb6c', 'Según la GPC del MSP de Ecuador sobre infección de vías urinarias en el embarazo, ¿existe clara evidencia de que la cistitis se asocie con trabajo de parto pretérmino, de forma similar a lo que ocurre con la BA?', 'Sí, la cistitis tiene una asociación aún más fuerte que la BA con el parto pretérmino', 'No se ha estudiado esta relación en ningún caso', 'Sí, la evidencia es igual de sólida para cistitis que para BA respecto a esta asociación', 'No hay una clara evidencia de que la cistitis se asocie con trabajo de parto pretérmino como es el caso de la BA', 'D', 'La guía indica (2+) que no hay una clara evidencia de que la cistitis se asocie con trabajo de parto pretérmino como es el caso de la BA, diferenciando así el nivel de evidencia de asociación obstétrica entre ambas entidades.', 'Enfermería - Cuidados de la Mujer, Recién Nacido, Niño y Adolescente', 'GPC MSP Ecuador – IVU en el embarazo 2013'),
  ('24a42acd-d20e-5298-b8bd-86d760156b0e', 'Según la GPC del MSP de Ecuador sobre infección de vías urinarias en el embarazo, ¿cuándo debe iniciarse el tratamiento de la cistitis?', 'Frente a paciente sintomática, idealmente luego de toma de muestra para EMO y urocultivo, con los fármacos sugeridos para el país', 'Solo si la paciente ha fallado previamente a un tratamiento con nitrofurantoína', 'Solo después de confirmar el resultado positivo del urocultivo, sin excepción', 'Únicamente cuando la paciente presente fiebre asociada', 'A', 'La guía establece como punto de buena práctica (ü) que el tratamiento de cistitis debe iniciarse frente a paciente sintomática, idealmente luego de toma de muestra para EMO y urocultivo, con los fármacos sugeridos para el país, sin necesidad de esperar el resultado para iniciar el manejo empírico.', 'Enfermería - Cuidados de la Mujer, Recién Nacido, Niño y Adolescente', 'GPC MSP Ecuador – IVU en el embarazo 2013'),
  ('a7092eb9-e066-542b-9762-212501f7aa65', 'Una paciente presenta datos clínicos de cistitis sin síntomas vaginales asociados. El profesional de salud evalúa iniciar tratamiento empírico. Según la GPC del MSP de Ecuador sobre infección de vías urinarias en el embarazo, ¿qué recomendaciones de tratamiento debe seguir para esta paciente?', 'Un esquema antibiótico completamente distinto al usado en BA, con doble duración de tratamiento', 'Las mismas recomendaciones de tratamiento que para la bacteriuria asintomática', 'Manejo exclusivamente quirúrgico mediante cateterismo vesical prolongado', 'Manejo expectante sin antibióticos, dado que la cistitis no complicada se autolimita en el embarazo', 'B', 'La guía establece (C 3) que las recomendaciones de tratamiento para la cistitis durante el embarazo son las mismas que para BA, dado que los uropatógenos encontrados en ambas condiciones son los mismos.', 'Enfermería - Cuidados de la Mujer, Recién Nacido, Niño y Adolescente', 'GPC MSP Ecuador – IVU en el embarazo 2013'),
  ('e886712f-a652-5acb-96dc-449cce2962bb', 'Una paciente embarazada de 14 semanas tiene un urocultivo de tamizaje positivo para BA, con más de 100.000 UFC/mL de Escherichia coli, sin presentar ningún síntoma urinario. Según la GPC del MSP de Ecuador sobre infección de vías urinarias en el embarazo, ¿se debe tratar esta bacteriuria asintomática con antibiótico?', 'Solo se trata en el tercer trimestre del embarazo, nunca antes', 'Solo se trata si la paciente desarrolla fiebre en las siguientes 48 horas', 'Sí, se debe dar tratamiento con antibiótico en caso de detectar BA por urocultivo durante el embarazo, ya que reduce el riesgo de pielonefritis, partos pretérmino y bajo peso al nacer', 'No, la BA no requiere tratamiento porque, por definición, la paciente está asintomática', 'C', 'La guía establece (A 1++) que se debe dar tratamiento con antibiótico en caso de detectar BA por urocultivo durante el embarazo, señalando que el tratamiento reduce el riesgo de infección del tracto urinario alto (pielonefritis), los partos pretérmino y el riesgo de productos con bajo peso al nacer, y que es costo-efectivo si hay una incidencia de BA mayor a 2%.', 'Enfermería - Cuidados de la Mujer, Recién Nacido, Niño y Adolescente', 'GPC MSP Ecuador – IVU en el embarazo 2013'),
  ('30b85d4e-431f-57f2-ba1c-972d43457fb8', 'Según la GPC del MSP de Ecuador sobre infección de vías urinarias en el embarazo, ¿a partir de qué incidencia de BA el tratamiento se considera costo-efectivo?', 'El tratamiento nunca se considera costo-efectivo según la guía', 'Mayor a 20%', 'Mayor a 50%', 'Mayor a 2%', 'D', 'La guía establece que el tratamiento de la bacteriuria asintomática en el embarazo es costo-efectivo si hay una incidencia de BA mayor a 2%.', 'Enfermería - Cuidados de la Mujer, Recién Nacido, Niño y Adolescente', 'GPC MSP Ecuador – IVU en el embarazo 2013'),
  ('dbcb59ba-c827-557c-a2b5-19c3dbce99cc', 'Según la GPC del MSP de Ecuador sobre infección de vías urinarias en el embarazo, ¿sobre qué base debe tratarse la BA en el embarazo con antibióticos?', 'Sobre la base del cultivo y sensibilidad reportada según tamizaje', 'Únicamente sobre la base de la sintomatología referida por la paciente', 'Solo con base en el criterio de la paciente sobre qué medicamento prefiere', 'Siempre con el mismo antibiótico de amplio espectro, sin considerar cultivo ni sensibilidad', 'A', 'La guía establece que la BA en el embarazo debe tratarse con antibióticos sobre la base del cultivo y sensibilidad reportada según tamizaje.', 'Enfermería - Cuidados de la Mujer, Recién Nacido, Niño y Adolescente', 'GPC MSP Ecuador – IVU en el embarazo 2013'),
  ('541b3ce9-12f3-594c-bf7d-1307674e038a', 'Según la GPC del MSP de Ecuador sobre infección de vías urinarias en el embarazo, ¿qué elementos se deben tomar en cuenta para elegir el antimicrobiano en el tratamiento de la IVU baja durante el embarazo?', 'Solamente la vía de administración preferida por el paciente', 'Espectro frente al germen, farmacocinética, efectos adversos, duración, costo y patrones locales de resistencia.', 'Únicamente el costo del medicamento', 'Exclusivamente la disponibilidad en el sector privado', 'B', 'La guía establece (A 1a) que para elegir el antimicrobiano que se debe usar hay que tomar en cuenta el espectro de actividad para el germen, su farmacocinética, los probables efectos secundarios, la duración del tratamiento y los costos, además de conocer los patrones de resistencia local a los antimicrobianos más usados.', 'Enfermería - Cuidados de la Mujer, Recién Nacido, Niño y Adolescente', 'GPC MSP Ecuador – IVU en el embarazo 2013'),
  ('7cd2a290-755c-5ab8-9b6d-352b65ff988c', 'Según la GPC del MSP de Ecuador sobre infección de vías urinarias en el embarazo, ¿los estudios realizados pudieron demostrar la preferencia de algún antibiótico en particular para el tratamiento de las IVU bajas en el embarazo?', 'No se realizaron estudios comparativos entre antibióticos según la guía', 'Sí, la ampicilina demostró ser el fármaco más eficaz en todos los estudios revisados', 'No, la mayoría de los antibióticos usados son efectivos en el embarazo y los estudios no pudieron mostrar la preferencia de algún fármaco en particular', 'Sí, todos los estudios coinciden en que la fosfomicina es claramente superior a cualquier otro antibiótico', 'C', 'La guía establece (nivel 1a) que la mayoría de los antibióticos usados en el tratamiento de las infecciones del tracto urinario bajo son efectivos en el embarazo, y que los estudios realizados no pudieron mostrar la preferencia de algún fármaco en particular; la selección se basa entonces en los patrones de resistencia local y otros factores.', 'Enfermería - Cuidados de la Mujer, Recién Nacido, Niño y Adolescente', 'GPC MSP Ecuador – IVU en el embarazo 2013'),
  ('d66fdc18-4c69-5eb6-b36b-12f15afa7fca', 'Según la GPC del MSP de Ecuador sobre infección de vías urinarias en el embarazo, ¿cuáles son los antibióticos que se deben iniciar previa toma de muestra para urocultivo, según la evidencia de farmacorresistencia local en Ecuador?', 'Solamente amoxicilina/clavulánico', 'Únicamente ampicilina/sulbactam en dosis altas', 'Exclusivamente trimetoprim con sulfametoxasol', 'Nitrofurantoína, fosfomicina o cefalosporinas de segunda generación, según los esquemas específicos descritos', 'D', 'La guía establece que, previa toma de muestra para urocultivo, se inicia tratamiento con uno de los siguientes antibióticos según evidencia de farmacorresistencia local: nitrofurantoína liberación retardada 100 mg cada 12 horas o nitrofurantoína 50-100 mg cada 6 horas (ambas no sobre 37 semanas), fosfomicina 3 g VO dosis única o fosfomicina 500 mg VO cada 8 horas, y cefalosporinas de segunda generación 250-500 mg VO cada 6 horas.', 'Enfermería - Cuidados de la Mujer, Recién Nacido, Niño y Adolescente', 'GPC MSP Ecuador – IVU en el embarazo 2013'),
  ('759d8eeb-1d6f-555c-a304-4088cd791149', 'Una paciente embarazada de 20 semanas será tratada con nitrofurantoína de liberación retardada (macrocristalina) para BA confirmada por urocultivo. Según la GPC del MSP de Ecuador sobre infección de vías urinarias en el embarazo, ¿cuál es el esquema de dosificación recomendado?', '100 mg cada 12 horas (no sobre 37 semanas de embarazo)', '400 mg cada 6 horas sin límite de edad gestacional', '50 mg una vez a la semana durante todo el embarazo', '100 mg cada 12 horas, incluso después de las 37 semanas de embarazo', 'A', 'La guía establece que el esquema de nitrofurantoína liberación retardada (macrocristalina) es de 100 mg cada 12 horas, especificando que no debe usarse sobre las 37 semanas de embarazo.', 'Enfermería - Cuidados de la Mujer, Recién Nacido, Niño y Adolescente', 'GPC MSP Ecuador – IVU en el embarazo 2013'),
  ('e21b9017-cd15-507f-b7cc-141e7e1f47c2', 'Según la GPC del MSP de Ecuador sobre infección de vías urinarias en el embarazo, ¿cuál es el esquema de dosificación de la nitrofurantoína microcristalina (no de liberación retardada) para el tratamiento de BA?', '500 mg cada 24 horas por 3 días', '50-100 mg cada 6 horas (no sobre 37 semanas de embarazo)', '1 g en dosis única', '200 mg cada 4 horas durante 14 días consecutivos', 'B', 'La guía establece que la nitrofurantoína microcristalina se dosifica en 50-100 mg cada 6 horas, no sobre las 37 semanas de embarazo, como una de las opciones de tratamiento empírico para BA y cistitis.', 'Enfermería - Cuidados de la Mujer, Recién Nacido, Niño y Adolescente', 'GPC MSP Ecuador – IVU en el embarazo 2013'),
  ('7be8f0a9-5611-5d26-9831-14af658142f3', 'Según la GPC del MSP de Ecuador sobre infección de vías urinarias en el embarazo, ¿cuáles son los dos esquemas de fosfomicina disponibles para el tratamiento de BA y cistitis en el embarazo?', 'Fosfomicina exclusivamente por vía intramuscular en dosis única', 'Fosfomicina 3 g VO cada 6 horas por 7 días', 'Fosfomicina 3 g VO dosis única, o fosfomicina 500 mg VO cada 8 horas', 'Fosfomicina 1 g VO cada 24 horas por 10 días exclusivamente', 'C', 'La guía establece los dos esquemas de fosfomicina disponibles: fosfomicina 3 g VO dosis única, y fosfomicina 500 mg VO cada 8 horas, ambos entre las opciones de tratamiento empírico según la resistencia local.', 'Enfermería - Cuidados de la Mujer, Recién Nacido, Niño y Adolescente', 'GPC MSP Ecuador – IVU en el embarazo 2013'),
  ('dd1f2a8c-0e22-5125-bc08-a641bb05376b', 'Según la GPC del MSP de Ecuador sobre infección de vías urinarias en el embarazo, ¿cuál es el esquema de cefalosporinas de segunda generación recomendado para el tratamiento de BA y cistitis?', '2 g VO en dosis única', '1 g IV cada 24 horas', '100 mg VO cada 12 horas', '250-500 mg VO cada 6 horas', 'D', 'La guía establece que el esquema recomendado de cefalosporinas de segunda generación es de 250-500 mg VO cada 6 horas, dentro de las opciones de tratamiento empírico para BA y cistitis.', 'Enfermería - Cuidados de la Mujer, Recién Nacido, Niño y Adolescente', 'GPC MSP Ecuador – IVU en el embarazo 2013'),
  ('163159f1-1566-5da3-8c51-aaec6d5e3016', 'Según la GPC del MSP de Ecuador sobre infección de vías urinarias en el embarazo, ¿por qué la nitrofurantoína es considerada segura y de bajo nivel de resistencia durante el embarazo?', 'Porque logra concentraciones terapéuticas solo en orina y presenta un nivel bajo de resistencia a los uropatógenos, incluido el Ecuador', 'Porque es el único antibiótico con actividad frente a hongos', 'Porque no cruza la barrera placentaria en ninguna etapa del embarazo', 'Porque alcanza altas concentraciones plasmáticas sistémicas que garantizan eficacia en cualquier tejido', 'A', 'La guía establece (2b) que la nitrofurantoína es segura durante el embarazo y logra concentraciones terapéuticas solo en orina, presentando un nivel bajo de resistencia a los uropatógenos, incluido el Ecuador.', 'Enfermería - Cuidados de la Mujer, Recién Nacido, Niño y Adolescente', 'GPC MSP Ecuador – IVU en el embarazo 2013'),
  ('8ffa9bb0-2fa3-5baa-ad2f-8c73d3af3034', 'Según la GPC del MSP de Ecuador sobre infección de vías urinarias en el embarazo, ¿qué ocurre con las concentraciones plasmáticas de los betalactámicos durante el embarazo y qué implicación tiene esto?', 'Se eliminan completamente en el primer trimestre, sin ningún efecto terapéutico', 'Disminuyen alrededor de 50% en el embarazo, lo que puede aumentar los niveles de resistencia', 'Aumentan al doble durante el embarazo, mejorando su eficacia', 'Permanecen sin cambios durante todo el embarazo', 'B', 'La guía establece (2b) que las concentraciones plasmáticas de los betalactámicos disminuyen alrededor de 50% en el embarazo, lo que puede aumentar los niveles de resistencia, dato relevante para la elección terapéutica.', 'Enfermería - Cuidados de la Mujer, Recién Nacido, Niño y Adolescente', 'GPC MSP Ecuador – IVU en el embarazo 2013'),
  ('a3e6a139-e1d4-509d-8022-792fdc386a39', 'Según la GPC del MSP de Ecuador sobre infección de vías urinarias en el embarazo, ¿cuál es la cefalosporina que se usa con mayor frecuencia en el embarazo?', 'Cefotaxima', 'Ceftriaxona', 'Cefalexina', 'Cefepime', 'C', 'La guía establece (B) que la cefalexina es la cefalosporina que se usa con mayor frecuencia en el embarazo, señalando que las cefalosporinas son bien toleradas y seguras durante la gestación.', 'Enfermería - Cuidados de la Mujer, Recién Nacido, Niño y Adolescente', 'GPC MSP Ecuador – IVU en el embarazo 2013'),
  ('f2b5c121-6504-5876-84b4-a0f8ecd9f077', 'Según la GPC del MSP de Ecuador sobre infección de vías urinarias en el embarazo, ¿por qué motivo la ampicilina en presentación oral ya no consta dentro del Cuadro Nacional de Medicamentos Básicos (CNMB) del Ecuador?', 'Debido a que su fabricación fue descontinuada a nivel mundial', 'Debido a reacciones alérgicas graves reportadas exclusivamente en población pediátrica', 'Debido a su alto costo en comparación con la nitrofurantoína', 'Debido a que la ampicilina y amoxicilina, con o sin inhibidores de betalactamasas, y las sulfas tienen tasas de resistencia local que superan las recomendaciones internacionales', 'D', 'La guía establece que la ampicilina y amoxicilina, con o sin inhibidores de betalactamasas, y las sulfas tienen tasas de resistencia local que superan las recomendaciones internacionales, y que por este motivo la ampicilina en presentación oral ya no consta dentro del Cuadro Nacional de Medicamentos Básicos (CNMB, octava revisión, 2010).', 'Enfermería - Cuidados de la Mujer, Recién Nacido, Niño y Adolescente', 'GPC MSP Ecuador – IVU en el embarazo 2013'),
  ('e9bad9b0-702a-5115-9ca1-63f76c73d19d', 'Una paciente embarazada en el primer trimestre está siendo evaluada para tratamiento antibiótico de una BA confirmada. Según la GPC del MSP de Ecuador sobre infección de vías urinarias en el embarazo, ¿por qué está contraindicado el trimetoprim con sulfametoxasol en el primer trimestre del embarazo?', 'Por su inhibición del metabolismo de folatos y asociación a defectos del tubo neural', 'Por su ineficacia total frente a Escherichia coli', 'Por causar exclusivamente reacciones alérgicas leves sin otra repercusión', 'Por no tener ninguna forma de presentación oral disponible', 'A', 'La guía establece (B/2b-3) que el uso de trimetoprim con sulfametoxasol está contraindicado en el primer trimestre por su inhibición del metabolismo de folatos y su asociación a defectos del tubo neural, y que en el tercer trimestre se ha asociado con ictericia en el recién nacido, por lo que se sugiere no utilizarlo en embarazadas por su potencial teratogenicidad.', 'Enfermería - Cuidados de la Mujer, Recién Nacido, Niño y Adolescente', 'GPC MSP Ecuador – IVU en el embarazo 2013'),
  ('4d0d58ac-982e-5c27-b66c-40cad517e43a', 'Según la GPC del MSP de Ecuador sobre infección de vías urinarias en el embarazo, ¿con qué se ha asociado el uso de trimetoprim con sulfametoxasol en el tercer trimestre del embarazo?', 'Con sordera congénita en el recién nacido', 'Con ictericia en el recién nacido, al desplazar a la bilirrubina de su unión con la albúmina', 'Con malformaciones cardíacas congénitas exclusivamente', 'No se ha reportado ninguna asociación en el tercer trimestre', 'B', 'La guía establece que en el tercer trimestre del embarazo el uso de trimetoprim con sulfametoxasol se ha asociado con ictericia en el recién nacido, ya que desplaza a la bilirrubina de su unión con la albúmina.', 'Enfermería - Cuidados de la Mujer, Recién Nacido, Niño y Adolescente', 'GPC MSP Ecuador – IVU en el embarazo 2013'),
  ('f4e2c519-e63a-503f-a4bb-027ea182a898', 'Una paciente inicia tratamiento antibiótico para BA confirmada por urocultivo, sin persistencia posterior de la bacteriuria. Según la GPC del MSP de Ecuador sobre infección de vías urinarias en el embarazo, ¿cuál es la duración mínima recomendada del tratamiento?', 'No menor a 21 días en todos los casos', '24 horas en dosis única, sin excepción', 'No menor a siete días', 'Tres días, igual que en mujeres no embarazadas con cistitis simple', 'C', 'La guía establece (D 4) que el tratamiento debe tener una duración no menor a siete días, y que en caso de persistir la bacteriuria, el tratamiento debe durar de siete a 14 días, señalando que no hay suficiente evidencia que apoye menor recurrencia de BA con tratamientos cortos.', 'Enfermería - Cuidados de la Mujer, Recién Nacido, Niño y Adolescente', 'GPC MSP Ecuador – IVU en el embarazo 2013'),
  ('ed481c89-bea9-5f69-a5ae-342598f48380', 'Una paciente completó siete días de tratamiento antibiótico para BA, pero el urocultivo de control resultó nuevamente positivo para el mismo germen. Según la GPC del MSP de Ecuador sobre infección de vías urinarias en el embarazo, ¿qué duración de tratamiento corresponde en este caso de persistencia de la bacteriuria?', '30 días continuos sin reevaluación', 'Un día adicional únicamente', 'Debe suspenderse todo tratamiento antibiótico de forma definitiva', 'Siete a 14 días', 'D', 'La guía establece que en caso de persistir la bacteriuria, el tratamiento debe durar de siete a 14 días, ampliando la duración inicial mínima de siete días.', 'Enfermería - Cuidados de la Mujer, Recién Nacido, Niño y Adolescente', 'GPC MSP Ecuador – IVU en el embarazo 2013'),
  ('c7d299b9-ed2f-5609-947d-fabb3fe636ad', 'Una paciente embarazada de 22 semanas presenta cistitis aguda confirmada clínicamente, sin síntomas vaginales asociados. Según la GPC del MSP de Ecuador sobre infección de vías urinarias en el embarazo, ¿qué esquema antibiótico corresponde utilizar?', 'Uno de los esquemas recomendados para BA: nitrofurantoína, fosfomicina o cefalosporinas de segunda generación, según patrones de resistencia local', 'Trimetoprim con sulfametoxasol como primera línea, sin restricción por trimestre', 'Ningún antibiótico, ya que la cistitis se resuelve espontáneamente sin tratamiento', 'Un antibiótico completamente distinto, exclusivo para cistitis, no utilizado en BA', 'A', 'La guía establece que las recomendaciones de tratamiento para la cistitis durante el embarazo son las mismas que para BA, por lo que corresponde utilizar los mismos esquemas descritos (nitrofurantoína, fosfomicina o cefalosporinas de segunda generación) según los patrones de resistencia local.', 'Enfermería - Cuidados de la Mujer, Recién Nacido, Niño y Adolescente', 'GPC MSP Ecuador – IVU en el embarazo 2013'),
  ('e538a01d-fb02-5672-91c8-9cad431b5b9e', 'Según la GPC del MSP de Ecuador sobre infección de vías urinarias en el embarazo, ¿la cistitis puede ser incapacitante para las actividades de la vida diaria y laboral de la paciente?', 'La guía no aborda el impacto funcional de la cistitis en la vida diaria', 'Sí, la cistitis puede ser incapacitante para las actividades de la vida diaria y laboral', 'No, la cistitis nunca interfiere con las actividades cotidianas de la paciente', 'Solo se considera incapacitante si progresa a pielonefritis', 'B', 'La guía reconoce explícitamente, en los criterios de seguimiento y vigilancia, que la cistitis puede ser incapacitante para las actividades de la vida diaria y laboral, lo que fundamenta la recomendación de expedir un certificado de descanso laboral cuando se considere necesario.', 'Enfermería - Cuidados de la Mujer, Recién Nacido, Niño y Adolescente', 'GPC MSP Ecuador – IVU en el embarazo 2013'),
  ('edfdc30a-e18e-5837-85e8-8ee0dc55871b', 'Una paciente con cistitis diagnosticada solicita un certificado de descanso laboral debido a la sintomatología que le impide desempeñar sus actividades. Según la GPC del MSP de Ecuador sobre infección de vías urinarias en el embarazo, ¿por cuántos días se debe expedir el certificado de descanso laboral según se considere necesario?', 'Un mes completo en todos los casos', 'No se contempla la expedición de certificados de descanso laboral en la guía', 'Uno a tres días', 'Diez a quince días de forma estándar', 'C', 'La guía establece que se debe expedir un certificado de descanso laboral por uno a tres días según se considere necesario, en el contexto de los criterios de seguimiento y vigilancia de la cistitis.', 'Enfermería - Cuidados de la Mujer, Recién Nacido, Niño y Adolescente', 'GPC MSP Ecuador – IVU en el embarazo 2013'),
  ('63b4a4d0-8a3f-5604-98ee-22e38ab2bb44', 'Según la GPC del MSP de Ecuador sobre infección de vías urinarias en el embarazo, ¿qué se debe realizar luego del tratamiento de cistitis para corroborar que se eliminó la bacteriuria?', 'Ninguna prueba adicional, ya que se asume la curación automáticamente', 'Una tomografía computarizada abdominal', 'Una biopsia renal', 'Un urocultivo de control', 'D', 'La guía establece, en los criterios de seguimiento y vigilancia, que luego del tratamiento debe realizarse un urocultivo de control para corroborar que se eliminó la bacteriuria.', 'Enfermería - Cuidados de la Mujer, Recién Nacido, Niño y Adolescente', 'GPC MSP Ecuador – IVU en el embarazo 2013'),
  ('bb4c1c77-e3d9-5c38-9b86-fcb96a3a8826', 'Una paciente completa tratamiento antibiótico para cistitis. El equipo de salud plantea el esquema de seguimiento posterior. Según la GPC del MSP de Ecuador sobre infección de vías urinarias en el embarazo, ¿cuál es el fundamento para realizar el urocultivo de control tras el tratamiento de BA o cistitis?', 'Documentar el éxito de la erradicación bacteriana', 'Sustituir el tamizaje de infecciones de transmisión sexual', 'Evaluar la función tiroidea materna', 'Determinar el sexo fetal', 'A', 'La guía establece, en la sección de definiciones y clasificación, que luego de completar el tratamiento antibiótico tanto de BA como de cistitis, se debe realizar urocultivo de control para documentar el éxito de la erradicación.', 'Enfermería - Cuidados de la Mujer, Recién Nacido, Niño y Adolescente', 'GPC MSP Ecuador – IVU en el embarazo 2013'),
  ('375ec30f-2d37-5b38-9f25-65bcb964eb8d', 'Una paciente con antecedente de cistitis presenta un nuevo episodio sintomático confirmado clínicamente durante el mismo embarazo. Según la GPC del MSP de Ecuador sobre infección de vías urinarias en el embarazo, ¿qué uropatógeno es más probable encontrar en este nuevo episodio, considerando los datos epidemiológicos de la GPC del MSP de Ecuador sobre infección de vías urinarias en el embarazo?', 'Ningún patógeno específico, ya que las recurrencias son siempre estériles', 'Escherichia coli, presente en 70% a 80% de las infecciones recurrentes', 'Estreptococo del grupo B de forma predominante', 'Virus del papiloma humano', 'B', 'La guía establece que la etiología bacteriana de la BA y cistitis en mujeres embarazadas y no embarazadas es similar, encontrando Escherichia coli en 80% a 90% de las infecciones iniciales y en 70% a 80% de las recurrentes, por lo que en un episodio recurrente de cistitis lo más probable es encontrar nuevamente este germen.', 'Enfermería - Cuidados de la Mujer, Recién Nacido, Niño y Adolescente', 'GPC MSP Ecuador – IVU en el embarazo 2013'),
  ('777a7935-b7a5-51ad-b1b6-5666562be747', 'Según la GPC del MSP de Ecuador sobre infección de vías urinarias en el embarazo, ¿qué se logra al referir a la paciente a centros con adecuada complejidad y capacidad resolutiva una vez establecido el diagnóstico?', 'Sustituir por completo el manejo en el primer nivel de atención para toda paciente embarazada', 'Eliminar la necesidad de urocultivo de control', 'Tomar decisiones de especialidad acertadas y oportunas', 'Retrasar innecesariamente el tratamiento antibiótico', 'C', 'La guía establece, en los criterios de referencia y contrarreferencia, que referir a la paciente a centros con adecuada complejidad y capacidad resolutiva una vez que se ha establecido el diagnóstico permite tomar decisiones de especialidad acertadas y oportunas.', 'Enfermería - Cuidados de la Mujer, Recién Nacido, Niño y Adolescente', 'GPC MSP Ecuador – IVU en el embarazo 2013'),
  ('2211f105-b611-56f9-97d6-339439b67d6d', 'Una paciente embarazada con IVU no responde adecuadamente al tratamiento antibiótico de primera línea instaurado en el primer nivel de atención. Según la GPC del MSP de Ecuador sobre infección de vías urinarias en el embarazo, ¿corresponde la referencia inmediata al nivel superior en este caso?', 'No, la respuesta inadecuada al tratamiento no es criterio de referencia según esta guía', 'Solo se refiere si además presenta fiebre mayor a 40°C', 'No, se debe insistir con el mismo esquema antibiótico por al menos 21 días adicionales antes de referir', 'Sí, la respuesta inadecuada al tratamiento es uno de los criterios de referencia inmediata al nivel superior', 'D', 'La guía establece que la referencia inmediata al nivel superior de embarazadas con IVU está indicada en los siguientes casos: respuesta inadecuada al tratamiento, intolerancia y/o alergia a los fármacos de primer nivel, diagnóstico clínico de pielonefritis, y complicaciones obstétricas relacionadas a IVU (parto pretérmino, ruptura de membranas).', 'Enfermería - Cuidados de la Mujer, Recién Nacido, Niño y Adolescente', 'GPC MSP Ecuador – IVU en el embarazo 2013'),
  ('71385ec4-b67f-56f1-b007-bf8c66d6f374', 'Una paciente embarazada refiere alergia documentada a la nitrofurantoína, fármaco de primera línea prescrito en el primer nivel de atención para tratar su BA. Según la GPC del MSP de Ecuador sobre infección de vías urinarias en el embarazo, ¿corresponde la referencia inmediata al nivel superior en este caso?', 'Sí, la intolerancia y/o alergia a los fármacos de primer nivel es uno de los criterios de referencia inmediata', 'No, la alergia a fármacos nunca es criterio de referencia según la guía', 'Solo se refiere si la alergia produce shock anafiláctico documentado', 'No, se debe simplemente duplicar la dosis del mismo fármaco', 'A', 'La guía establece explícitamente que la intolerancia y/o alergia a los fármacos de primer nivel es uno de los criterios de referencia inmediata al nivel superior en embarazadas con IVU.', 'Enfermería - Cuidados de la Mujer, Recién Nacido, Niño y Adolescente', 'GPC MSP Ecuador – IVU en el embarazo 2013'),
  ('51ede33e-da64-5b8f-b635-3b9b4be55c66', 'Una paciente embarazada presenta diagnóstico clínico de pielonefritis, con fiebre, escalofrío y dolor costovertebral. Según la GPC del MSP de Ecuador sobre infección de vías urinarias en el embarazo, ¿qué conducta corresponde en el primer nivel de atención?', 'Observación sin tratamiento antibiótico hasta confirmar el urocultivo', 'Referencia inmediata al nivel superior, dado que el diagnóstico clínico de pielonefritis es uno de los criterios de referencia inmediata', 'Manejo ambulatorio con nitrofurantoína, igual que para BA o cistitis', 'Alta domiciliaria con control en 15 días', 'B', 'La guía establece que la referencia inmediata al nivel superior de embarazadas con IVU está indicada, entre otros casos, ante el diagnóstico clínico de pielonefritis, dado el mayor riesgo de complicaciones asociado a esta presentación.', 'Enfermería - Cuidados de la Mujer, Recién Nacido, Niño y Adolescente', 'GPC MSP Ecuador – IVU en el embarazo 2013'),
  ('d43d4838-e366-5e4a-86e9-3f8044c9b0fd', 'Según la GPC del MSP de Ecuador sobre infección de vías urinarias en el embarazo, ¿cuáles son las complicaciones obstétricas relacionadas a IVU que constituyen criterio de referencia inmediata?', 'Exclusivamente la restricción del crecimiento fetal', 'Únicamente la preeclampsia severa', 'Parto pretérmino y ruptura de membranas', 'Solamente el embarazo múltiple', 'C', 'La guía establece que la referencia inmediata al nivel superior está indicada, entre otros criterios, con complicaciones obstétricas relacionadas a IVU: parto pretérmino y ruptura de membranas.', 'Enfermería - Cuidados de la Mujer, Recién Nacido, Niño y Adolescente', 'GPC MSP Ecuador – IVU en el embarazo 2013'),
  ('9cf12df5-499b-5d22-a6d8-cfbb2ccb7374', 'Una paciente fue referida a un especialista por un cuadro complicado de IVU. Tras superar la fase aguda, el especialista considera que puede continuar su control en el primer nivel de atención. Según la GPC del MSP de Ecuador sobre infección de vías urinarias en el embarazo, ¿qué debe incluir el proceso de contrarreferencia en este caso?', 'Solamente la firma del especialista, sin detalle clínico alguno', 'Únicamente la fecha de la próxima cita, sin más información', 'No se requiere ningún tipo de informe escrito para la contrarreferencia', 'Indicaciones claras del médico especialista sobre manejo subsecuente, con informe de acciones y resultados de la atención de especialidad', 'D', 'La guía establece que, superada la fase de atención del cuadro complicado de IVU, se debe remitir al nivel primario con indicaciones claras del médico especialista sobre manejo subsecuente, con informe de acciones y resultados de la atención de especialidad.', 'Enfermería - Cuidados de la Mujer, Recién Nacido, Niño y Adolescente', 'GPC MSP Ecuador – IVU en el embarazo 2013'),
  ('7ff27a81-6260-500f-a25b-f7eb369a4321', 'Según la GPC del MSP de Ecuador sobre infección de vías urinarias en el embarazo, ¿qué manual debe aplicar el equipo de Mejoramiento Continuo de la Calidad para el monitoreo de calidad de la GPC del MSP de Ecuador sobre infección de vías urinarias en el embarazo?', 'El Manual de Estándares, Indicadores e Instrumentos para medir la Calidad de la Atención Materno Neonatal del Ministerio de Salud Pública del Ecuador', 'El instrumento AGREE II', 'El Manual para la referencia y contrarreferencia de pacientes y usuarios exclusivamente', 'El Cuadro Nacional de Medicamentos Básicos y Registro Terapéutico exclusivamente', 'A', 'La guía establece que el equipo de Mejoramiento Continuo de la Calidad debe aplicar el Manual de Estándares, Indicadores e Instrumentos para medir la Calidad de la Atención Materno Neonatal del Ministerio de Salud Pública del Ecuador.', 'Enfermería - Cuidados de la Mujer, Recién Nacido, Niño y Adolescente', 'GPC MSP Ecuador – IVU en el embarazo 2013'),
  ('0e8f60b8-0931-509b-8bcd-42b43e6cb81a', 'Según la GPC del MSP de Ecuador sobre infección de vías urinarias en el embarazo, ¿cuál es el estándar e indicador principal para el monitoreo de cumplimiento de la GPC del MSP de Ecuador sobre infección de vías urinarias en el embarazo?', 'El indicador 10, referente exclusivamente a la tasa de cesáreas', 'El indicador de proceso 8 C de complicaciones obstétricas (% de pacientes con infección de causa obstétrica que fueron manejadas de acuerdo a la norma)', 'No existe ningún indicador específico para el monitoreo de esta guía', 'El indicador 1, referente exclusivamente al número de camas hospitalarias disponibles', 'B', 'La guía establece que el estándar e indicador de proceso 8 C de complicaciones obstétricas (porcentaje de pacientes con infección de causa obstétrica que fueron manejadas de acuerdo a la norma) es el principal para el monitoreo de cumplimiento de esta guía de práctica clínica.', 'Enfermería - Cuidados de la Mujer, Recién Nacido, Niño y Adolescente', 'GPC MSP Ecuador – IVU en el embarazo 2013'),
  ('74ad47b0-cb55-5071-9340-b01838c64e37', 'Según la GPC del MSP de Ecuador sobre infección de vías urinarias en el embarazo, ¿qué mide el indicador 8 D mencionado como parte del monitoreo de calidad relacionado con la GPC del MSP de Ecuador sobre infección de vías urinarias en el embarazo?', '% de recién nacidos con bajo peso al nacer, independientemente de la causa', 'Tasa de mortalidad materna directa por todas las causas', '% de amenazas de parto pretérmino menores a 34 semanas en las que se administró a la madre corticoides antenatales', '% de pacientes con IVU que recibieron nitrofurantoína como primera línea', 'C', 'La guía enumera entre los indicadores relacionados el 8 D: porcentaje de amenazas de parto pretérmino menores a 34 semanas en las que se administró a la madre corticoides antenatales.', 'Enfermería - Cuidados de la Mujer, Recién Nacido, Niño y Adolescente', 'GPC MSP Ecuador – IVU en el embarazo 2013'),
  ('56ca3850-2f2e-546e-b38b-9ea250683816', 'Según la GPC del MSP de Ecuador sobre infección de vías urinarias en el embarazo, ¿qué mide el indicador 12 mencionado en el apartado de monitoreo de calidad?', 'Tasa de partos por cesárea en el área de salud', '% de embarazadas que recibieron control prenatal completo', '% de recién nacidos vacunados en las primeras 24 horas de vida', '% de complicaciones obstétricas atendidas en las unidades del Área de Salud, de los esperados', 'D', 'La guía enumera entre los indicadores relacionados el 12: porcentaje de complicaciones obstétricas atendidas en las unidades del Área de Salud, de los esperados.', 'Enfermería - Cuidados de la Mujer, Recién Nacido, Niño y Adolescente', 'GPC MSP Ecuador – IVU en el embarazo 2013'),
  ('5e5405e2-f0f4-5acb-bd54-1fbed26a7549', 'Según la GPC del MSP de Ecuador sobre infección de vías urinarias en el embarazo, ¿qué mide el indicador de entrada número 1 mencionado en el apartado de monitoreo de calidad?', '% de insumos, equipos y medicamentos esenciales con los que cuenta cada Unidad Operativa para la atención de la salud materna y del/a recién nacido/a', 'Número de médicos especialistas disponibles por unidad de salud', '% de pacientes satisfechas con la atención recibida', '% de embarazadas que solicitaron cita en línea', 'A', 'La guía establece que el indicador 1, de tipo entrada, corresponde al porcentaje de insumos, equipos y medicamentos esenciales con los que cuenta cada Unidad Operativa para la atención de la salud materna y del/a recién nacido/a.', 'Enfermería - Cuidados de la Mujer, Recién Nacido, Niño y Adolescente', 'GPC MSP Ecuador – IVU en el embarazo 2013'),
  ('757978db-a1f8-56e5-8ca9-b35f42092c9c', 'Según la GPC del MSP de Ecuador sobre infección de vías urinarias en el embarazo, ¿los indicadores adicionales de entrada, proceso y salida mencionados en el apartado de monitoreo de calidad son de aplicación obligatoria en todos los casos?', 'Sí, son de aplicación obligatoria y simultánea en cada consulta prenatal', 'No necesariamente; la guía indica que estos otros indicadores ''también pueden ser evaluados si aplican al caso''', 'Solo se aplican en pacientes con antecedente de aborto', 'Solo se aplican en hospitales de tercer nivel, nunca en el primer nivel de atención', 'B', 'La guía establece que, además del indicador principal 8 C, existen otros indicadores de entrada, proceso y salida relacionados que ''también pueden ser evaluados si aplican al caso'', lo que indica que su aplicación depende de la pertinencia según el contexto, y no que sean obligatorios en todos los casos.', 'Enfermería - Cuidados de la Mujer, Recién Nacido, Niño y Adolescente', 'GPC MSP Ecuador – IVU en el embarazo 2013'),
  ('bdaeef0f-b0d6-514b-b5cd-e4429782cda4', 'Una paciente llega a su primera consulta prenatal. Según el flujograma de la GPC del MSP de Ecuador sobre infección de vías urinarias en el embarazo, el primer paso es determinar si presenta datos clínicos de vaginitis. Según el Anexo 1 (Flujograma de diagnóstico y tratamiento de bacteriuria asintomática), si la paciente NO presenta datos clínicos de vaginitis, ¿cuál es el siguiente paso?', 'Tratar la vaginitis de forma preventiva aunque no existan datos clínicos', 'Iniciar tratamiento antibiótico empírico inmediato sin urocultivo', 'Solicitar urocultivo de tamizaje en semana 12-16, o en la primera consulta prenatal si esta es posterior a la semana 12-16', 'Derivar directamente a especialista sin más evaluación', 'C', 'El Anexo 1 (Flujograma de diagnóstico y tratamiento de bacteriuria asintomática en embarazadas) establece que, si la paciente no presenta datos clínicos de vaginitis, se debe solicitar urocultivo de tamizaje en la semana 12-16, o en la primera consulta prenatal si esta es posterior a la semana 12-16.', 'Enfermería - Cuidados de la Mujer, Recién Nacido, Niño y Adolescente', 'GPC MSP Ecuador – IVU en el embarazo 2013'),
  ('90e56454-a744-53d2-a034-5d177b961ebb', 'Según el Anexo 1 de la GPC del MSP de Ecuador sobre infección de vías urinarias en el embarazo, si el urocultivo de tamizaje resulta positivo, ¿cuál es la conducta siguiente según el flujograma?', 'Repetir el urocultivo semanalmente sin iniciar tratamiento', 'Referencia inmediata sin tratamiento antibiótico previo', 'Control prenatal de bajo riesgo sin ninguna otra intervención', 'Iniciar antibioticoterapia con los esquemas recomendados y luego solicitar urocultivo de control', 'D', 'El Anexo 1 establece que, ante un cultivo positivo, se debe iniciar antibioticoterapia (con los esquemas de nitrofurantoína, fosfomicina o cefalosporinas de segunda generación descritos) y posteriormente solicitar urocultivo de control.', 'Enfermería - Cuidados de la Mujer, Recién Nacido, Niño y Adolescente', 'GPC MSP Ecuador – IVU en el embarazo 2013'),
  ('98562820-493f-58c7-a912-26a08b6aed2c', 'Una paciente completó tratamiento antibiótico por BA. Su urocultivo de control resulta nuevamente positivo. Según el Anexo 1 de la GPC del MSP de Ecuador sobre infección de vías urinarias en el embarazo, ¿cuál es la conducta indicada tras un urocultivo de control positivo?', 'Referencia por BA recurrente', 'Suspender todo control hasta el parto', 'Repetir exactamente el mismo esquema antibiótico sin evaluación adicional ni referencia', 'Control prenatal de bajo riesgo sin más intervención', 'A', 'El Anexo 1 (Flujograma de diagnóstico y tratamiento de BA) establece que, si el urocultivo de control resulta positivo tras el tratamiento antibiótico inicial, la conducta indicada es la referencia por BA recurrente.', 'Enfermería - Cuidados de la Mujer, Recién Nacido, Niño y Adolescente', 'GPC MSP Ecuador – IVU en el embarazo 2013'),
  ('6afbb578-9dfa-5f27-af57-55af8841a4de', 'Una paciente embarazada presenta sintomatología de IVU baja: urgencia, frecuencia, disuria y piuria. Se evalúa si presenta datos clínicos de afección sistémica. Según el Anexo 2 (Flujograma de diagnóstico y tratamiento de cistitis en embarazadas), si la paciente SÍ presenta datos clínicos de afección sistémica, ¿cuál es la conducta indicada?', 'Referencia a nivel superior por IVU recurrente, sin excepción', 'Probable pielonefritis, con referencia a especialista', 'Control prenatal de bajo riesgo sin más intervención', 'Dar tratamiento con antibioticoterapia ambulatoria de primera línea y solicitar urocultivo de control', 'B', 'El Anexo 2 (Flujograma de diagnóstico y tratamiento de cistitis en embarazadas) establece que, si la paciente presenta datos clínicos de afección sistémica, la conducta es ''probable pielonefritis, referencia a especialista'', diferenciándose de la rama sin afección sistémica, en la que se indica dar tratamiento con antibioticoterapia y solicitar urocultivo de control.', 'Enfermería - Cuidados de la Mujer, Recién Nacido, Niño y Adolescente', 'GPC MSP Ecuador – IVU en el embarazo 2013'),
  ('8e177fda-58a2-5f02-add2-6831eccfc66e', 'Según el Anexo 3 de la GPC del MSP de Ecuador sobre infección de vías urinarias en el embarazo, ¿cuál es el mecanismo de acción de la nitrofurantoína?', 'Bloquea los canales de sodio de la membrana bacteriana', 'Inhibe la síntesis de la pared celular bacteriana mediante la inactivación de la enzima UDP-N-acetilglucosamina-3-0-enolpiruvil transferasa (MurA)', 'Inhibe la acetil-coenzima A bacteriana, interfiriendo con el metabolismo de los carbohidratos e impidiendo la formación de la pared celular', 'Inhibe la síntesis de folatos bacterianos de forma exclusiva', 'C', 'La ficha del Anexo 3 sobre nitrofurantoína establece que este fármaco inhibe la acetil-coenzima A bacteriana, interfiriendo con el metabolismo de los carbohidratos e impidiendo la formación de la pared celular, y que su actividad antibacteriana depende de la acidez de la orina.', 'Enfermería - Cuidados de la Mujer, Recién Nacido, Niño y Adolescente', 'GPC MSP Ecuador – IVU en el embarazo 2013'),
  ('240fdf80-55ab-5d0e-abeb-c80f61bd51ce', 'Una paciente embarazada con antecedente de déficit de glucosa-6-fosfato deshidrogenasa (G6PD) requiere tratamiento antibiótico para BA. Según el Anexo 3 de la GPC del MSP de Ecuador sobre infección de vías urinarias en el embarazo, ¿qué riesgo específico presenta la nitrofurantoína en esta paciente?', 'No presenta ningún riesgo adicional en pacientes con deficiencia de G6PD', 'Está formalmente contraindicada solo en pacientes con hipertiroidismo', 'Produce exclusivamente hepatotoxicidad en estos pacientes, sin riesgo hematológico', 'Puede inducir anemia hemolítica en pacientes con deficiencia de G6PD', 'D', 'La ficha de nitrofurantoína del Anexo 3 establece que, aunque este fármaco se clasifica dentro de la categoría B de riesgo en el embarazo, puede inducir anemia hemolítica en pacientes con deficiencia de G6PD y en pacientes con insuficiente producción de glutatión.', 'Enfermería - Cuidados de la Mujer, Recién Nacido, Niño y Adolescente', 'GPC MSP Ecuador – IVU en el embarazo 2013'),
  ('eeb4f937-9017-518c-a4a6-614971c60ec0', 'Según el Anexo 3 de la GPC del MSP de Ecuador sobre infección de vías urinarias en el embarazo, ¿por qué no se recomienda la administración de nitrofurantoína en las últimas semanas del embarazo (38 a 42 semanas) ni durante el parto?', 'Porque la producción de glutatión es insuficiente en el neonato durante ese período, lo que aumenta el riesgo de anemia hemolítica neonatal', 'Porque produce malformaciones congénitas graves si se administra en el tercer trimestre tardío', 'Porque interfiere con el trabajo de parto al inhibir las contracciones uterinas', 'Porque el fármaco pierde toda su eficacia antibacteriana después de la semana 38', 'A', 'La ficha de nitrofurantoína del Anexo 3 explica que, como la producción insuficiente de glutatión tiene lugar en el neonato en las últimas semanas (38 a 42 semanas), así como durante el parto, no se recomienda la administración de nitrofurantoína durante este período, por el riesgo de anemia hemolítica neonatal.', 'Enfermería - Cuidados de la Mujer, Recién Nacido, Niño y Adolescente', 'GPC MSP Ecuador – IVU en el embarazo 2013'),
  ('bacd8a15-2a2e-5f04-a73d-c434b8fb05de', 'Según el Anexo 3 de la GPC del MSP de Ecuador sobre infección de vías urinarias en el embarazo, ¿cómo se recomienda administrar la fosfomicina en relación con los alimentos, y por qué?', 'La relación con los alimentos no afecta en absoluto su absorción, según la guía', 'Es conveniente administrarla 2 horas después de las comidas, ya que los alimentos retrasan y/o disminuyen su absorción', 'Debe administrarse siempre junto con las comidas para mejorar su absorción', 'Debe administrarse exclusivamente en ayunas de 12 horas', 'B', 'La ficha de fosfomicina del Anexo 3 indica que los alimentos retrasan y/o disminuyen la absorción del fármaco, por lo que la administración conjunta de alimentos con la fosfomicina vía oral conlleva una reducción en la absorción digestiva; por ello, es conveniente administrarla 2 horas después de las comidas.', 'Enfermería - Cuidados de la Mujer, Recién Nacido, Niño y Adolescente', 'GPC MSP Ecuador – IVU en el embarazo 2013'),
  ('0920da57-eb64-5c8a-adf5-63b97ef4fed5', 'Se dispone de una presentación parenteral intramuscular de fosfomicina que contiene lidocaína. Si una paciente embarazada requiere dosis superiores a 8 g al día, ¿puede administrarse esa misma presentación por vía intravenosa?', 'La vía de administración es irrelevante según la guía', 'Sí, cualquier presentación de fosfomicina puede administrarse indistintamente por vía IM o IV sin ninguna precaución', 'No. La presentación intramuscular contiene lidocaína y no debe usarse por vía intravenosa; corresponde emplear la formulación IV.', 'Sí, siempre que se diluya en solución salina hipertónica', 'C', 'La ficha de fosfomicina del Anexo 3 establece que la presentación parenteral IM contiene lidocaína, por lo que no debe administrarse por vía intravenosa, y que si se precisan dosis superiores a 8 g al día se debe pasar a la administración intravenosa (utilizando la formulación adecuada para esa vía, no la presentación IM con lidocaína).', 'Enfermería - Cuidados de la Mujer, Recién Nacido, Niño y Adolescente', 'GPC MSP Ecuador – IVU en el embarazo 2013'),
  ('bc86ac3f-5e26-592d-884e-a748a521d608', 'Según el Anexo 3 de la GPC del MSP de Ecuador sobre infección de vías urinarias en el embarazo, ¿en qué caso está contraindicada la cefalexina?', 'En cualquier paciente con antecedente de bacteriuria asintomática', 'Únicamente en pacientes mayores de 35 años', 'En todos los casos de embarazo, sin excepción', 'En caso de hipersensibilidad conocida a las cefalosporinas', 'D', 'La ficha de cefalexina del Anexo 3 establece que su contraindicación es el caso de hipersensibilidad conocida a las cefalosporinas, señalando además que en pacientes alérgicos a la penicilina debe administrarse con extrema precaución por el riesgo de reacciones cruzadas de hipersensibilidad, incluyendo anafilaxia.', 'Enfermería - Cuidados de la Mujer, Recién Nacido, Niño y Adolescente', 'GPC MSP Ecuador – IVU en el embarazo 2013'),
  ('07f434d1-bd4c-5273-97ee-4e70ec82f829', 'Según la GPC del MSP de Ecuador sobre prevención, diagnóstico y tratamiento de la hemorragia posparto, ¿cómo se define la hemorragia posparto (HPP)?', 'Pérdida de sangre que supera los 500 mL en un parto vaginal o los 1.000 mL en un parto por cesárea', 'Cualquier sangrado vaginal que ocurra durante las primeras 6 horas posparto, sin importar el volumen', 'Pérdida de sangre mayor a 2.000 mL exclusivamente', 'Pérdida de sangre mayor a 200 mL en cualquier tipo de parto', 'A', 'La guía define la hemorragia posparto como la pérdida de sangre que supera los 500 mL en un parto vaginal y que supera 1.000 mL en un parto por cesárea, señalando además que toda pérdida con posibilidad de producir inestabilidad hemodinámica debe considerarse HPP.', 'Enfermería - Cuidados de la Mujer, Recién Nacido, Niño y Adolescente', 'GPC MSP Ecuador – Hemorragia posparto 2013'),
  ('b7c3bc8d-4fc9-5144-a666-691232830635', 'Una paciente presenta sangrado vaginal abundante a las 8 horas posteriores al parto vaginal. Según la clasificación temporal de la GPC del MSP de Ecuador sobre prevención, diagnóstico y tratamiento de la hemorragia posparto, este cuadro corresponde a:', 'Hemorragia posparto secundaria o tardía', 'Hemorragia posparto primaria o inmediata', 'No se clasifica como HPP por ocurrir después de las 6 horas', 'Hemorragia posparto crónica', 'B', 'La guía define la HPP primaria o inmediata como aquella que se produce dentro de las primeras 24 horas posteriores al parto, por lo que un sangrado a las 8 horas posparto corresponde a esta categoría.', 'Enfermería - Cuidados de la Mujer, Recién Nacido, Niño y Adolescente', 'GPC MSP Ecuador – Hemorragia posparto 2013'),
  ('3afff026-e9be-5fd7-a915-b762d9d60f49', 'Una puérpera presenta sangrado vaginal persistente a los 10 días posparto. Según la GPC del MSP de Ecuador sobre prevención, diagnóstico y tratamiento de la hemorragia posparto, ¿a qué categoría corresponde este sangrado y cuál es su causa más frecuente?', 'Hemorragia posparto primaria, causada por trauma del canal de parto', 'No se considera hemorragia posparto por ocurrir después de la primera semana', 'Hemorragia posparto secundaria o tardía, causada mayormente por retención de productos de la concepción, infección o ambas', 'Hemorragia posparto primaria, causada por atonía uterina', 'C', 'La guía define la HPP secundaria o tardía como aquella que se produce entre las 24 horas y las seis semanas posparto, señalando que la mayoría de los casos se deben a la retención de productos de la concepción, infección o ambas.', 'Enfermería - Cuidados de la Mujer, Recién Nacido, Niño y Adolescente', 'GPC MSP Ecuador – Hemorragia posparto 2013'),
  ('7ae8e5d7-7e21-52be-94a9-06d97d88e0ad', 'Según la GPC del MSP de Ecuador sobre prevención, diagnóstico y tratamiento de la hemorragia posparto, ¿qué porcentaje aproximado de los casos de HPP inmediata se produce debido a atonía uterina?', 'Menos del 1%', '20%', '10%', '70%', 'D', 'La guía señala que aproximadamente el 70% de los casos de HPP inmediata se producen debido a atonía uterina, definida como la incapacidad del útero de contraerse adecuadamente después del nacimiento del producto.', 'Enfermería - Cuidados de la Mujer, Recién Nacido, Niño y Adolescente', 'GPC MSP Ecuador – Hemorragia posparto 2013'),
  ('68da365b-66e3-56b7-9a28-111c6bb1fb11', 'Según el CIE-10 citado en la GPC del MSP de Ecuador sobre prevención, diagnóstico y tratamiento de la hemorragia posparto, ¿qué código corresponde a otras hemorragias posparto inmediatas asociadas a atonía?', 'O72.1', 'O72.0', 'O72.3', 'O72.2', 'A', 'La guía indica que el código O72.1 corresponde a otras hemorragias posparto inmediatas (atonía), dentro de la clasificación general O72 Hemorragia posparto.', 'Enfermería - Cuidados de la Mujer, Recién Nacido, Niño y Adolescente', 'GPC MSP Ecuador – Hemorragia posparto 2013'),
  ('8851f943-27c3-58fa-8f83-1b4d3a9c227a', 'Según la GPC del MSP de Ecuador sobre prevención, diagnóstico y tratamiento de la hemorragia posparto, ¿cuál es la población blanco a la que va dirigida la GPC del MSP de Ecuador sobre prevención, diagnóstico y tratamiento de la hemorragia posparto?', 'Recién nacidos con antecedente de parto complicado', 'Mujeres en tercer estadio del trabajo de parto y puerperio hasta las 12 semanas posparto', 'Únicamente mujeres durante el trabajo de parto activo', 'Mujeres embarazadas durante todo el control prenatal', 'B', 'La guía especifica que la población blanco corresponde a mujeres en tercer estadio del trabajo de parto y puerperio hasta las 12 semanas posparto.', 'Enfermería - Cuidados de la Mujer, Recién Nacido, Niño y Adolescente', 'GPC MSP Ecuador – Hemorragia posparto 2013'),
  ('137dd5df-0af2-5976-8a55-08b6208eeac9', '¿Qué metodología se utilizó para la elaboración de la GPC del MSP de Ecuador sobre prevención, diagnóstico y tratamiento de la hemorragia posparto de hemorragia posparto?', 'Una encuesta a las pacientes atendidas en el sistema de salud', 'La metodología GRADE exclusivamente', 'La metodología ADAPTE, descrita por Guidelines International Network (G-I-N)', 'Un consenso exclusivamente nacional sin revisión de guías internacionales', 'C', 'La guía señala que fue elaborada siguiendo la metodología ADAPTE, descrita por Guidelines International Network (G-I-N), con el objetivo de incorporar las mejores prácticas clínicas y recomendaciones disponibles para el manejo de la hemorragia posparto.', 'Enfermería - Cuidados de la Mujer, Recién Nacido, Niño y Adolescente', 'GPC MSP Ecuador – Hemorragia posparto 2013'),
  ('a90fab72-8b00-505d-8eb7-869429c227f1', 'Según la GPC del MSP de Ecuador sobre prevención, diagnóstico y tratamiento de la hemorragia posparto, ¿con qué instrumento se sometieron a evaluación independiente las guías de práctica clínica seleccionadas para el proceso de adaptación?', 'El instrumento PRISMA', 'La escala de Bishop', 'El cuestionario SF-36', 'El instrumento AGREE II', 'D', 'La guía indica que las guías de práctica clínica seleccionadas se sometieron a evaluación independiente con el instrumento AGREE II.', 'Enfermería - Cuidados de la Mujer, Recién Nacido, Niño y Adolescente', 'GPC MSP Ecuador – Hemorragia posparto 2013'),
  ('9aea52ce-ea5f-5eff-a780-e7c9b988ad2e', 'Según la GPC del MSP de Ecuador sobre prevención, diagnóstico y tratamiento de la hemorragia posparto, los sistemas utilizados para calificar la calidad de la evidencia y la fuerza de las recomendaciones en este documento son:', 'Scottish Intercollegiate Guidelines Network (SIGN) y Oxford Centre for Evidence-Based Medicine (CEBM)', 'Solamente el sistema GRADE', 'Únicamente la escala de Shekelle modificada', 'El sistema de clasificación de la OMS para mortalidad materna', 'A', 'La guía señala explícitamente que los lectores encontrarán recomendaciones sustentadas por evidencia calificada con los sistemas Scottish Intercollegiate Guidelines Network (SIGN) y del Oxford Centre for Evidence-Based Medicine (CEBM).', 'Enfermería - Cuidados de la Mujer, Recién Nacido, Niño y Adolescente', 'GPC MSP Ecuador – Hemorragia posparto 2013'),
  ('a255d899-0898-513c-a42a-12e19a80226f', 'En la GPC del MSP de Ecuador sobre prevención, diagnóstico y tratamiento de la hemorragia posparto, ¿qué representa el símbolo que indica ''punto de buena práctica clínica''?', 'Un nivel de evidencia 1++ según el sistema SIGN', 'Un consejo sobre el cual el grupo de expertos acuerda, para aspectos prácticos sobre los que probablemente no existe suficiente evidencia científica que los sustente', 'Una recomendación de fuerza A basada en metaanálisis de alta calidad', 'Una recomendación exclusiva para el tercer nivel de atención', 'B', 'La guía indica que el símbolo de buena práctica clínica representa un consejo sobre el cual el grupo de expertos acuerda, correspondiente a aspectos prácticos que se quiere enfatizar y para los cuales probablemente no existe suficiente evidencia científica que los sustente, sin ser una alternativa a las recomendaciones basadas en evidencia.', 'Enfermería - Cuidados de la Mujer, Recién Nacido, Niño y Adolescente', 'GPC MSP Ecuador – Hemorragia posparto 2013'),
  ('91b6ff3c-4599-5845-8bb0-86e752bec4cd', 'De acuerdo con la clasificación SIGN incluida en el Anexo 5, ¿qué grado de recomendación corresponde a un volumen de evidencia científica compuesta por estudios clasificados como 2++, directamente aplicable a la población diana de la GPC del MSP de Ecuador sobre prevención, diagnóstico y tratamiento de la hemorragia posparto?', 'Grado C', 'Grado A', 'Grado B', 'Grado D', 'C', 'Según la tabla SIGN del Anexo 5, el grado de recomendación B corresponde a un volumen de evidencia científica compuesta por estudios clasificados como 2++, directamente aplicable a la población diana de la guía y que demuestran gran consistencia entre ellos, o evidencia extrapolada desde estudios clasificados como 1++ o 1+.', 'Enfermería - Cuidados de la Mujer, Recién Nacido, Niño y Adolescente', 'GPC MSP Ecuador – Hemorragia posparto 2013'),
  ('c8b972e1-01ff-5f81-930a-81f6cf2f01b2', 'Según la GPC del MSP de Ecuador sobre prevención, diagnóstico y tratamiento de la hemorragia posparto, ¿cuál es la causa más común de hemorragia posparto que los profesionales de salud deben recordar?', 'El trauma del canal de parto', 'La coagulopatía adquirida', 'La retención de restos placentarios', 'La atonía uterina', 'D', 'La guía establece (nivel C) que los profesionales de salud deben recordar que la causa más común de hemorragia posparto es la atonía uterina, señalando que el mecanismo primario de hemostasia inmediata luego del parto es la contracción miometrial.', 'Enfermería - Cuidados de la Mujer, Recién Nacido, Niño y Adolescente', 'GPC MSP Ecuador – Hemorragia posparto 2013'),
  ('a7c1871f-b2a2-52d6-8a78-97268f90c6c2', 'Según la nemotecnia de las 4 T descrita en la GPC del MSP de Ecuador sobre prevención, diagnóstico y tratamiento de la hemorragia posparto para el abordaje sistemático de la HPP, ¿qué representa la letra ''T'' de Tono?', 'Atonía uterina', 'Coagulopatía preexistente o adquirida', 'Lesión cervical o vaginal, ruptura uterina', 'Retención de placenta o coágulos', 'A', 'La guía indica que dentro de la nemotecnia de las 4 T, ''Tono'' representa la atonía uterina, causa más frecuente de HPP con un 70% de los casos.', 'Enfermería - Cuidados de la Mujer, Recién Nacido, Niño y Adolescente', 'GPC MSP Ecuador – Hemorragia posparto 2013'),
  ('01193434-a917-53fc-9d9f-f359d1e11c60', 'Según la nemotecnia de las 4 T, ¿cuál es el orden decreciente de frecuencia de las causas de hemorragia posparto?', 'Trauma (70%), Tono (20%), Trombina (10%), Tejido (menor a 1%)', 'Tono (70%), Trauma (20%), Tejido (10%), Trombina (menor a 1%)', 'Trombina (70%), Tejido (20%), Trauma (10%), Tono (menor a 1%)', 'Tejido (70%), Tono (20%), Trauma (10%), Trombina (menor a 1%)', 'B', 'La guía presenta el orden de frecuencia de las 4 T como: Tono (atonía uterina) 70%, Trauma (lesión cervical, vaginal o ruptura uterina) 20%, Tejido (retención de placenta o coágulos) 10%, y Trombina (coagulopatía) menor a 1%.', 'Enfermería - Cuidados de la Mujer, Recién Nacido, Niño y Adolescente', 'GPC MSP Ecuador – Hemorragia posparto 2013'),
  ('7b8e0cc1-1971-5f6f-8093-c20d92a7755b', 'Según la GPC del MSP de Ecuador sobre prevención, diagnóstico y tratamiento de la hemorragia posparto, ¿cuál es el mecanismo primario de hemostasia inmediata luego del parto?', 'La formación de un coágulo en el sitio de inserción placentaria exclusivamente', 'La vasoconstricción sistémica generalizada', 'La contracción miometrial, que produce la oclusión de los vasos sanguíneos uterinos miometriales', 'El cierre mecánico del cuello uterino', 'C', 'La guía indica que el mecanismo primario de hemostasia inmediata luego del parto es la contracción miometrial, que produce la oclusión de los vasos sanguíneos uterinos miometriales que pasan entre las células musculares del útero.', 'Enfermería - Cuidados de la Mujer, Recién Nacido, Niño y Adolescente', 'GPC MSP Ecuador – Hemorragia posparto 2013'),
  ('90b9f133-ac22-5d53-a0c3-9cdb207eff28', 'Una paciente presenta hemorragia posparto inmediata con placenta íntegra y útero contraído. De acuerdo con los criterios de diagnóstico diferencial de la GPC del MSP de Ecuador sobre prevención, diagnóstico y tratamiento de la hemorragia posparto, este cuadro clínico orienta hacia:', 'Inversión uterina', 'Atonía uterina', 'Retención de placenta', 'Desgarros del cuello uterino, la vagina o el periné', 'D', 'Según la tabla de diagnóstico diferencial, la hemorragia posparto inmediata con placenta íntegra y útero contraído orienta hacia desgarros del cuello uterino, la vagina o el periné, correspondiendo al 20% de los casos atribuibles a trauma.', 'Enfermería - Cuidados de la Mujer, Recién Nacido, Niño y Adolescente', 'GPC MSP Ecuador – Hemorragia posparto 2013'),
  ('f404d960-872d-567c-bd42-8a88bd1bb734', 'Una gestante presenta desprendimiento placentario confirmado. De acuerdo con los factores de riesgo descritos en la GPC del MSP de Ecuador sobre prevención, diagnóstico y tratamiento de la hemorragia posparto, ¿a qué componente de la nemotecnia de las 4 T se asocia este factor?', 'Trombina', 'Tono', 'Tejido', 'Trauma', 'A', 'La tabla de factores de riesgo de la guía asocia la sospecha o confirmación de desprendimiento placentario a la categoría ''Trombina'' dentro de la nemotecnia de las 4 T, con un OR de 13 (IC 95%: 7,61-12,9) para HPP.', 'Enfermería - Cuidados de la Mujer, Recién Nacido, Niño y Adolescente', 'GPC MSP Ecuador – Hemorragia posparto 2013'),
  ('135ff701-34eb-531f-b060-bf391593a14c', 'Una gestante presenta diagnóstico confirmado de placenta previa. De acuerdo con los factores de riesgo descritos en la GPC del MSP de Ecuador sobre prevención, diagnóstico y tratamiento de la hemorragia posparto, ¿cuál es el odds ratio (OR) asociado a la placenta previa conocida para el desarrollo de HPP?', '1,4 (IC 95%: 1,16-1,74)', '12 (IC 95%: 7,17-23)', '3', '2 (IC 95%: 1,48-2,12)', 'B', 'La tabla de factores de riesgo de la guía indica que la placenta previa conocida tiene un OR de 12 (IC 95%: 7,17-23) para HPP, clasificada dentro del grupo de factores presentes antes del parto asociados a incremento sustancial de la incidencia de HPP.', 'Enfermería - Cuidados de la Mujer, Recién Nacido, Niño y Adolescente', 'GPC MSP Ecuador – Hemorragia posparto 2013'),
  ('13bcc36a-5767-5191-a950-d63c267bb805', 'De acuerdo con los factores de riesgo descritos en la GPC del MSP de Ecuador sobre prevención, diagnóstico y tratamiento de la hemorragia posparto, ¿a qué grupo pertenecen los factores ''presentes antes del parto y asociados a incremento sustancial de la incidencia de HPP'', y qué recomendación general se asocia a este grupo?', 'Deben ser dadas de alta inmediatamente después del parto sin observación adicional', 'No requieren ninguna consideración adicional respecto al lugar del parto', 'A estas mujeres se les aconseja la atención del parto en centros de mayor complejidad', 'A estas mujeres se les debe indicar parto domiciliario', 'C', 'La guía especifica en la tabla de factores de riesgo que a las mujeres con factores presentes antes del parto asociados a un incremento sustancial de la incidencia de HPP (como desprendimiento placentario, placenta previa conocida, embarazo múltiple o preeclampsia/hipertensión gestacional) se les aconseja la atención del parto en centros de mayor complejidad.', 'Enfermería - Cuidados de la Mujer, Recién Nacido, Niño y Adolescente', 'GPC MSP Ecuador – Hemorragia posparto 2013'),
  ('b11e6565-5336-57c7-9afd-a79577d17714', 'Una mujer con IMC de 38 se encuentra en trabajo de parto. De acuerdo con los factores de riesgo descritos en la GPC del MSP de Ecuador sobre prevención, diagnóstico y tratamiento de la hemorragia posparto, la obesidad (IMC mayor a 35) se clasifica como un factor:', 'Presente antes del parto, asociado a incremento sustancial de la incidencia de HPP', 'Presente durante el trabajo de parto y parto', 'No descrito como factor de riesgo en esta guía', 'Presente antes del parto, asociado a incremento bajo de la incidencia de HPP', 'D', 'La tabla de factores de riesgo clasifica la obesidad (IMC mayor a 35) dentro del grupo B, es decir, factores presentes antes del parto asociados a un incremento bajo de la incidencia de HPP, con un OR de 2 (IC 95%: 1,24-2,17).', 'Enfermería - Cuidados de la Mujer, Recién Nacido, Niño y Adolescente', 'GPC MSP Ecuador – Hemorragia posparto 2013'),
  ('f5589f21-0f8c-5da9-84d5-f4092f5c73dc', 'Una paciente con hemoglobina de 8,2 g/dL se encuentra en trabajo de parto. De acuerdo con los factores de riesgo descritos en la GPC del MSP de Ecuador sobre prevención, diagnóstico y tratamiento de la hemorragia posparto, la anemia con Hb menor a 9 g/dL se asocia a un OR de:', '2 (IC 95%: 1,63-3,15)', '13 (IC 95%: 7,61-12,9)', '4', '5 (IC 95%: 3,36-7,87)', 'A', 'La tabla de factores de riesgo indica que la anemia (Hb menor a 9 g/dL) se asocia a un OR de 2 (IC 95%: 1,63-3,15) para HPP, dentro del grupo de factores presentes antes del parto con incremento bajo de la incidencia.', 'Enfermería - Cuidados de la Mujer, Recién Nacido, Niño y Adolescente', 'GPC MSP Ecuador – Hemorragia posparto 2013'),
  ('4c4835c3-d9ae-50f5-895d-f856adc85a1e', 'Una paciente requiere cesárea de emergencia durante el trabajo de parto. De acuerdo con los factores de riesgo descritos en la GPC del MSP de Ecuador sobre prevención, diagnóstico y tratamiento de la hemorragia posparto, ¿cuál es el OR asociado a la cesárea de emergencia para HPP, y a qué componente de las 4T corresponde?', '2 (IC 95%: 2,18-2,80), correspondiente a Trauma', '4 (IC 95%: 3,28-3,95), correspondiente a Trauma', '2 (IC 95%: 1,67-2,96), sin componente de las 4T asociado', '5, correspondiente a Trauma', 'B', 'La tabla de factores de riesgo indica que la cesárea de emergencia tiene un OR de 4 (IC 95%: 3,28-3,95) para HPP, correspondiente al componente Trauma de la nemotecnia de las 4T, con un riesgo mayor que la cesárea electiva.', 'Enfermería - Cuidados de la Mujer, Recién Nacido, Niño y Adolescente', 'GPC MSP Ecuador – Hemorragia posparto 2013'),
  ('803ac51d-8d8d-5336-8257-91430f3ffd81', 'De acuerdo con los factores de riesgo descritos en la GPC del MSP de Ecuador sobre prevención, diagnóstico y tratamiento de la hemorragia posparto, ¿cuál es el factor con el OR más elevado entre los presentes durante el trabajo de parto y el parto (grupo C)?', 'Inducción del trabajo de parto, con OR de 2', 'Edad mayor de 40 años en primípara, con OR de 1,4', 'Placenta retenida y episiotomía medio-lateral, ambos con OR de 5', 'Pirexia durante la labor, con OR de 2', 'C', 'Según la tabla de factores de riesgo del grupo C, tanto la placenta retenida (OR 5, IC 95%: 3,36-7,87) como la episiotomía medio-lateral (OR 5) presentan los valores más elevados entre los factores presentes durante el trabajo de parto y el parto.', 'Enfermería - Cuidados de la Mujer, Recién Nacido, Niño y Adolescente', 'GPC MSP Ecuador – Hemorragia posparto 2013'),
  ('46c7a2a0-c448-573c-be32-fc9ddeb8a595', 'Según la GPC del MSP de Ecuador sobre prevención, diagnóstico y tratamiento de la hemorragia posparto, ¿qué factores asociados al trabajo de parto y al parto se han identificado como incidentes en una mayor pérdida de sangre?', 'Exclusivamente la posición materna durante el expulsivo', 'Solamente la vía de parto vaginal espontáneo sin instrumentación', 'Únicamente la edad materna avanzada', 'La episiotomía, la cesárea y el trabajo de parto prolongado', 'D', 'La guía señala que entre los factores asociados al trabajo de parto y al parto que inciden en una mayor pérdida de sangre se encuentran la episiotomía, la cesárea y el trabajo de parto prolongado, y que las mujeres anémicas son más vulnerables a una pérdida de sangre en cantidad moderada.', 'Enfermería - Cuidados de la Mujer, Recién Nacido, Niño y Adolescente', 'GPC MSP Ecuador – Hemorragia posparto 2013'),
  ('fe2db825-febc-5ef7-82aa-0b82e6bc0f0c', 'Según la GPC del MSP de Ecuador sobre prevención, diagnóstico y tratamiento de la hemorragia posparto, ¿por qué se recomienda que todos los profesionales estén preparados para manejar una hemorragia posparto en la atención de cada parto, más allá de la evaluación de factores de riesgo?', 'Porque una hemorragia posparto puede ocurrir en mujeres sin factores de riesgo clínicos identificables o presentes en su historial', 'Porque el manejo activo de la tercera etapa solo debe aplicarse en mujeres de alto riesgo identificado', 'Porque la evaluación de riesgo predice con exactitud absoluta qué mujeres presentarán HPP', 'Porque todos los factores de riesgo son siempre modificables mediante intervención temprana', 'A', 'La guía señala que, si bien se han descrito factores de riesgo identificables, en muchos casos la hemorragia posparto puede ocurrir en mujeres sin factores de riesgo clínicos identificables o presentes en su historial, por lo que se recomienda que los profesionales estén preparados para manejar una HPP en la atención de cada parto.', 'Enfermería - Cuidados de la Mujer, Recién Nacido, Niño y Adolescente', 'GPC MSP Ecuador – Hemorragia posparto 2013'),
  ('90986dac-01fa-5825-95bf-a544c1c88e6a', 'Según la GPC del MSP de Ecuador sobre prevención, diagnóstico y tratamiento de la hemorragia posparto, basar la conducta clínica exclusivamente en la evaluación de riesgos puede conducir a qué consecuencia no deseada?', 'Una reducción significativa de los costos del sistema de salud', 'Que las mujeres consideradas de alto riesgo sean sometidas a un manejo innecesario', 'Una disminución de la necesidad de personal capacitado en la atención del parto', 'Una mejora uniforme en los resultados perinatales sin efectos adversos', 'B', 'La guía advierte que basar la conducta clínica en la evaluación de los riesgos puede conducir a que las mujeres consideradas de alto riesgo sean sometidas a un manejo innecesario, lo que no sería ventajoso ni para ellas ni para los sistemas de salud.', 'Enfermería - Cuidados de la Mujer, Recién Nacido, Niño y Adolescente', 'GPC MSP Ecuador – Hemorragia posparto 2013'),
  ('04442028-4558-54e4-b2cf-824a2cfc690a', 'Según la GPC del MSP de Ecuador sobre prevención, diagnóstico y tratamiento de la hemorragia posparto, ¿cuál es la recomendación para todas las instituciones que atienden partos?', 'Contar exclusivamente con servicios de tercer nivel para cualquier atención de parto', 'Realizar cesárea electiva en toda paciente con algún factor de riesgo identificado', 'Deben estar preparadas para responder a una emergencia durante el parto y a sus posibles complicaciones.', 'Restringir la atención de partos únicamente a mujeres sin factores de riesgo', 'C', 'La guía establece (nivel 9) que todas las instituciones que asisten partos deben estar preparadas para la eventualidad de una emergencia durante el parto y sus posibles complicaciones.', 'Enfermería - Cuidados de la Mujer, Recién Nacido, Niño y Adolescente', 'GPC MSP Ecuador – Hemorragia posparto 2013'),
  ('e6d607b2-64ed-58be-9f6d-e6227610d80c', 'Una paciente presenta hemorragia posparto inmediata con útero blando y no retraído a la palpación, además de taquicardia e hipotensión. De acuerdo con los criterios de diagnóstico diferencial de la GPC del MSP de Ecuador sobre prevención, diagnóstico y tratamiento de la hemorragia posparto, este cuadro corresponde a:', 'Retención de placenta', 'Retención de restos placentarios', 'Desgarros del cuello uterino, la vagina o el periné', 'Atonía uterina', 'D', 'Según la tabla de diagnóstico diferencial, la hemorragia posparto inmediata con útero blando y no retraído, taquicardia e hipotensión, corresponde al diagnóstico probable de atonía uterina, la causa más frecuente (70%) de HPP.', 'Enfermería - Cuidados de la Mujer, Recién Nacido, Niño y Adolescente', 'GPC MSP Ecuador – Hemorragia posparto 2013'),
  ('728d00db-0c42-5a75-a924-6e81b2b836a1', 'En el examen posparto inmediato, no se logra palpar el fondo uterino en la palpación abdominal, y la paciente presenta dolor intenso además de una masa visible en la vulva. De acuerdo con los criterios de diagnóstico diferencial de la GPC del MSP de Ecuador sobre prevención, diagnóstico y tratamiento de la hemorragia posparto, este cuadro corresponde a:', 'Inversión uterina', 'Retención de restos placentarios', 'Atonía uterina', 'Rotura uterina', 'A', 'Según la tabla de diagnóstico diferencial, la ausencia de palpación del fondo uterino en la palpación abdominal junto con dolor intenso, y la presencia de inversión uterina visible en la vulva o hemorragia posparto inmediata, corresponden al diagnóstico probable de inversión uterina.', 'Enfermería - Cuidados de la Mujer, Recién Nacido, Niño y Adolescente', 'GPC MSP Ecuador – Hemorragia posparto 2013'),
  ('904658b2-b8ab-566f-8dc8-d8be1abf33f9', 'Una paciente presenta dolor abdominal severo que disminuye posteriormente, con shock, taquicardia, abdomen doloroso y no expulsión de la placenta. De acuerdo con los criterios de diagnóstico diferencial de la GPC del MSP de Ecuador sobre prevención, diagnóstico y tratamiento de la hemorragia posparto, este cuadro orienta hacia:', 'Retención de placenta', 'Rotura uterina', 'Inversión uterina', 'Desgarros del cuello uterino', 'B', 'Según la tabla de diagnóstico diferencial, el dolor abdominal severo que puede disminuir después de la rotura, junto con abdomen doloroso, shock, taquicardia y no expulsión de la placenta, con sangrado intraabdominal y/o vaginal, corresponde al diagnóstico probable de rotura uterina.', 'Enfermería - Cuidados de la Mujer, Recién Nacido, Niño y Adolescente', 'GPC MSP Ecuador – Hemorragia posparto 2013'),
  ('f74a0314-cdc6-5245-9082-13368c7ba6c5', 'A los 35 minutos posparto, la placenta aún no ha sido expulsada, y el útero se encuentra contraído. De acuerdo con los criterios de diagnóstico diferencial de la GPC del MSP de Ecuador sobre prevención, diagnóstico y tratamiento de la hemorragia posparto, ¿cuál es el diagnóstico probable?', 'Inversión uterina', 'Rotura uterina', 'Retención de placenta', 'Atonía uterina', 'C', 'Según la tabla de diagnóstico diferencial, cuando no se expulsa la placenta dentro de los 30 minutos después del parto, con útero contraído, el diagnóstico probable es retención de placenta, correspondiente al 10% de los casos por causa de tejido.', 'Enfermería - Cuidados de la Mujer, Recién Nacido, Niño y Adolescente', 'GPC MSP Ecuador – Hemorragia posparto 2013'),
  ('e333051b-c4a2-5405-94b1-89051a91cd0a', 'Al examinar la placenta expulsada, se observa que falta una porción de la superficie materna y se identifican desgarros de las membranas. De acuerdo con los criterios de diagnóstico diferencial de la GPC del MSP de Ecuador sobre prevención, diagnóstico y tratamiento de la hemorragia posparto, este hallazgo orienta hacia:', 'Retención de placenta completa', 'Desgarros del cuello uterino', 'Inversión uterina', 'Retención de restos placentarios', 'D', 'Según la tabla de diagnóstico diferencial, la falta de una porción de la superficie materna de la placenta o la presencia de desgarros de membranas, junto con hemorragia posparto inmediata y útero retraído, corresponden al diagnóstico probable de retención de restos placentarios.', 'Enfermería - Cuidados de la Mujer, Recién Nacido, Niño y Adolescente', 'GPC MSP Ecuador – Hemorragia posparto 2013'),
  ('f5a445d7-3594-5f43-bba1-0cb04349ceae', 'Una puérpera de 14 horas posparto presenta sangrado leve continuo, con útero más blando y más grande de lo esperado según el tiempo transcurrido, y anemia asociada. De acuerdo con los criterios de diagnóstico diferencial de la GPC del MSP de Ecuador sobre prevención, diagnóstico y tratamiento de la hemorragia posparto, ¿cuál es el diagnóstico probable en este caso?', 'Retención de restos placentarios', 'Atonía uterina inmediata', 'Inversión uterina', 'Desgarros del cuello uterino', 'A', 'Según la tabla de diagnóstico diferencial, el sangrado leve que continúa luego de 12 horas después del parto, con útero más blando y grande de lo previsto según el tiempo transcurrido y sangrado variable con anemia, corresponde al diagnóstico probable de retención de restos placentarios.', 'Enfermería - Cuidados de la Mujer, Recién Nacido, Niño y Adolescente', 'GPC MSP Ecuador – Hemorragia posparto 2013'),
  ('b2a5e567-b153-5fc8-b506-7564efc51387', 'De acuerdo con los criterios de diagnóstico diferencial de la GPC del MSP de Ecuador sobre prevención, diagnóstico y tratamiento de la hemorragia posparto, ¿qué porcentaje aproximado de los casos de sangrado vaginal posparto se atribuye a trauma (desgarros, inversión o rotura uterina)?', '50%', '20%', '70%', '10%', 'B', 'La tabla de diagnóstico diferencial de la guía indica que el trauma, que incluye desgarros del cuello uterino, la vagina o el periné, la inversión uterina y la rotura uterina, corresponde aproximadamente al 20% de los casos de sangrado vaginal posparto.', 'Enfermería - Cuidados de la Mujer, Recién Nacido, Niño y Adolescente', 'GPC MSP Ecuador – Hemorragia posparto 2013'),
  ('72ea1d41-340f-5a9d-983b-195420516968', 'De acuerdo con los criterios de diagnóstico diferencial de la GPC del MSP de Ecuador sobre prevención, diagnóstico y tratamiento de la hemorragia posparto, ¿qué porcentaje de los casos de sangrado vaginal posparto corresponde a causas relacionadas con tejido (retención de placenta o de restos placentarios)?', 'Menor a 1%', '70%', '10%', '20%', 'C', 'La tabla de diagnóstico diferencial de la guía indica que las causas relacionadas con tejido, que incluyen la retención de placenta y la retención de restos placentarios, corresponden aproximadamente al 10% de los casos de sangrado vaginal posparto.', 'Enfermería - Cuidados de la Mujer, Recién Nacido, Niño y Adolescente', 'GPC MSP Ecuador – Hemorragia posparto 2013'),
  ('6d73fdbc-f0bf-5ca4-a518-310b27cd5bad', 'Según la GPC del MSP de Ecuador sobre prevención, diagnóstico y tratamiento de la hemorragia posparto, ¿cuál es el diagnóstico probable más frecuente ante una hemorragia posparto inmediata en términos generales?', 'Inversión uterina', 'Rotura uterina', 'Retención de restos placentarios', 'Atonía uterina', 'D', 'La atonía uterina, como causa de anomalía de la contractilidad, es el diagnóstico probable más frecuente, correspondiendo al 70% de los casos de sangrado vaginal posparto, tal como lo indica la tabla de diagnóstico diferencial de la guía.', 'Enfermería - Cuidados de la Mujer, Recién Nacido, Niño y Adolescente', 'GPC MSP Ecuador – Hemorragia posparto 2013'),
  ('ab04f9d3-5ed6-5f7b-a715-9acf76282402', 'Según la GPC del MSP de Ecuador sobre prevención, diagnóstico y tratamiento de la hemorragia posparto, ¿en qué porcentaje reduce el manejo activo de la tercera etapa del parto (MATEP) el riesgo de HPP cuando se aplica en todas las mujeres?', '60%', '90%', '30%', '10%', 'A', 'La guía establece (nivel A) que el manejo activo de la tercera etapa del parto (MATEP) en todas las mujeres reduce el riesgo de HPP en un 60%, además de reducir los casos de anemia posparto y la necesidad de transfusiones sanguíneas.', 'Enfermería - Cuidados de la Mujer, Recién Nacido, Niño y Adolescente', 'GPC MSP Ecuador – Hemorragia posparto 2013'),
  ('fbb52c63-94fd-59d5-bc6d-02ba31978b68', 'Según la GPC del MSP de Ecuador sobre prevención, diagnóstico y tratamiento de la hemorragia posparto, ¿cuál es el agente uterotónico de elección para el manejo activo de la tercera etapa del parto?', 'Ergometrina 0,2 mg IM como agente de primera elección universal', 'Oxitocina, 10 UI intramuscular dentro del primer minuto después del parto del recién nacido, o 5 UI intravenosas administradas lentamente', 'Ácido tranexámico 1 g intravenoso', 'Misoprostol 600 mcg VO como primera línea en todos los casos', 'B', 'La guía indica (nivel A) que la oxitocina, en dosis de 10 UI intramuscular dentro del primer minuto después del parto del recién nacido, o 5 UI intravenosas administradas lentamente, es el agente de elección para el manejo activo de la tercera etapa del parto (NNT 12).', 'Enfermería - Cuidados de la Mujer, Recién Nacido, Niño y Adolescente', 'GPC MSP Ecuador – Hemorragia posparto 2013'),
  ('b65e49db-5ea9-5999-b95e-640fade1c33b', 'Según la GPC del MSP de Ecuador sobre prevención, diagnóstico y tratamiento de la hemorragia posparto, ¿en qué situación se recomienda utilizar misoprostol 600 mcg vía oral para la prevención de HPP?', 'Como primera opción en toda mujer, independientemente de la disponibilidad de oxitocina', 'Únicamente en mujeres con antecedente de cesárea previa', 'En caso de que la oxitocina no esté disponible o su administración no sea posible', 'Solo en combinación obligatoria con oxitocina en todas las pacientes', 'C', 'La guía señala (nivel A) que el misoprostol 600 mcg VO es menos efectivo que la oxitocina, pero puede utilizarse en caso de que la oxitocina no esté disponible o su administración no sea posible (NNT 18).', 'Enfermería - Cuidados de la Mujer, Recién Nacido, Niño y Adolescente', 'GPC MSP Ecuador – Hemorragia posparto 2013'),
  ('f271e955-758e-5286-93dc-2f6adfa2dd66', 'Según los estudios de Bristol y Hinchingbrooke citados en la GPC del MSP de Ecuador sobre prevención, diagnóstico y tratamiento de la hemorragia posparto, ¿qué se demostró al comparar el manejo activo (MATEP) con el manejo expectante de la tercera etapa del parto?', 'No existió ninguna diferencia significativa entre ambos manejos', 'Ambos manejos mostraron resultados idénticos en cuanto a necesidad de transfusión', 'El manejo expectante mostró una incidencia de HPP significativamente menor', 'La incidencia de HPP fue significativamente inferior con el manejo activo en comparación con el manejo expectante', 'D', 'La guía indica que los estudios de Bristol y Hinchingbrooke demostraron claramente que, cuando se aplicó el manejo activo, la incidencia de HPP fue significativamente inferior (5,9% con MATEP vs. 17,9% con manejo expectante; y 6,8% con MATEP vs. 16,5% sin MATEP).', 'Enfermería - Cuidados de la Mujer, Recién Nacido, Niño y Adolescente', 'GPC MSP Ecuador – Hemorragia posparto 2013'),
  ('535b2e48-bf6d-5c3c-9e57-62c1040acbee', 'Según la GPC del MSP de Ecuador sobre prevención, diagnóstico y tratamiento de la hemorragia posparto, ¿qué organización recomienda el uso de rutina del MATEP como el mejor método basado en evidencia para la prevención de la HPP?', 'La Federación Internacional de Ginecología y Obstetricia (FIGO)', 'La Organización Mundial de la Salud (OMS) exclusivamente', 'El Colegio Americano de Ginecología y Obstetricia (ACOG) exclusivamente', 'La Sociedad Ecuatoriana de Gineco-Obstetricia exclusivamente', 'A', 'La guía señala que la Federación Internacional de Ginecología y Obstetricia (FIGO) recomienda el uso de rutina de MATEP como el mejor método basado en evidencia para la prevención de la HPP, destacando que se deben tomar todas las medidas para asegurar su uso en cada parto vaginal atendido por personal especializado.', 'Enfermería - Cuidados de la Mujer, Recién Nacido, Niño y Adolescente', 'GPC MSP Ecuador – Hemorragia posparto 2013'),
  ('78b0773e-a601-513d-ad0c-41b5fe74bad0', 'Según la GPC del MSP de Ecuador sobre prevención, diagnóstico y tratamiento de la hemorragia posparto, ¿cuáles son los tres pasos habituales que componen el manejo activo de la tercera etapa del parto (MATEP)?', 'Pinzamiento inmediato del cordón, aspiración uterina y antibioticoterapia', 'Administración de un uterotónico dentro del primer minuto, tracción controlada del cordón umbilical, y masaje uterino después de la expulsión de la placenta', 'Cateterismo vesical, reposo absoluto y control de signos vitales cada 4 horas', 'Administración de antibiótico profiláctico, sutura de episiotomía y observación por 6 horas', 'B', 'La guía describe los tres pasos habituales del MATEP: Paso 1, administración de oxitocina u otro medicamento uterotónico dentro de un minuto luego del nacimiento del recién nacido; Paso 2, tracción controlada del cordón luego de pinzar y cortar el cordón umbilical cuando ha dejado de latir o a los dos o tres minutos del parto; y Paso 3, masaje uterino a través del abdomen después de la expulsión de la placenta.', 'Enfermería - Cuidados de la Mujer, Recién Nacido, Niño y Adolescente', 'GPC MSP Ecuador – Hemorragia posparto 2013'),
  ('da706a84-08a1-5ca3-bcde-226bbc9b2cd3', 'Según la GPC del MSP de Ecuador sobre prevención, diagnóstico y tratamiento de la hemorragia posparto, ¿en qué momento se debe realizar el pinzamiento y corte del cordón umbilical dentro del esquema de tracción controlada del MATEP?', 'Inmediatamente después del nacimiento, sin esperar ningún tiempo', 'Únicamente después de 10 minutos del nacimiento', 'Cuando el cordón ha dejado de latir o a los dos o tres minutos del parto', 'Solo cuando se ha confirmado la expulsión completa de la placenta', 'C', 'La guía indica que la tracción controlada del cordón se realiza luego de pinzar y cortar el cordón umbilical cuando ha dejado de latir o a los dos o tres minutos del parto.', 'Enfermería - Cuidados de la Mujer, Recién Nacido, Niño y Adolescente', 'GPC MSP Ecuador – Hemorragia posparto 2013'),
  ('a41ccedc-29f5-5663-9afe-797f06c7b3ca', 'Según la GPC del MSP de Ecuador sobre prevención, diagnóstico y tratamiento de la hemorragia posparto, ¿qué precaución se debe tener respecto a la tracción controlada del cordón umbilical durante el MATEP?', 'Se debe realizar tracción vigorosa y continua del cordón independientemente de los signos de separación placentaria', 'No se requiere ninguna maniobra adicional durante la tracción del cordón', 'La tracción debe realizarse antes de la administración de fármacos uterotónicos', 'No se debe realizar la tracción del cordón umbilical sin aplicar la contratracción por encima del pubis con la otra mano', 'D', 'La guía indica explícitamente que no se debe realizar la tracción del cordón umbilical sin aplicar la contratracción por encima del pubis con la otra mano, dado que la tracción sin esta maniobra puede favorecer complicaciones como la inversión uterina.', 'Enfermería - Cuidados de la Mujer, Recién Nacido, Niño y Adolescente', 'GPC MSP Ecuador – Hemorragia posparto 2013'),
  ('8d676db8-0db6-501a-98ca-ac12ce8375fb', 'Según la GPC del MSP de Ecuador sobre prevención, diagnóstico y tratamiento de la hemorragia posparto, ¿qué se registró respecto a la inversión uterina o la separación del cordón en los cinco principales estudios controlados que compararon el manejo activo y el manejo expectante?', 'No se registró ningún caso de inversión uterina o de separación del cordón', 'Se registró un aumento significativo de casos de inversión uterina con el manejo activo', 'Se registró un aumento significativo de separación del cordón con el manejo expectante', 'Solo se registraron casos de inversión uterina en el grupo de manejo expectante', 'A', 'La guía señala que, aunque es uno de los temores principales, no se registró ningún caso de inversión uterina o de separación del cordón en los cinco principales estudios controlados en los que se comparó el manejo activo y el manejo expectante.', 'Enfermería - Cuidados de la Mujer, Recién Nacido, Niño y Adolescente', 'GPC MSP Ecuador – Hemorragia posparto 2013'),
  ('d5900535-35fb-585e-912a-0a8aa0bc9f94', 'Según la GPC del MSP de Ecuador sobre prevención, diagnóstico y tratamiento de la hemorragia posparto, ¿qué se debe controlar durante las dos primeras horas posparto tras realizar el masaje uterino del tercer paso del MATEP?', 'Únicamente la temperatura corporal materna cada 30 minutos', 'Que exista una adecuada retracción uterina y que los loquios sean normales', 'La frecuencia cardiaca fetal cada 15 minutos', 'Exclusivamente la diuresis materna cada hora', 'B', 'La guía indica que después del alumbramiento se debe masajear el fondo del útero a través del abdomen hasta conseguir que se contraiga, y que durante las dos primeras horas se debe controlar que exista una adecuada retracción uterina y que los loquios sean normales.', 'Enfermería - Cuidados de la Mujer, Recién Nacido, Niño y Adolescente', 'GPC MSP Ecuador – Hemorragia posparto 2013'),
  ('851095f2-6fe5-5c50-95af-afc6db83bb64', 'Según el Anexo 3 de la GPC del MSP de Ecuador sobre prevención, diagnóstico y tratamiento de la hemorragia posparto, ¿cuáles son las condiciones de almacenamiento recomendadas para la oxitocina?', 'Congelación obligatoria a -20°C para preservar su efectividad', 'Almacenamiento a temperatura ambiente sin restricción de luz ni temperatura', 'Almacenamiento en lugar oscuro (nivel ++), con un rango de temperatura de 2°C a 8°C o menor a 30°C, según las condiciones que consten en el envase secundario', 'Almacenamiento exclusivamente a más de 30°C en ambiente seco', 'C', 'El Anexo 3 de la guía indica que la oxitocina requiere almacenamiento en lugar oscuro (nivel ++), con un rango de temperatura de 2°C a 8°C o menor a 30°C, según las condiciones de almacenamiento que constan en el envase secundario (estuche), sin congelar.', 'Enfermería - Cuidados de la Mujer, Recién Nacido, Niño y Adolescente', 'GPC MSP Ecuador – Hemorragia posparto 2013'),
  ('e02dc8f5-03d1-55f2-9524-6fb8be484e8d', 'Se ha identificado una hemorragia posparto en una paciente en un centro de primer nivel. Según la GPC del MSP de Ecuador sobre prevención, diagnóstico y tratamiento de la hemorragia posparto, una vez identificada la HPP, ¿cómo deben implementarse los cuatro componentes del manejo (comunicación, reanimación, monitorización/investigación de la causa y detención del sangrado)?', 'Únicamente el componente de comunicación es obligatorio en el primer nivel', 'De forma secuencial, completando cada componente antes de iniciar el siguiente', 'Solo el componente de detención del sangrado es prioritario; los demás son opcionales', 'De forma SIMULTÁNEA en todos los casos de HPP', 'D', 'La guía establece (nivel C) que los cuatro componentes del manejo (comunicación con el personal relevante, reanimación, monitorización e investigación de la causa, e implementación de medidas para detener el sangrado) se deben implementar de forma SIMULTÁNEA en todos los casos de HPP.', 'Enfermería - Cuidados de la Mujer, Recién Nacido, Niño y Adolescente', 'GPC MSP Ecuador – Hemorragia posparto 2013'),
  ('5f0aa549-d953-5ae2-a7f8-343247090df2', 'Un establecimiento de salud de primer nivel no cuenta con las condiciones obstétricas esenciales para el manejo definitivo de una hemorragia posparto. Según la GPC del MSP de Ecuador sobre prevención, diagnóstico y tratamiento de la hemorragia posparto, ¿qué conducta se recomienda en este contexto?', 'Iniciar con maniobras de reanimación y detención del sangrado, y derivar a la paciente sin pérdida de tiempo a otra institución de capacidad resolutiva apropiada', 'Esperar a que la hemorragia se resuelva espontáneamente antes de considerar la referencia', 'Realizar únicamente observación clínica sin intervención activa hasta la llegada de un especialista', 'Diferir cualquier acción hasta contar con resultados de laboratorio completos', 'A', 'La guía establece (nivel C) que si el establecimiento no reúne las condiciones obstétricas esenciales, se debe iniciar con maniobras de reanimación y detención del sangrado y derivar a la paciente sin pérdida de tiempo a otra institución de capacidad resolutiva apropiada.', 'Enfermería - Cuidados de la Mujer, Recién Nacido, Niño y Adolescente', 'GPC MSP Ecuador – Hemorragia posparto 2013'),
  ('3ad4321e-d780-50c3-a76a-c3ab85c3ac5e', 'Según la GPC del MSP de Ecuador sobre prevención, diagnóstico y tratamiento de la hemorragia posparto, ¿por qué el sangrado lento y continuo posparto también constituye una emergencia que requiere intervención inmediata?', 'Porque siempre se resuelve espontáneamente sin necesidad de intervención', 'Porque puede que la afección no se detecte hasta que la mujer entre repentinamente en shock, y la hemorragia puede transformarse rápidamente en una amenaza para la vida', 'Porque solo representa riesgo si se acompaña de fiebre', 'Porque únicamente compromete el bienestar fetal, no el materno', 'B', 'La guía señala que el sangrado puede producirse a un ritmo lento durante varias horas y puede que la afección no se detecte hasta que la mujer entre repentinamente en shock; en comparación con otros riesgos asociados a la maternidad, la hemorragia puede transformarse rápidamente en una amenaza para la vida, por lo que tanto el sangrado lento y continuo como el repentino constituyen una emergencia.', 'Enfermería - Cuidados de la Mujer, Recién Nacido, Niño y Adolescente', 'GPC MSP Ecuador – Hemorragia posparto 2013'),
  ('235571e7-9bc9-5d3f-8c4a-31a40926fb93', 'Se ha identificado hemorragia posparto en una paciente y se inicia el manejo del caso. Según el esquema de la GPC del MSP de Ecuador sobre prevención, diagnóstico y tratamiento de la hemorragia posparto, ¿cuáles son los cuatro componentes del manejo que deben llevarse a cabo simultáneamente?', 'Detención del sangrado, comunicación, reanimación y, por último, monitorización', 'Reanimación, detención del sangrado, comunicación y monitorización, en ese orden estricto y consecutivo', 'Comunicación al personal pertinente, reanimación e inicio de maniobras de reposición de líquidos y oxigenación, monitorización e investigación de la causa, y detención del sangrado', 'Monitorización, detención del sangrado, comunicación y finalmente reanimación', 'C', 'La guía presenta el esquema de manejo de la HPP en cuatro componentes: comunicación al personal pertinente, reanimación e inicio de maniobras de reposición de líquidos y oxigenación, monitorización e investigación de la causa, y detención del sangrado, los cuales deben llevarse a cabo SIMULTÁNEAMENTE.', 'Enfermería - Cuidados de la Mujer, Recién Nacido, Niño y Adolescente', 'GPC MSP Ecuador – Hemorragia posparto 2013'),
  ('f4478ae5-7d9e-526c-9cff-209ac62557c1', 'Se identifica una hemorragia posparto y se moviliza al personal disponible. Según la GPC del MSP de Ecuador sobre prevención, diagnóstico y tratamiento de la hemorragia posparto, ¿qué se recomienda para lograr coordinación efectiva del equipo de salud ante una emergencia como la HPP?', 'Delegar toda la responsabilidad exclusivamente al médico tratante sin participación del resto del equipo', 'Limitar la participación únicamente al personal médico, excluyendo a enfermería y laboratorio', 'Evitar la comunicación verbal directa entre los miembros del equipo durante la emergencia', 'La práctica periódica de simulacros', 'D', 'La guía indica (nivel C) que, para que las medidas se implementen simultáneamente y sin pérdida de tiempo, el personal debe actuar en equipo sabiendo qué debe hacer cada uno en la emergencia, y que para lograr coordinación es recomendable la práctica periódica de simulacros.', 'Enfermería - Cuidados de la Mujer, Recién Nacido, Niño y Adolescente', 'GPC MSP Ecuador – Hemorragia posparto 2013'),
  ('12db3734-d29d-567a-8c6a-9bab866af372', 'Una paciente presenta hemorragia posparto activa y se decide iniciar reposición de volumen. Según la GPC del MSP de Ecuador sobre prevención, diagnóstico y tratamiento de la hemorragia posparto, ¿qué tipo de acceso venoso y volumen de cristaloides se recomienda inicialmente?', 'Dos vías intravenosas de gran calibre (16G o 14G), con solución cristaloide en volumen de hasta dos litros en infusión rápida', 'Una sola vía intravenosa de calibre pequeño (22G), con cristaloides en volumen de hasta 500 mL', 'Ninguna reposición de líquidos hasta contar con hemoderivados disponibles', 'Vía central exclusivamente, sin uso de vías periféricas en ningún caso', 'A', 'La guía recomienda (nivel B) colocar dos vías intravenosas de gran calibre (16G o 14G) y suministrar soluciones cristaloides en volumen de hasta dos litros en infusión rápida; en caso de no disponer de sangre para transfusión, se puede continuar con infusión de soluciones coloides en volumen de hasta 1,5 litros.', 'Enfermería - Cuidados de la Mujer, Recién Nacido, Niño y Adolescente', 'GPC MSP Ecuador – Hemorragia posparto 2013'),
  ('63b0649b-3847-5851-86e4-ac65ae7c59b1', 'Según la GPC del MSP de Ecuador sobre prevención, diagnóstico y tratamiento de la hemorragia posparto, ¿qué acción se recomienda como primera medida para la contención del sangrado en caso de atonía uterina, mientras se prepara el manejo farmacológico?', 'Administrar exclusivamente antibióticos de amplio espectro', 'Iniciar masaje uterino bimanual', 'Realizar histerectomía de inmediato sin intentos previos de manejo conservador', 'Esperar la llegada del especialista sin realizar ninguna maniobra', 'B', 'La guía recomienda (nivel C) evaluar el tono uterino y, en caso de atonía, masajear el útero para expulsar la sangre y los coágulos, iniciando masaje uterino bimanual como primera medida para la contención del sangrado mientras se prepara de forma simultánea el manejo farmacológico.', 'Enfermería - Cuidados de la Mujer, Recién Nacido, Niño y Adolescente', 'GPC MSP Ecuador – Hemorragia posparto 2013'),
  ('bd6f13fd-49d1-50ce-b01d-eb6a20d0fa67', 'Según la GPC del MSP de Ecuador sobre prevención, diagnóstico y tratamiento de la hemorragia posparto, ¿por qué es importante evaluar el tono uterino y masajear el útero para expulsar los coágulos sanguíneos retenidos?', 'Porque el masaje uterino sustituye por completo la necesidad de manejo farmacológico', 'Porque la presencia de coágulos siempre indica coagulopatía sistémica', 'Porque los coágulos sanguíneos retenidos en el útero inhiben las contracciones uterinas eficaces', 'Porque los coágulos retenidos no tienen ningún efecto sobre la contractilidad uterina', 'C', 'La guía señala que en caso de atonía se debe masajear el útero para expulsar la sangre y los coágulos sanguíneos, dado que los coágulos sanguíneos retenidos en el útero inhiben las contracciones uterinas eficaces.', 'Enfermería - Cuidados de la Mujer, Recién Nacido, Niño y Adolescente', 'GPC MSP Ecuador – Hemorragia posparto 2013'),
  ('bc69b4d3-454c-5841-90f5-6afb5126b59f', 'Según la GPC del MSP de Ecuador sobre prevención, diagnóstico y tratamiento de la hemorragia posparto, además de las medidas hemodinámicas, ¿qué otras acciones forman parte del manejo general inicial de la HPP?', 'Suspender cualquier vigilancia de signos vitales una vez iniciada la reposición de líquidos', 'Indicar reposo absoluto sin ninguna otra intervención adicional', 'Realizar exclusivamente radiografía de abdomen en todos los casos', 'Asegurar permeabilidad aérea y provisión de oxígeno si es necesario, y colocar una sonda vesical para la monitorización del gasto urinario', 'D', 'La guía indica (nivel C) que se debe asegurar una adecuada permeabilidad aérea y la provisión de oxígeno de ser necesario, y colocar una sonda vesical para la monitorización del gasto urinario, como parte del manejo general de la HPP.', 'Enfermería - Cuidados de la Mujer, Recién Nacido, Niño y Adolescente', 'GPC MSP Ecuador – Hemorragia posparto 2013'),
  ('49e73c44-348e-5537-bb85-40ec76395caa', 'Una paciente presenta hemorragia posparto y se sospecha shock hipovolémico. Según la GPC del MSP de Ecuador sobre prevención, diagnóstico y tratamiento de la hemorragia posparto, ¿qué recomienda realizar el profesional de salud incluso si no hay signos evidentes de shock en la evaluación inicial?', 'Tener en mente la posibilidad de shock mientras evalúa a la mujer, puesto que su estado general puede empeorar rápidamente', 'Suspender la evaluación clínica una vez descartados signos iniciales de shock', 'Descartar por completo la posibilidad de shock si los signos vitales iniciales son normales', 'Diferir cualquier preparación para el manejo del shock hasta que este se manifieste clínicamente', 'A', 'La guía indica que, aun si no hay signos de shock presentes, se debe tener en mente esta posibilidad mientras se evalúa a la mujer, puesto que su estado general puede empeorar rápidamente.', 'Enfermería - Cuidados de la Mujer, Recién Nacido, Niño y Adolescente', 'GPC MSP Ecuador – Hemorragia posparto 2013'),
  ('dd7d4423-f6c2-5120-92b9-8c940d57ab8d', 'Según la GPC del MSP de Ecuador sobre prevención, diagnóstico y tratamiento de la hemorragia posparto, al intentar identificar la causa de la hemorragia posparto, ¿qué acciones se deben realizar como parte de la evaluación?', 'Solamente evaluar la temperatura corporal materna', 'Verificar la expulsión e integridad de la placenta, buscar desgarros en cuello uterino, vagina y periné, y considerar una coagulopatía.', 'Descartar la evaluación de la placenta si el parto fue por cesárea', 'Únicamente solicitar una ecografía abdominal sin examen físico directo', 'B', 'La guía indica (nivel C) que se debe intentar identificar la causa de la hemorragia e iniciar los tratamientos específicos de acuerdo a la causa: verificar la expulsión completa de la placenta y examinarla para tener la certeza de que está íntegra, examinar el cuello uterino, la vagina y el perineo para detectar desgarros, y considerar la posibilidad de coagulopatía.', 'Enfermería - Cuidados de la Mujer, Recién Nacido, Niño y Adolescente', 'GPC MSP Ecuador – Hemorragia posparto 2013'),
  ('e01bab3c-7d43-551c-8bf8-b3d21885b101', 'Se ha identificado atonía uterina como causa de la hemorragia posparto en una paciente. De acuerdo con las medidas para identificar y tratar la causa descritas en la GPC del MSP de Ecuador sobre prevención, diagnóstico y tratamiento de la hemorragia posparto, ¿qué medidas corresponden específicamente al manejo del tono uterino?', 'Remoción manual y legrado', 'Reparación de desgarros cervicales o vaginales', 'Masaje uterino, compresión bimanual del útero y uso de drogas uterotónicas', 'Tratamiento específico de coagulopatía', 'C', 'Según la tabla de identificación y tratamiento de la causa, para el tono uterino se recomienda masaje uterino, compresión bimanual del útero y uso de drogas uterotónicas.', 'Enfermería - Cuidados de la Mujer, Recién Nacido, Niño y Adolescente', 'GPC MSP Ecuador – Hemorragia posparto 2013'),
  ('f3da1a72-1507-53ec-bb10-e24afefcff8e', 'Se identifica retención de tejido placentario como causa de la hemorragia posparto. De acuerdo con las medidas para identificar y tratar la causa descritas en la GPC del MSP de Ecuador sobre prevención, diagnóstico y tratamiento de la hemorragia posparto, ¿qué medidas corresponden al manejo de tejidos retenidos?', 'Corrección de la inversión uterina', 'Masaje uterino y compresión bimanual', 'Reparación de desgarros cervicales', 'Remoción manual y legrado', 'D', 'Según la tabla de identificación y tratamiento de la causa, para los tejidos retenidos se recomienda la remoción manual y el legrado.', 'Enfermería - Cuidados de la Mujer, Recién Nacido, Niño y Adolescente', 'GPC MSP Ecuador – Hemorragia posparto 2013'),
  ('9fe8f78b-52a7-5255-94a1-043cca47b95b', 'De acuerdo con las medidas para identificar y tratar la causa descritas en la GPC del MSP de Ecuador sobre prevención, diagnóstico y tratamiento de la hemorragia posparto, ¿qué acciones corresponden al manejo del trauma o laceraciones en la hemorragia posparto?', 'Reparar desgarros cervicales o vaginales, corregir la inversión uterina e identificar la ruptura uterina', 'Tratamiento específico dirigido únicamente a corregir la coagulopatía', 'Uso exclusivo de drogas uterotónicas sin intervención mecánica', 'Remoción manual de restos placentarios exclusivamente', 'A', 'Según la tabla de identificación y tratamiento de la causa, para el trauma o laceraciones se recomienda reparar desgarros cervicales o vaginales, corregir la inversión uterina e identificar la ruptura uterina.', 'Enfermería - Cuidados de la Mujer, Recién Nacido, Niño y Adolescente', 'GPC MSP Ecuador – Hemorragia posparto 2013'),
  ('15b4857f-5d38-5e3b-9897-408d0dadc481', 'Una hemorragia posparto no responde al tratamiento inicial y se decide conformar un equipo ampliado. Según la GPC del MSP de Ecuador sobre prevención, diagnóstico y tratamiento de la hemorragia posparto, ¿qué profesionales debe incluir la conformación del equipo ante una HPP que no responde a tratamiento?', 'Exclusivamente el médico general que atendió el parto', 'Segundo ginecólogo con experiencia, anestesiólogo, instrumentista y laboratorio', 'Solo personal de enfermería, sin apoyo de laboratorio', 'Únicamente un ginecólogo, sin necesidad de anestesiólogo', 'B', 'La guía indica que, ante una HPP que no responde a tratamiento, la conformación del equipo debe incluir un segundo ginecólogo con experiencia, anestesiólogo, instrumentista y laboratorio.', 'Enfermería - Cuidados de la Mujer, Recién Nacido, Niño y Adolescente', 'GPC MSP Ecuador – Hemorragia posparto 2013'),
  ('a2badb14-6e45-574f-ab8d-8e073fa34b0c', 'Según la GPC del MSP de Ecuador sobre prevención, diagnóstico y tratamiento de la hemorragia posparto, ¿qué maniobra de control local se menciona para la HPP que no responde a tratamiento, mientras se organiza el manejo definitivo?', 'Colocación de balón intrauterino como única alternativa mencionada', 'Taponamiento vaginal exclusivamente', 'Compresión bimanual', 'Ligadura de arterias hipogástricas como primera medida de control local', 'C', 'La guía indica, dentro del apartado de HPP que no responde a tratamiento, que el control local se realiza mediante compresión bimanual, mientras se organiza la transfusión con cristaloides y sangre total o subproductos según sea necesario.', 'Enfermería - Cuidados de la Mujer, Recién Nacido, Niño y Adolescente', 'GPC MSP Ecuador – Hemorragia posparto 2013'),
  ('d6a1aa46-27c7-59a2-b3cb-d873c2470f1a', 'El equipo médico decide realizar cirugía ante una hemorragia posparto persistente. Según la GPC del MSP de Ecuador sobre prevención, diagnóstico y tratamiento de la hemorragia posparto, ¿cuál es el primer paso descrito dentro del abordaje quirúrgico de la HPP?', 'Ligadura de arterias uterinas como primer paso obligatorio', 'Sutura hemostática de B-Lynch sin examen previo', 'Histerectomía inmediata sin evaluación previa', 'Examen bajo anestesia', 'D', 'La guía indica que dentro de la sección de cirugía, el primer paso descrito es el examen bajo anestesia, seguido de la reparación de desgarros y la toma de decisión quirúrgica según la experiencia del equipo.', 'Enfermería - Cuidados de la Mujer, Recién Nacido, Niño y Adolescente', 'GPC MSP Ecuador – Hemorragia posparto 2013'),
  ('7e716bc2-08d4-523d-8553-11a4b83069e0', 'Según la GPC del MSP de Ecuador sobre prevención, diagnóstico y tratamiento de la hemorragia posparto, ¿qué opción quirúrgica se describe como la más segura para personal poco entrenado o cuando fallan las ligaduras vasculares y los puntos hemostáticos?', 'La histerectomía', 'El examen bajo anestesia', 'La sutura hemostática de B-Lynch', 'La ligadura de arterias útero-ováricas', 'A', 'La guía indica que la histerectomía es la opción más segura para personal poco entrenado o cuando fallan las ligaduras vasculares y puntos hemostáticos, dentro del apartado de toma de decisión quirúrgica.', 'Enfermería - Cuidados de la Mujer, Recién Nacido, Niño y Adolescente', 'GPC MSP Ecuador – Hemorragia posparto 2013'),
  ('e3f9ab8b-3036-56fd-b415-961eb987e726', 'Una paciente presenta sangrado persistente después de una histerectomía por HPP. Según la GPC del MSP de Ecuador sobre prevención, diagnóstico y tratamiento de la hemorragia posparto, ¿de qué depende el manejo del sangrado poshisterectomía?', 'Solamente de la hora del día en que ocurre el sangrado', 'De la situación clínica, la experiencia del equipo médico, y la infraestructura y personal disponible', 'Exclusivamente del tipo de anestesia utilizada durante la cirugía', 'Únicamente de la preferencia personal de la paciente', 'B', 'La guía indica que el manejo del sangrado poshisterectomía responderá a la situación clínica, la experiencia del equipo médico, y la infraestructura y personal disponible, pudiendo requerirse reposición de factores de coagulación o taponaje abdominal.', 'Enfermería - Cuidados de la Mujer, Recién Nacido, Niño y Adolescente', 'GPC MSP Ecuador – Hemorragia posparto 2013'),
  ('9c7f7e7f-0211-5e36-b52c-1da173a4a43a', 'Según la GPC del MSP de Ecuador sobre prevención, diagnóstico y tratamiento de la hemorragia posparto, ¿qué beneficio aporta referir a la paciente a centros con adecuada complejidad y capacidad resolutiva una vez establecido el diagnóstico diferencial?', 'Sustituye la necesidad de manejo inicial en el establecimiento de origen', 'Elimina por completo la necesidad de seguimiento posterior', 'Permite tomar decisiones de especialidad acertadas y oportunas', 'Garantiza automáticamente la resolución del cuadro sin más intervención', 'C', 'La guía establece (nivel B) que referir a la paciente a centros con adecuada complejidad y capacidad resolutiva una vez que se ha establecido el diagnóstico diferencial permite tomar decisiones de especialidad acertadas y oportunas.', 'Enfermería - Cuidados de la Mujer, Recién Nacido, Niño y Adolescente', 'GPC MSP Ecuador – Hemorragia posparto 2013'),
  ('ba8b27a8-5952-5e88-97ea-da04d3c2173c', 'Según la GPC del MSP de Ecuador sobre prevención, diagnóstico y tratamiento de la hemorragia posparto, una vez superada la fase de atención del cuadro complicado de hemorragia posparto, ¿qué se debe hacer con la paciente en el proceso de contrarreferencia?', 'Remitir a la paciente sin ningún informe escrito del manejo realizado', 'Dar de alta a la paciente sin ninguna indicación específica para el nivel primario', 'Mantener a la paciente indefinidamente en el nivel de mayor complejidad sin remisión posterior', 'Remitir al nivel primario con indicaciones claras del médico especialista sobre manejo subsecuente, con informe de acciones y resultados de la atención de especialidad', 'D', 'La guía indica que, superada la fase de atención del cuadro complicado de hemorragia posparto, se debe remitir al nivel primario con indicaciones claras del médico especialista sobre manejo subsecuente, con informe de acciones y resultados de la atención de especialidad.', 'Enfermería - Cuidados de la Mujer, Recién Nacido, Niño y Adolescente', 'GPC MSP Ecuador – Hemorragia posparto 2013'),
  ('6d4ad3cc-cfe4-51bc-bcbd-6255bbe2c4ef', 'Según la GPC del MSP de Ecuador sobre prevención, diagnóstico y tratamiento de la hemorragia posparto, ¿cuál es el principal estándar e indicador de proceso para el monitoreo de cumplimiento de la GPC del MSP de Ecuador sobre prevención, diagnóstico y tratamiento de la hemorragia posparto?', 'El estándar 8B: porcentaje de pacientes con hemorragia obstétrica manejadas de acuerdo a la norma', 'El estándar 12: porcentaje de complicaciones obstétricas atendidas del total esperado', 'El estándar 1: porcentaje de insumos, equipos y medicamentos esenciales disponibles', 'El estándar 10: tasa hospitalaria de letalidad por complicaciones obstétricas directas', 'A', 'La guía señala que el principal estándar e indicador de proceso para el monitoreo de cumplimiento de esta GPC es el 8B: porcentaje de pacientes con hemorragia obstétrica manejadas de acuerdo a la norma.', 'Enfermería - Cuidados de la Mujer, Recién Nacido, Niño y Adolescente', 'GPC MSP Ecuador – Hemorragia posparto 2013'),
  ('6653a811-f1b1-5518-b19c-48225cad2196', 'Según la GPC del MSP de Ecuador sobre prevención, diagnóstico y tratamiento de la hemorragia posparto, ¿qué manual debe aplicar el equipo de Mejoramiento Continuo de la Calidad para el monitoreo de la GPC del MSP de Ecuador sobre prevención, diagnóstico y tratamiento de la hemorragia posparto?', 'El manual AGREE II para evaluación de guías clínicas', 'El Manual de Estándares, Indicadores e Instrumentos para medir la Calidad de la Atención Materno Neonatal del Ministerio de Salud Pública del Ecuador', 'El manual de procedimientos de la Organización Mundial de la Salud exclusivamente', 'El manual de bioseguridad hospitalaria del MSP', 'B', 'La guía indica que el equipo de Mejoramiento Continuo de la Calidad debe aplicar el Manual de Estándares, Indicadores e Instrumentos para medir la Calidad de la Atención Materno Neonatal del Ministerio de Salud Pública del Ecuador.', 'Enfermería - Cuidados de la Mujer, Recién Nacido, Niño y Adolescente', 'GPC MSP Ecuador – Hemorragia posparto 2013'),
  ('dcf7e354-ebde-5312-9d0b-b232270c5122', 'Según el glosario de términos de la GPC del MSP de Ecuador sobre prevención, diagnóstico y tratamiento de la hemorragia posparto (Anexo 6), ¿cómo se define la contrarreferencia?', 'Es un trámite exclusivamente administrativo sin relación con la información clínica del caso', 'Es un procedimiento aplicable únicamente en casos de mortalidad materna', 'Es el proceso inverso a la referencia, es decir, la devolución del paciente del nivel superior al inferior que lo envió, con la debida información en el formulario correspondiente', 'Es el proceso de envío de un paciente de un nivel de menor a mayor complejidad', 'C', 'El Anexo 6 de la guía define la contrarreferencia como el proceso inverso a la referencia, es decir, la devolución del paciente del nivel superior al inferior que lo envió, con la debida información en el formulario correspondiente.', 'Enfermería - Cuidados de la Mujer, Recién Nacido, Niño y Adolescente', 'GPC MSP Ecuador – Hemorragia posparto 2013'),
  ('d7f6d460-c4aa-5dca-9af2-5556dd634705', 'Según el glosario de la GPC del MSP de Ecuador sobre prevención, diagnóstico y tratamiento de la hemorragia posparto (Anexo 6), ¿cómo se define la referencia?', 'Es un proceso que no requiere información escrita del caso', 'Es el mismo concepto que la contrarreferencia, utilizado de forma intercambiable', 'Es un proceso que solo puede realizarse hacia el nivel inmediato superior, sin excepción', 'Es el proceso estructurado de envío de un paciente, con información por escrito, de un nivel del sistema de salud a otro superior en tecnicidad y competencia', 'D', 'El Anexo 6 define la referencia como el proceso estructurado de envío de un paciente (con información por escrito) de un nivel del sistema de salud a otro superior en tecnicidad y competencia, señalando que el nivel superior puede ser el inmediato superior o no.', 'Enfermería - Cuidados de la Mujer, Recién Nacido, Niño y Adolescente', 'GPC MSP Ecuador – Hemorragia posparto 2013'),
  ('ef57b408-ff61-5c91-8758-841b3003a929', 'Según el esquema farmacológico del Anexo 1 (adaptado de FIGO), ¿cuál es la dosis de oxitocina recomendada para el tratamiento de la hemorragia posparto ya establecida?', '10 UI/mL IM (o 5 UI IV lento), o 20-40 UI en 1000 mL de solución cristaloide en infusión IV a 250 mL/h', '100 UI IM en dosis única', '5 UI/mL IM únicamente, sin opción de infusión intravenosa', '2 UI IM cada 6 horas', 'A', 'El Anexo 1 de la guía indica que, para el tratamiento de la HPP, la oxitocina se administra en dosis de 10 UI/mL IM (o 5 UI IV lento), o 20-40 UI en 1000 mL de solución cristaloide en infusión IV a 250 mL/h.', 'Enfermería - Cuidados de la Mujer, Recién Nacido, Niño y Adolescente', 'GPC MSP Ecuador – Hemorragia posparto 2013'),
  ('df5f91ac-e0a3-52af-88bf-b6fd75b39e61', 'Según el Anexo 1 de la GPC del MSP de Ecuador sobre prevención, diagnóstico y tratamiento de la hemorragia posparto, ¿cuál es la dosis de misoprostol recomendada para el tratamiento de la hemorragia posparto ya establecida?', '1.200 mcg intravenoso', '800 µg sublingual (4 tabletas de 200 mcg)', '600 mcg vía oral, misma dosis que en la prevención', '200 mcg intramuscular', 'B', 'El Anexo 1 de la guía indica que, para el tratamiento de la HPP, el misoprostol se administra en dosis de 800 µg sublingual, equivalente a 4 tabletas de 200 mcg, dosis distinta a la utilizada en la prevención (600 mcg VO).', 'Enfermería - Cuidados de la Mujer, Recién Nacido, Niño y Adolescente', 'GPC MSP Ecuador – Hemorragia posparto 2013'),
  ('8ffa93ca-94f0-5a8f-8e43-b01866ca6a1b', 'Según el Anexo 1 de la GPC del MSP de Ecuador sobre prevención, diagnóstico y tratamiento de la hemorragia posparto, ¿cuál es la dosis máxima de ergonovina o metilergonovina recomendada para el tratamiento de la HPP en un período de 24 horas?', 'Dosis única de 0,2 mg sin posibilidad de repetición', 'Máximo 2 dosis (0,4 mg) en un período de 24 horas', 'Máximo 5 dosis (1 mg) en un período de 24 horas, repitiendo cada 2 a 4 horas si es necesario', 'Máximo 10 dosis (2 mg) en un período de 24 horas', 'C', 'El Anexo 1 de la guía indica que, en ausencia de contraindicaciones, la ergonovina o metilergonovina se administra en dosis de 0,2 mg IM, pudiendo repetirse cada 2 a 4 horas, con un máximo de 5 dosis (1 mg) en un período de 24 horas.', 'Enfermería - Cuidados de la Mujer, Recién Nacido, Niño y Adolescente', 'GPC MSP Ecuador – Hemorragia posparto 2013'),
  ('f19d7eb0-0334-54ed-bcf7-04d2ef32ec3f', 'Según la advertencia del Anexo 1, ¿en qué grupo de pacientes están contraindicados los alcaloides del ergot (ergonovina, metilergonovina)?', 'Mujeres con parto vaginal sin complicaciones', 'Mujeres con anemia leve sin otra comorbilidad', 'Mujeres con embarazo gemelar sin otra comorbilidad asociada', 'Mujeres con hipertensión arterial, enfermedad cardíaca, preeclampsia o eclampsia, porque elevan la presión sanguínea', 'D', 'El Anexo 1 advierte explícitamente que los alcaloides del ergot (ergonovina, metilergonovina) están contraindicados en mujeres con hipertensión arterial, enfermedad cardíaca, preeclampsia o eclampsia porque elevan la presión sanguínea.', 'Enfermería - Cuidados de la Mujer, Recién Nacido, Niño y Adolescente', 'GPC MSP Ecuador – Hemorragia posparto 2013'),
  ('dd483e71-e926-511c-b0fd-f3257197b4f9', 'Según el Anexo 2 (adaptado de FIGO), en caso de retención de placenta que no responde a la extracción manual, ¿qué se debe hacer?', 'Coordinar la transferencia de la mujer a un centro apto para realizar procedimientos de dilatación y curetaje', 'Aplicar exclusivamente antibióticos sin ninguna otra intervención', 'Esperar la resolución espontánea sin ninguna intervención adicional', 'Realizar histerectomía de inmediato sin intentar otras alternativas', 'A', 'El Anexo 2 indica que ante retención de placenta se debe intentar extraer manualmente la placenta, considerando una inyección intrafunicular o misoprostol como alternativa antes de intentar removerla manualmente; si no se obtienen resultados satisfactorios, se debe coordinar la transferencia de la mujer a un centro apto para realizar procedimientos de dilatación y curetaje.', 'Enfermería - Cuidados de la Mujer, Recién Nacido, Niño y Adolescente', 'GPC MSP Ecuador – Hemorragia posparto 2013'),
  ('5607be97-608e-50c5-9dfc-97e5c91dd479', 'Según el Anexo 2 de la GPC del MSP de Ecuador sobre prevención, diagnóstico y tratamiento de la hemorragia posparto, ¿qué se debe evitar en caso de inversión uterina hasta haber colocado el útero nuevamente en su lugar?', 'Remover la placenta de forma prioritaria antes de reposicionar el útero', 'No administrar uterotónicos ni intentar remover la placenta hasta haber colocado el útero en su lugar', 'Administrar de inmediato dosis altas de oxitocina antes de reposicionar el útero', 'No se describe ninguna precaución específica para este escenario', 'B', 'El Anexo 2 indica que, ante inversión uterina, se debe intentar colocar el útero nuevamente en su lugar, sin administrar uterotónicos ni intentar remover la placenta hasta haber colocado el útero en su lugar.', 'Enfermería - Cuidados de la Mujer, Recién Nacido, Niño y Adolescente', 'GPC MSP Ecuador – Hemorragia posparto 2013'),
  ('e8225ecf-badf-5055-9e49-cfb83a404eb5', 'Según el Anexo 2, ¿qué riesgo particular presentan las mujeres que han requerido intervenciones avanzadas por hemorragia posparto (como taponamiento uterino, embolización o laparotomía), y qué se recomienda al respecto?', 'No presentan ningún riesgo adicional tras la resolución del sangrado', 'Deben recibir transfusión sanguínea obligatoria independientemente de sus valores de hemoglobina', 'Presentan riesgo de anemia, siendo importante administrar suplementos de hierro durante al menos tres meses', 'Requieren suspender toda suplementación nutricional posparto', 'C', 'El Anexo 2 señala que estas mujeres presentan riesgo de anemia, siendo importante administrar suplementos de hierro durante al menos tres meses.', 'Enfermería - Cuidados de la Mujer, Recién Nacido, Niño y Adolescente', 'GPC MSP Ecuador – Hemorragia posparto 2013'),
  ('75c59851-7a89-56ae-bbce-6a569fcf6ff7', 'Según la nota al pie del Anexo 2, ¿cómo se define la inyección intrafunicular como alternativa antes de intentar la remoción manual de la placenta?', 'Administrar ergometrina diluida en dextrosa por el cordón umbilical', 'Administrar misoprostol disuelto en solución salina por vía intrafunicular', 'Administrar 100 UI de oxitocina no diluida directamente en la vena umbilical materna', 'Administrar 20 UI de oxitocina disueltos en 20 mL de solución salina por el lado placentario del cordón umbilical', 'D', 'La nota al pie del Anexo 2 especifica que la inyección intrafunicular consiste en administrar 20 UI de oxitocina disueltos en 20 mL de solución salina por el lado placentario del cordón umbilical.', 'Enfermería - Cuidados de la Mujer, Recién Nacido, Niño y Adolescente', 'GPC MSP Ecuador – Hemorragia posparto 2013'),
  ('c11856a7-bdb7-5ee0-a1a6-e63898f20e74', 'Según el algoritmo del Anexo 2, ¿cuál es el umbral de sangrado que define la hemorragia posparto en un parto vaginal y en una cesárea, respectivamente?', 'Mayor a 500 mL en parto vaginal y mayor a 1 litro en parto por cesárea', 'Mayor a 1.000 mL en parto vaginal y mayor a 2.000 mL en cesárea', 'El mismo umbral de 500 mL para ambas vías de nacimiento', 'Mayor a 200 mL en parto vaginal y mayor a 500 mL en cesárea', 'A', 'El Anexo 2 reitera la definición de HPP como sangrado mayor a 500 mL en parto vaginal y mayor a 1 litro en parto por cesárea, coincidiendo con la definición general de la guía, además de señalar que cualquier volumen de pérdida sanguínea en una mujer hemodinámicamente inestable también se considera HPP.', 'Enfermería - Cuidados de la Mujer, Recién Nacido, Niño y Adolescente', 'GPC MSP Ecuador – Hemorragia posparto 2013'),
  ('26d03e20-766d-5c45-b5e8-6dab01154d16', 'Según el algoritmo del Anexo 2, ante una hemorragia posparto con sangrado persistente, ¿cuáles son las primeras medidas generales de control del sangrado que se deben aplicar mientras se determina la causa específica?', 'Iniciar de inmediato manejo quirúrgico definitivo sin medidas previas de estabilización', 'Compresión aórtica, asegurar acceso IV y considerar taponamiento uterino por atonía', 'Suspender toda vía intravenosa hasta identificar la causa exacta', 'Aplicar exclusivamente antibióticos de amplio espectro como primera medida', 'B', 'El algoritmo del Anexo 2 indica, como parte del control del sangrado ante una HPP, la compresión aórtica, asegurar acceso IV y el taponamiento uterino por atonía, en paralelo con la monitorización del estado materno y la evaluación para determinar la causa del sangrado.', 'Enfermería - Cuidados de la Mujer, Recién Nacido, Niño y Adolescente', 'GPC MSP Ecuador – Hemorragia posparto 2013'),
  ('5b8adc41-d698-52c5-9778-6f7619ec738f', 'Según la ficha de oxitocina del Anexo 4, ¿qué precaución especial se debe tener respecto a la vía de administración intravenosa?', 'La vía intravenosa está completamente contraindicada en cualquier situación', 'Se debe administrar siempre en bolo rápido para lograr efecto inmediato', 'Evitar la inyección intravenosa rápida, ya que puede reducir transitoriamente la presión arterial', 'No existe ninguna precaución específica sobre la velocidad de administración intravenosa', 'C', 'La ficha de oxitocina del Anexo 4 indica como precaución importante evitar la inyección intravenosa rápida, ya que puede reducir transitoriamente la presión arterial.', 'Enfermería - Cuidados de la Mujer, Recién Nacido, Niño y Adolescente', 'GPC MSP Ecuador – Hemorragia posparto 2013'),
  ('19f4c265-de31-5e13-86d3-300be3ab8967', 'Según la ficha de oxitocina del Anexo 4, ¿cuál es la categoría de uso en el embarazo asignada a este medicamento?', 'No se especifica ninguna categoría de uso en el embarazo', 'Categoría B, evitar salvo indicación indispensable', 'Categoría A, uso recomendado sin restricciones', 'Categoría X, contraindicado en el primer trimestre salvo en aborto incompleto o terapéutico', 'D', 'La ficha de oxitocina del Anexo 4 señala categoría X en el embarazo, contraindicado en el primer trimestre (salvo en aborto incompleto o terapéutico), y que no se recomienda su uso durante el embarazo salvo para inducción a dosis adecuadas.', 'Enfermería - Cuidados de la Mujer, Recién Nacido, Niño y Adolescente', 'GPC MSP Ecuador – Hemorragia posparto 2013'),
  ('dcf5569c-c3bb-5fd0-85a2-3ba6cc3951b3', 'Una puérpera en tratamiento con oxitocina presenta antecedente de preeclampsia severa y enfermedad cardiovascular severa. Según la ficha de oxitocina del Anexo 4, ¿qué se recomienda tener en cuenta en este contexto?', 'Se debe utilizar con precaución en pacientes con preeclampsia severa y enfermedades cardiovasculares severas, entre otras condiciones que requieren vigilancia especial', 'La oxitocina está formalmente contraindicada en toda paciente con antecedente de preeclampsia, sin excepción', 'No existe ninguna precaución especial en pacientes con estas condiciones', 'Se debe suspender cualquier uso de oxitocina en pacientes con antecedente de cesárea', 'A', 'La ficha de oxitocina del Anexo 4 enumera, dentro de las precauciones, antecedentes de cesárea, polihidramnios, multiparidad, preeclampsia severa y enfermedades cardiovasculares severas, insuficiencia renal (con riesgo de sobrecarga hídrica), señalando que su uso requiere una adecuada evaluación del riesgo/beneficio.', 'Enfermería - Cuidados de la Mujer, Recién Nacido, Niño y Adolescente', 'GPC MSP Ecuador – Hemorragia posparto 2013'),
  ('2991b0aa-055e-5c97-b1a7-f201f166e79b', 'Según la ficha de misoprostol del Anexo 4, ¿en qué grupo de pacientes se debe tener precaución especial debido al riesgo de incremento de coagulación intravascular diseminada?', 'Pacientes con embarazo gemelar sin otra comorbilidad', 'Pacientes con embarazo postérmino', 'Pacientes con anemia leve', 'Pacientes con parto vaginal previo sin complicaciones', 'B', 'La ficha de misoprostol del Anexo 4 señala como precaución que en pacientes con embarazo postérmino puede incrementarse el riesgo de coagulación intravascular diseminada.', 'Enfermería - Cuidados de la Mujer, Recién Nacido, Niño y Adolescente', 'GPC MSP Ecuador – Hemorragia posparto 2013'),
  ('afa6df48-c3f3-5367-8fe9-bae7e0c32c2e', 'Según la ficha de misoprostol del Anexo 4, ¿cuál es un efecto adverso raro asociado a su uso, especialmente en multíparas y con cesárea previa?', 'Constipación severa', 'Rash cutáneo generalizado', 'Ruptura de útero', 'Cefalea intensa', 'C', 'La ficha de misoprostol del Anexo 4 indica que, dentro de los efectos adversos raros, se encuentra la ruptura de útero (principalmente en multíparas y con cesárea previa), además de la muerte materna por embolismo de líquido amniótico, la coagulación intravascular diseminada y la muerte fetal.', 'Enfermería - Cuidados de la Mujer, Recién Nacido, Niño y Adolescente', 'GPC MSP Ecuador – Hemorragia posparto 2013'),
  ('64cde438-75da-5d8d-b5a5-0f6308c02b3e', 'Según la ficha de metilergonovina/ergonovina del Anexo 4, ¿cuál es una de las contraindicaciones absolutas para su administración?', 'Embarazo gemelar sin otra comorbilidad asociada', 'Anemia leve sin otra comorbilidad', 'Antecedente de parto vaginal previo sin complicaciones', 'Hipertensión arterial severa, eclampsia o preeclampsia', 'D', 'La ficha de metilergonovina/ergonovina del Anexo 4 indica como contraindicaciones la hipertensión arterial severa, eclampsia o preeclampsia, hipersensibilidad a los alcaloides del cornezuelo de centeno, angina inestable, infarto de miocardio reciente, entre otras.', 'Enfermería - Cuidados de la Mujer, Recién Nacido, Niño y Adolescente', 'GPC MSP Ecuador – Hemorragia posparto 2013'),
  ('a459eff1-119c-5fa5-813b-f0b5155352df', 'Según la ficha de metilergonovina/ergonovina del Anexo 4, ¿qué efecto puede tener este fármaco sobre la lactancia?', 'Puede interferir con la secreción de prolactina en el puerperio inmediato y retrasar o inhibir la secreción láctea', 'Está formalmente recomendado para estimular la lactancia', 'Aumenta significativamente la producción de leche materna', 'No tiene ningún efecto descrito sobre la lactancia', 'A', 'La ficha de metilergonovina/ergonovina del Anexo 4 indica que este fármaco se excreta por leche materna y puede interferir con la secreción de prolactina en el puerperio inmediato, retrasando o inhibiendo la secreción láctea, por lo que no se recomienda su empleo durante la lactancia.', 'Enfermería - Cuidados de la Mujer, Recién Nacido, Niño y Adolescente', 'GPC MSP Ecuador – Hemorragia posparto 2013'),
  ('30e7a86b-ef1e-5443-9fe1-d05c8b716d74', 'Según la ficha de metilergonovina/ergonovina del Anexo 4, ¿qué precaución se debe tener respecto a su uso durante la inducción o conducción de la labor de parto?', 'Es el fármaco de elección para la inducción del trabajo de parto', 'No se debe utilizar durante la inducción o conducción de la labor de parto', 'Debe combinarse siempre con oxitocina durante la inducción', 'No existe ninguna restricción respecto a su uso durante el trabajo de parto activo', 'B', 'La ficha de metilergonovina/ergonovina del Anexo 4 indica explícitamente, dentro de las precauciones, que no se debe utilizar durante la inducción o conducción de la labor de parto.', 'Enfermería - Cuidados de la Mujer, Recién Nacido, Niño y Adolescente', 'GPC MSP Ecuador – Hemorragia posparto 2013'),
  ('5f944404-b413-5659-87e2-5e513cb2da53', 'Según el sistema Oxford Centre for Evidence-Based Medicine (CEBM) descrito en el Anexo 5, ¿qué grado de recomendación corresponde a estudios de nivel 1?', 'Grado B', 'Grado C', 'Grado A', 'Grado D', 'C', 'Según la tabla del sistema CEBM del Anexo 5, el grado de recomendación A corresponde a estudios de nivel 1, tales como revisiones sistemáticas de ensayos clínicos aleatorizados con homogeneidad o ensayos clínicos aleatorizados con intervalo de confianza estrecho.', 'Enfermería - Cuidados de la Mujer, Recién Nacido, Niño y Adolescente', 'GPC MSP Ecuador – Hemorragia posparto 2013'),
  ('af4b1ca9-308c-5d0e-a9eb-aee23d50b32d', 'Según el sistema CEBM del Anexo 5, ¿qué nivel de evidencia corresponde a la ''opinión de expertos sin valoración crítica explícita, o basados en la fisiología o fisiopatología''?', 'Nivel 3b', 'Nivel 1c', 'Nivel 2a', 'Nivel 5', 'D', 'Según la tabla del sistema CEBM del Anexo 5, el nivel de evidencia 5 corresponde a la opinión de expertos sin valoración crítica explícita, o basados en la fisiología o fisiopatología, siendo el nivel de menor jerarquía dentro de esta clasificación.', 'Enfermería - Cuidados de la Mujer, Recién Nacido, Niño y Adolescente', 'GPC MSP Ecuador – Hemorragia posparto 2013'),
  ('e7e48b39-2b0c-5525-ba3f-c8289c1d851f', 'Según el glosario de términos del Anexo 6, ¿cómo se define la ''sutura hemostática de B-Lynch''?', 'Sutura compresiva que se coloca quirúrgicamente para tratamiento de hemorragia posparto', 'Una técnica de sutura empleada únicamente en cesáreas electivas sin complicaciones', 'Un procedimiento no quirúrgico de compresión externa del abdomen', 'Un tipo de sutura utilizada exclusivamente para la reparación de la episiotomía', 'A', 'El Anexo 6 define la sutura hemostática de B-Lynch como una sutura compresiva que se coloca quirúrgicamente para tratamiento de hemorragia posparto.', 'Enfermería - Cuidados de la Mujer, Recién Nacido, Niño y Adolescente', 'GPC MSP Ecuador – Hemorragia posparto 2013'),
  ('3432201f-e8f3-55cc-a7b3-90b30c56c9a8', 'Según el Anexo 7 de abreviaturas de la GPC del MSP de Ecuador sobre prevención, diagnóstico y tratamiento de la hemorragia posparto, ¿qué significa la sigla MATEP?', 'Manejo Ambulatorio de la Terapia de Emergencia Prenatal', 'Manejo Activo de la Tercera Etapa de la Labor de Parto', 'Monitoreo Activo de la Temperatura en el Puerperio', 'Manual de Atención de la Tercera Etapa del Parto', 'B', 'El Anexo 7 de abreviaturas indica que MATEP corresponde a Manejo Activo de la Tercera Etapa de la Labor de Parto, conocido en inglés como AMSTL.', 'Enfermería - Cuidados de la Mujer, Recién Nacido, Niño y Adolescente', 'GPC MSP Ecuador – Hemorragia posparto 2013'),
  ('53e9273a-96a9-5ebc-8d55-191957c271c4', 'Según el Anexo 7 de abreviaturas, ¿qué significa la sigla HPP utilizada a lo largo de la GPC del MSP de Ecuador sobre prevención, diagnóstico y tratamiento de la hemorragia posparto?', 'Hospitalización prolongada por parto', 'Hipertensión posparto', 'Hemorragia posparto', 'Hemoglobina posparto', 'C', 'El Anexo 7 de abreviaturas de la guía indica que HPP corresponde a Hemorragia posparto, término central utilizado a lo largo de todo el documento.', 'Enfermería - Cuidados de la Mujer, Recién Nacido, Niño y Adolescente', 'GPC MSP Ecuador – Hemorragia posparto 2013'),
  ('d1e4e0b1-b5f5-5245-bda3-5a9be874c6c3', 'Según la introducción de la GPC del MSP de Ecuador sobre prevención, diagnóstico y tratamiento de la hemorragia posparto, ¿cuál es la segunda causa más importante de muerte materna en Ecuador?', 'La sepsis puerperal', 'La preeclampsia/eclampsia', 'El embolismo pulmonar', 'La hemorragia posparto', 'D', 'La guía señala en su introducción que la hemorragia posparto, en su mayoría causada por atonía uterina, es la causa más frecuente de mortalidad materna evitable en todo el mundo, y la segunda causa más importante de muerte materna en Ecuador.', 'Enfermería - Cuidados de la Mujer, Recién Nacido, Niño y Adolescente', 'GPC MSP Ecuador – Hemorragia posparto 2013'),
  ('602f7a42-8fbc-57b5-9403-23092d3eea4a', 'Según la introducción de la GPC del MSP de Ecuador sobre prevención, diagnóstico y tratamiento de la hemorragia posparto, ¿en qué año la Organización Mundial de la Salud agregó el misoprostol a su Lista Modelo de Medicamentos Esenciales para la prevención de la HPP, y a qué dosis?', 'En 2011, a una dosis de 600 µg por vía oral.', 'En 2015, a una dosis de 1.000 µg por vía oral.', 'En 2005, a una dosis de 200 µg por vía oral.', 'En el año 2000, sin especificar dosis', 'A', 'La guía indica en su introducción que en 2011 la Organización Mundial de la Salud agregó al misoprostol (600 µg por vía oral) a su Lista Modelo de Medicamentos Esenciales para la prevención de la HPP.', 'Enfermería - Cuidados de la Mujer, Recién Nacido, Niño y Adolescente', 'GPC MSP Ecuador – Hemorragia posparto 2013'),
  ('9734bbf7-4871-5476-b1f8-d03749996b5b', 'Según el alcance de la GPC del MSP de Ecuador sobre prevención, diagnóstico y tratamiento de la hemorragia posparto, ¿a qué grupo de profesionales está dirigida, incluyendo explícitamente al personal de enfermería?', 'Únicamente a médicos gineco-obstetras de tercer nivel', 'Médicos generales, médicos familiares, médicos gineco-obstetras, anestesiólogos, médicos de emergencia, obstetras, enfermeros y profesionales de equipos de atención prehospitalaria', 'Solo a estudiantes de pregrado en formación, sin aplicación para profesionales en ejercicio', 'Exclusivamente a personal de laboratorio clínico', 'B', 'La guía especifica en su alcance que está dirigida al amplio grupo de profesionales involucrados en la atención directa de salud sexual y reproductiva, embarazo, parto y puerperio, incluyendo explícitamente a médicos generales, médicos familiares, médicos gineco-obstetras, anestesiólogos, médicos de emergencia, obstetras, enfermeros y profesionales de los equipos de atención prehospitalaria.', 'Enfermería - Cuidados de la Mujer, Recién Nacido, Niño y Adolescente', 'GPC MSP Ecuador – Hemorragia posparto 2013'),
  ('e216ce8a-e403-52ae-9466-54045f13943f', 'Según los objetivos específicos de la GPC del MSP de Ecuador sobre prevención, diagnóstico y tratamiento de la hemorragia posparto, ¿con qué énfasis debe describirse la secuencia ordenada de intervenciones eficaces para el tratamiento de la hemorragia posparto?', 'Con énfasis exclusivo en el manejo quirúrgico como primera línea de acción', 'Con énfasis únicamente en la transfusión sanguínea inmediata en todos los casos, sin otras medidas previas', 'Con énfasis en la implementación de medidas de resucitación y el uso adecuado de masaje uterino bimanual y de oxitócicos como primera línea de acción', 'Con énfasis exclusivo en la referencia inmediata sin manejo local previo', 'C', 'Entre los objetivos específicos, la guía plantea describir una secuencia ordenada de intervenciones eficaces para el tratamiento de la hemorragia posparto, con énfasis en la implementación de medidas de resucitación y el uso adecuado de masaje uterino bimanual y de oxitócicos como primera línea de acción.', 'Enfermería - Cuidados de la Mujer, Recién Nacido, Niño y Adolescente', 'GPC MSP Ecuador – Hemorragia posparto 2013'),
  ('e9f65c23-2170-55fa-96a9-9c675c52ce4a', 'Según el glosario de términos del Anexo 6, ¿cómo se define la prevalencia?', 'El número absoluto de casos nuevos diagnosticados en un año determinado', 'La tasa de mortalidad específica de una enfermedad en una población dada', 'El promedio de días de hospitalización por una enfermedad determinada', 'La proporción de individuos de una población que padecen la enfermedad', 'D', 'El Anexo 6 de glosario de términos de la guía define la prevalencia como la proporción de individuos de una población que padecen la enfermedad.', 'Enfermería - Cuidados de la Mujer, Recién Nacido, Niño y Adolescente', 'GPC MSP Ecuador – Hemorragia posparto 2013')
